"""Mechanical help for moving Machine out of reva-vm (saga step local-split-gates).

parse(text) -> list of items; each `impl Machine {` block's methods are split
out with their doc comments and attributes, so methods can be moved to the
core or the block turned into an extension trait.
"""
import re
import sys

FN = re.compile(r'^    (pub(\(crate\))? )?fn (\w+)')


def impl_blocks(lines):
    """(start, end) line indexes of top-level `impl Machine {` blocks."""
    out = []
    i = 0
    while i < len(lines):
        if lines[i].rstrip() == 'impl Machine {':
            j = i + 1
            while lines[j].rstrip() != '}':
                j += 1
            out.append((i, j))
            i = j
        i += 1
    return out


def methods(lines, start, end):
    """Methods inside an impl block: (name, first_line, last_line)."""
    out = []
    i = start + 1
    while i < end:
        m = FN.match(lines[i])
        if m:
            first = i
            while first - 1 > start and (lines[first - 1].startswith('    ///') or lines[first - 1].startswith('    #[')):
                first -= 1
            j = i
            # one-line fn ending with `}`?
            while not (lines[j].rstrip() == '    }' or (j == i and lines[j].rstrip().endswith('}') and '{' in lines[j])):
                j += 1
            out.append((m.group(3), first, j))
            i = j + 1
        else:
            i += 1
    return out


def signature(lines, first, last):
    """The method's doc/attrs and signature as a trait item ending in `;`."""
    out = []
    i = first
    while not FN.match(lines[i]):
        if not lines[i].startswith('    #[inline'):
            out.append(lines[i])
        i += 1
    sig = []
    while True:
        sig.append(lines[i])
        if lines[i].rstrip().endswith('{') or lines[i].rstrip().endswith('}'):
            break
        i += 1
    s = '\n'.join(sig)
    s = re.sub(r'^    pub(\(crate\))? fn', '    fn', s)
    s = s[: s.rindex('{')].rstrip() + ';'
    return '\n'.join(out + [s])


def strip_vis(body_lines):
    return [re.sub(r'^    pub(\(crate\))? fn', '    fn', l) for l in body_lines]


def to_trait(text, trait, doc):
    """Every `impl Machine {` block becomes `impl <trait> for Machine`, and a
    `pub trait <trait>` with all their signatures is inserted before the
    first block."""
    lines = text.split('\n')
    blocks = impl_blocks(lines)
    if not blocks:
        return text
    sigs = []
    for (s, e) in blocks:
        for (_, f, l) in methods(lines, s, e):
            sigs.append(signature(lines, f, l))
    out = []
    first = blocks[0][0]
    for idx, line in enumerate(lines):
        if idx == first:
            out.append(doc)
            out.append(f'pub trait {trait} {{')
            out.append('\n\n'.join(sigs))
            out.append('}')
            out.append('')
        if any(idx == s for (s, _) in blocks):
            out.append(f'impl {trait} for Machine {{')
            continue
        if any(s < idx < e for (s, e) in blocks):
            out.append(re.sub(r'^    pub(\(crate\))? fn', '    fn', line))
        else:
            out.append(line)
    return '\n'.join(out)


def cut_methods(text, names):
    """Remove the named methods from `impl Machine` blocks; return
    (new_text, removed_method_texts) with removed ones made `pub`."""
    lines = text.split('\n')
    removed = []
    drop = set()
    for (s, e) in impl_blocks(lines):
        for (name, f, l) in methods(lines, s, e):
            if name in names:
                chunk = lines[f:l + 1]
                chunk = [re.sub(r'^    (pub\(crate\) )?fn', '    pub fn', x) for x in chunk]
                removed.append('\n'.join(chunk))
                drop.update(range(f, l + 1))
                # a blank line after it goes too
                if l + 1 < len(lines) and lines[l + 1].strip() == '':
                    drop.add(l + 1)
    keep = [x for i, x in enumerate(lines) if i not in drop]
    missing = set(names) - {n for n in names if any(f'fn {n}(' in r for r in removed)}
    if missing:
        sys.exit(f'not found: {missing}')
    return '\n'.join(keep), removed

