    if not blocks:
        return text
    sigs = []
    for (s, e) in blocks:
        for (_, f, l) in methods(lines, s, e):
            sigs.append(signature(lines, f, l))
    out = []
    first = blocks[0][0]
    for idx, line in enumerate(lines):
        if idx == first:
            out.append(doc)
            out.append(f'pub trait {trait} {{')
            out.append('\n\n'.join(sigs))
            out.append('}')
            out.append('')
        if any(idx == s for (s, _) in blocks):
            out.append(f'impl {trait} for Machine {{')
            continue
        if any(s < idx < e for (s, e) in blocks):
            out.append(re.sub(r'^    pub(\(crate\))? fn', '    fn', line))
        else:
            out.append(line)
    return '\n'.join(out)


def cut_methods(text, names):
    """Remove the named methods from `impl Machine` blocks; return
    (new_text, removed_method_texts) with removed ones made `pub`."""
    lines = text.split('\n')
    removed = []
    drop = set()
    for (s, e) in impl_blocks(lines):
        for (name, f, l) in methods(lines, s, e):
            if name in names:
                chunk = lines[f:l + 1]
                chunk = [re.sub(r'^    (pub\(crate\) )?fn', '    pub fn', x) for x in chunk]
                removed.append('\n'.join(chunk))
                drop.update(range(f, l + 1))
                # a blank line after it goes too
                if l + 1 < len(lines) and lines[l + 1].strip() == '':
                    drop.add(l + 1)
    keep = [x for i, x in enumerate(lines) if i not in drop]
    missing = set(names) - {n for n in names if any(f'fn {n}(' in r for r in removed)}
    if missing:
        sys.exit(f'not found: {missing}')
    return '\n'.join(keep), removed

