652	    fn not_implemented(g: Gate) -> Fault {
653	        Fault::NotImplemented(match g {
654	            Gate::MakeExe => "makeexe",
655	            Gate::Syscall => "syscall",
656	            Gate::LzPack => ">lz",
657	            Gate::LzDepack => "lz>",
658	            Gate::LzMax => "lzmax",
659	            Gate::LoadLib => "(lib)",
660	            Gate::UnloadLib => "(-lib)",
661	            Gate::CallFn => "(call)",
662	            Gate::OsFunc => "(func)",
663	            _ => g.name(),
664	        })
