667	    // ---- the dispatcher ------------------------------------------------
668	
669	    fn gate(&mut self, g: Gate, host: &mut dyn Host) -> R<Next> {
670	        use Gate::*;
671	        use Next::{Call, Jump, Ret};
672	        match g {
673	            // --- classes: called with EAX = xt, EDX = dictionary entry ---
674	            FClass | FClassNotail => {
675	                self.setv(st::SSEMI_DO_TAIL, if g == FClass { 0x90 } else { 0xc3 })?;
676	                if self.compiling() {
677	                    let xt = self.upop()?;
678	                    self.compile_call(xt)?;
679	                    Ok(Ret)
680	                } else {
681	                    self.mclass()
682	                }
683	            }
684	            MClass => self.mclass(),
685	            MClassNotail => {
686	                self.setv(st::SSEMI_DO_TAIL, 0xc3)?;
687	                self.mclass()
688	            }
689	            IClass => {
690	                self.setv(st::SSEMI_DO_TAIL, 0xc3)?;
691	                if !self.compiling() {
692	                    return self.mclass();
693	                }
694	                let xt = self.upop()?;
695	                let n = self.mem.read_u8(xt.wrapping_sub(1))? as u32;
696	                self.cpu.r[EDX as usize] = xt;
697	                self.store_here(xt, n)?;
698	                Ok(Ret)
699	            }
700	            CClass => {
701	                // `cclass` has no `ret`: it falls through into `vclass`, so
702	                // while compiling the constant's value becomes a literal.
703	                let v = self.mem.read_u32(self.eax())?;
704	                self.set_eax(v);
705	                if self.compiling() {
706	                    let v = self.upop()?;
707	                    self.compile_literal(v)?;
708	                }
709	                Ok(Ret)
710	            }
711	            VClass => {
712	                if self.compiling() {
713	                    let v = self.upop()?;
714	                    self.compile_literal(v)?;
715	                }
716	                Ok(Ret)
717	            }
718	            ValClass => {
719	                if self.compiling() {
720	                    let v = self.upop()?;
721	                    self.compile_literal(v)?;
722	                    self.compile_call(CClass.addr())?;
723	                } else {
724	                    let v = self.mem.read_u32(self.eax())?;
725	                    self.set_eax(v);
726	                }
727	                Ok(Ret)
728	            }
729	            DoesClass => {
730	                // xt-4 holds the address of the code after `does>`.
731	                self.dup()?;
732	                let code = self.mem.read_u32(self.eax().wrapping_sub(4))?;
733	                self.set_eax(code);
734	                if !self.compiling() {
735	                    return self.mclass();
736	                }
737	                let code = self.upop()?;
738	                let xt = self.upop()?;
739	                self.compile_literal(xt)?;
740	                self.compile_call(code)?;
741	                Ok(Ret)
742	            }
743	            DClass => {
744	                if self.compiling() {
745	                    // call dword [xt]
746	                    let xt = self.upop()?;
747	                    let mut b = [0xff, 0x15, 0, 0, 0, 0];
748	                    b[2..].copy_from_slice(&xt.to_le_bytes());
749	                    self.emit_code(&b)?;
750	                    Ok(Ret)
751	                } else {
752	                    let cell = self.upop()?;
753	                    self.cpu.r[EBX as usize] = cell;
754	                    Ok(Jump(self.mem.read_u32(cell)?))
755	                }
756	            }
757	
758	            // --- default DEFER targets ---
759	            Noop => Ok(Ret),
760	            OsEmit => {
761	                let c = self.upop()?;
762	                host.write(&[c as u8]);
763	                Ok(Ret)
764	            }
765	            OsType => {
766	                // The original passed `n` to write(2); a negative count (as
767	                // `srcstr` yields at the keyboard: `src` is 0 there) made the
768	                // kernel refuse with EFAULT and print nothing.  Same here.
769	                let n = self.upop()?;
770	                let a = self.upop()?;
771	                if n != 0 && (n as i32) > 0 {
772	                    host.write(self.mem.slice(a, n)?);
773	                }
774	                Ok(Ret)
775	            }
776	            OsKey => match self.input.pop_front() {
777	                Some(b) => {
778	                    self.upsh(b as u32)?;
779	                    Ok(Ret)
780	                }
781	                None if self.input_closed => {
782	                    self.upsh(EOF_KEY)?;
783	                    Ok(Ret)
784	                }
785	                None => Ok(Next::NeedInput),
786	            },
787	            OsBye => Ok(Next::Halt(self.eax() as i32)),
788	            Find => {
789	                // ( a n -- entry | a n 0 )
790	                let n = self.upop()?;
791	                let a = self.eax();
792	                let name = self.mem.slice(a, n)?.to_vec();
793	                match self.find_entry(&name) {
794	                    Some(e) => self.set_eax(e),
795	                    None => {
796	                        self.upsh(n)?;
797	                        self.upsh(0)?;
798	                    }
799	                }
800	                Ok(Ret)
801	            }
802	            WordNotFound => {
803	                // ( a n -- 0 ): print "name?" and give up on the token.
804	                self.call_type(host)?;
805	                self.call_emit(host, b'?')?;
806	                self.call_emit(host, b'\n')?;
807	                self.upsh(0)?;
808	                Ok(Ret)
809	            }
810	            HeaderDefault => {
811	                self.header_default(host)?;
812	                Ok(Ret)
813	            }
814	            Hello => {
815	                // `_hello`: include argv[1] if given, then run the REPL.
816	                if self.var(st::ARGC) > 1 {
817	                    let p = self.mem.read_u32(self.var(st::ARGV) + 4)?;
818	                    let n = self.zlen(p)?;
819	                    self.upsh(p)?;
820	                    self.upsh(n)?;
821	                    Ok(Call(Include2.addr(), Repl))
822	                } else {
823	                    Ok(Jump(Repl.addr()))
824	                }
825	            }
826	
827	            // --- startup ---
828	            Cold => {
829	                self.cpu.r[SI] = S0;
830	                self.set_eax(0);
831	                self.setv(st::RP0_SAVED, self.cpu.r[ESP as usize])?;
832	                self.iterate_list(host, OnStartThunk.addr(), st::START_LIST)?;
833	                Ok(Call(self.var(st::APPSTART), ColdDone))
834	            }
835	            BootRestart => {
836	                // reva.f's last step saved a native executable; running that
837	                // executable started with fresh stacks and no source file,
838	                // ran the `onstartup` list (which allocates `scratch`, `pad`
839	                // ...) and then `appstart`.  Do the same in place: drop the
840	                // boot file from argv, abandon the include frames, restart.
841	                // TOS is reva.f's interpreter loop, for fault recovery.
