use crate::layout::*;

macro_rules! gates {
    ($($v:ident),* $(,)?) => {
        #[derive(Clone, Copy, Debug, PartialEq, Eq)]
        #[repr(u16)]
        pub enum Gate { $($v),* }
        impl Gate {
