1	//! # Gateways: the `newcore.asm` routines, in Rust
2	//!
3	//! Each [`Gate`] occupies one 4-byte slot in the gateway region.  Forth code
4	//! reaches it exactly as it reached the assembly routine (`call`, `jmp`,
5	//! `call [vector]`), and the routine sees the same registers: EAX = TOS,
6	//! ESI = data stack, ESP = return stack, EDX = dictionary entry for class
7	//! handlers.
8	//!
9	//! Comments name the original routine (`PROC xyz` in `src/newcore.asm`) and
10	//! call out every place where behaviour deliberately differs.
11	//!
12	//! Routines that must call back into Forth (the outer interpreter, `eval`,
13	//! `include`, `catch`, `:` via the `(header)` vector) are split into a head
14	//! and continuation gateways, so the VM never holds Forth state on the Rust
15	//! stack and can pause for input anywhere (see [`crate::machine`]).
16	
17	use crate::Gate;
18	use crate::fault::Fault;
19	use crate::ffi::Ffi;
20	use crate::fileio::FileIo;
21	use crate::host::Host;
22	use crate::layout::*;
23	use crate::machine::{Next, st};
24	use crate::vfs::Access;
25	use crate::x86::{EBX, EDI, EDX, ESI, ESP};
26	
27	const SI: usize = ESI as usize;
28	const BASES: [u32; 5] = [10, 16, 2, 8, 255]; // prefixes # $ % & '
29	const DIGITS: &[u8; 16] = b"0123456789ABCDEF";
30	
31	fn digit_value(c: u32, base: u32) -> Option<u32> {
32	    let v = match c {
33	        0x30..=0x39 => c - 0x30,
34	        0x41..=0x5a => c - 0x41 + 10,
35	        0x61..=0x7a => c - 0x61 + 10,
36	        _ => return None,
37	    };
38	    (v < base).then_some(v)
39	}
40	
41	/// Result of a gateway helper.
42	type R<T = ()> = Result<T, Fault>;
43	
44	reva_macros::machine_trait! {
45	    /// The gateway routines, as methods of the machine (reva-core's `Machine`).
46	    pub trait Words: Ffi, FileIo {
47	        // ---- register / stack helpers (the upsh/upop/drop macros) ---------
48	
49	        // ---- code generation (compile, literal, comma, align) -------------
50	
51	        fn reserve_code(&self, n: u32) -> R<u32> {
52	            let h = self.here();
53	            if h.checked_add(n).is_none_or(|e| e > HTOP) {
54	                return Err(Fault::OutOfSpace("code"));
55	            }
56	            Ok(h)
57	    }
58	
59	    fn emit_code(&mut self, bytes: &[u8]) -> R {
60	        let h = self.reserve_code(bytes.len() as u32)?;

640	                _ => {}
641	            }
642	        }
643	        Ok(Next::Jump(Gate::InterpWord.addr()))
644	    }
645	
646	    fn mclass(&mut self) -> R<Next> {
647	        let xt = self.upop()?;
648	        self.cpu.r[EBX as usize] = xt;
649	        Ok(Next::Jump(xt))
650	    }
651	
652	    fn not_implemented(g: Gate) -> Fault {
653	        Fault::NotImplemented(match g {
654	            Gate::MakeExe => "makeexe",
655	            Gate::Syscall => "syscall",
656	            Gate::LzPack => ">lz",
657	            Gate::LzDepack => "lz>",
658	            Gate::LzMax => "lzmax",
659	            Gate::LoadLib => "(lib)",
660	            Gate::UnloadLib => "(-lib)",
661	            Gate::CallFn => "(call)",
662	            Gate::OsFunc => "(func)",
663	            _ => g.name(),
664	        })
665	    }
666	
667	    // ---- the dispatcher ------------------------------------------------
668	
669	    fn gate(&mut self, g: Gate, host: &mut dyn Host) -> R<Next> {
670	        use Gate::*;
671	        use Next::{Call, Jump, Ret};
672	        match g {
673	            // --- classes: called with EAX = xt, EDX = dictionary entry ---
674	            FClass | FClassNotail => {
675	                self.setv(st::SSEMI_DO_TAIL, if g == FClass { 0x90 } else { 0xc3 })?;
676	                if self.compiling() {
677	                    let xt = self.upop()?;
678	                    self.compile_call(xt)?;
679	                    Ok(Ret)
680	                } else {
681	                    self.mclass()
682	                }
683	            }
684	            MClass => self.mclass(),
685	            MClassNotail => {
686	                self.setv(st::SSEMI_DO_TAIL, 0xc3)?;
687	                self.mclass()
688	            }
689	            IClass => {
690	                self.setv(st::SSEMI_DO_TAIL, 0xc3)?;
691	                if !self.compiling() {
692	                    return self.mclass();
693	                }
694	                let xt = self.upop()?;
695	                let n = self.mem.read_u8(xt.wrapping_sub(1))? as u32;
696	                self.cpu.r[EDX as usize] = xt;
697	                self.store_here(xt, n)?;
698	                Ok(Ret)
699	            }
700	            CClass => {
701	                // `cclass` has no `ret`: it falls through into `vclass`, so
702	                // while compiling the constant's value becomes a literal.
703	                let v = self.mem.read_u32(self.eax())?;
704	                self.set_eax(v);
705	                if self.compiling() {
706	                    let v = self.upop()?;
707	                    self.compile_literal(v)?;
708	                }
709	                Ok(Ret)
710	            }
711	            VClass => {
712	                if self.compiling() {
713	                    let v = self.upop()?;
714	                    self.compile_literal(v)?;
715	                }
716	                Ok(Ret)
717	            }
718	            ValClass => {
719	                if self.compiling() {
720	                    let v = self.upop()?;
721	                    self.compile_literal(v)?;
722	                    self.compile_call(CClass.addr())?;
723	                } else {
724	                    let v = self.mem.read_u32(self.eax())?;
725	                    self.set_eax(v);
726	                }
727	                Ok(Ret)
728	            }
729	            DoesClass => {
730	                // xt-4 holds the address of the code after `does>`.
731	                self.dup()?;
732	                let code = self.mem.read_u32(self.eax().wrapping_sub(4))?;
733	                self.set_eax(code);
734	                if !self.compiling() {
735	                    return self.mclass();
736	                }
737	                let code = self.upop()?;
738	                let xt = self.upop()?;
739	                self.compile_literal(xt)?;
740	                self.compile_call(code)?;
741	                Ok(Ret)
742	            }
743	            DClass => {
744	                if self.compiling() {
745	                    // call dword [xt]
746	                    let xt = self.upop()?;
747	                    let mut b = [0xff, 0x15, 0, 0, 0, 0];
748	                    b[2..].copy_from_slice(&xt.to_le_bytes());
749	                    self.emit_code(&b)?;
750	                    Ok(Ret)
751	                } else {
752	                    let cell = self.upop()?;
753	                    self.cpu.r[EBX as usize] = cell;
754	                    Ok(Jump(self.mem.read_u32(cell)?))
755	                }
756	            }
757	
758	            // --- default DEFER targets ---
759	            Noop => Ok(Ret),
760	            OsEmit => {
761	                let c = self.upop()?;
762	                host.write(&[c as u8]);
763	                Ok(Ret)
764	            }
765	            OsType => {
766	                // The original passed `n` to write(2); a negative count (as
767	                // `srcstr` yields at the keyboard: `src` is 0 there) made the
768	                // kernel refuse with EFAULT and print nothing.  Same here.
769	                let n = self.upop()?;
770	                let a = self.upop()?;
771	                if n != 0 && (n as i32) > 0 {
772	                    host.write(self.mem.slice(a, n)?);
773	                }
774	                Ok(Ret)
775	            }
776	            OsKey => match self.input.pop_front() {
777	                Some(b) => {
778	                    self.upsh(b as u32)?;
779	                    Ok(Ret)
780	                }
781	                None if self.input_closed => {
782	                    self.upsh(EOF_KEY)?;
783	                    Ok(Ret)
784	                }
785	                None => Ok(Next::NeedInput),
