167	        d += size;
168	        self.mem.write_u8(d, 0xc3)?;
169	        self.setv(st::D, d + 1)?;
170	        self.setv(st::H, lasth)?;
171	        let entry = self.mem.read_u32(self.var(st::LAST))?;
172	        self.mem
173	            .write_u32(entry.wrapping_sub(4), Gate::IClass.addr())?;
174	        self.mem.write_u32(entry + 4, xt)?;
175	        self.lbracket()
176	    }
