178	    /// `PROC __header` ( a n -- ): create a dictionary entry
179	    /// `[class][link][xt][count][name...]` for the word about to be compiled
180	    /// at `here`, remembering enough to undo it if compilation fails.
181	    fn header_default(&mut self, host: &mut dyn Host) -> R {
182	        self.setv(st::DIDHEADER, 1)?;
183	        self.align_code()?;
184	        let d = (self.var(st::D) + 3) & !3;
185	        self.setv(st::LASTH, self.here())?;
186	        self.setv(st::LASTD, d)?;
187	        let lastp = self.var(st::LAST);
188	        let prev = self.mem.read_u32(lastp)?;
189	        self.setv(st::LASTL, prev)?;
190	        let n = self.upop()?;
191	        let a = self.upop()?;
192	        if d.checked_add(13 + n).is_none_or(|e| e > DTOP) {
193	            let v = self.var(st::DICTGONE);
194	            if v != Gate::OsBye.addr() {
195	                return self.call_nested(host, v);
196	            }
197	            return Err(Fault::OutOfSpace("dictionary"));
198	        }
199	        let entry = d + 4;
200	        self.mem.write_u32(d, self.var(st::DEFAULT_CLASS))?;
201	        self.mem.write_u32(lastp, entry)?;
202	        self.mem.write_u32(entry, prev)?;
203	        self.mem.write_u32(entry + 4, self.here())?;
204	        self.mem.write_u8(entry + 8, n as u8)?;
205	        self.mem.move_forward(a, entry + 9, n)?;
206	        self.setv(st::D, entry + 9 + n)
207	    }
