211	    /// Run a DEFER vector that takes no arguments, skipping it when it still
212	    /// points at `noop` (the common case, and the cheap one).
213	    fn call_vector(&mut self, host: &mut dyn Host, cell: u32) -> R {
214	        let t = self.var(cell);
