221	    /// `PROC parsews`: skip blanks (9..=32), return the next word.  Each
222	    /// newline crossed runs the `do_cr` vector (line counting in `include`).
223	    fn parsews(&mut self, host: &mut dyn Host) -> R<(u32, u32)> {
224	        let end = self.var(st::TP);
225	        let mut p = self.var(st::TIN);
226	        let blank = |c: u8| (9..=32).contains(&c);
227	        while p < end {
228	            let c = self.mem.read_u8(p)?;
229	            if c == b'\n' {
230	                p += 1;
231	                self.setv(st::TIN, p)?;
232	                self.call_vector(host, st::DO_CR)?;
233	                continue;
234	            }
235	            if !blank(c) {
236	                break;
237	            }
238	            p += 1;
239	        }
240	        let start = p;
241	        while p < end && !blank(self.mem.read_u8(p)?) {
242	            p += 1;
243	        }
244	        let len = p - start;
245	        if p < end {
246	            let nl = self.mem.read_u8(p)? == b'\n';
247	            p += 1;
248	            self.setv(st::TIN, p)?;
249	            if nl {
250	                self.call_vector(host, st::DO_CR)?;
251	            }
252	        } else {
253	            self.setv(st::TIN, p)?;
254	        }
255	        Ok((start, len))
256	    }
