385	    /// `PROC _printr` (`(.r)`) ( n width -- a n ): format `n` in `base`
386	    /// (signed only in base 10), right-aligned with `padchar`.
387	    fn print_r(&mut self) -> R {
388	        let width = self.upop()? & 255;
389	        let n = self.eax();
390	        let base = self.var(st::BASE);
391	        if base < 2 {
392	            return Err(Fault::DivideError { eip: self.cpu.eip });
393	        }
394	        let neg = base == 10 && (n as i32) < 0;
395	        let mut v = if neg { n.wrapping_neg() } else { n };
396	        let mut p = NPAD;
397	        loop {
398	            let mut c = (v % base) as u8 + b'0';
399	            if c > b'9' {
400	                c += 7;
401	            }
402	            v /= base;
403	            p -= 1;
404	            self.mem.write_u8(p, c)?;
405	            if v == 0 {
406	                break;
407	            }
408	        }
409	        if neg {
410	            p -= 1;
411	            self.mem.write_u8(p, b'-')?;
412	        }
413	        let mut len = NPAD - p;
414	        if width > len {
415	            let pad = self.var(st::PADCHAR) as u8;
416	            for _ in len..width {
417	                p -= 1;
418	                self.mem.write_u8(p, pad)?;
419	            }
420	            len = width;
421	        }
422	        self.set_eax(p);
423	        self.upsh(len)
424	    }
