434	    /// `compare_common` + `PROC compare`/`comparei` ( a1 n1 a2 n2 -- r ).
435	    fn compare(&mut self, fold: bool) -> R {
436	        let n2 = self.upop()?;
437	        let a2 = self.upop()?;
438	        let n1 = self.upop()?;
439	        let a1 = self.eax();
440	        let r: i32 = if n1 == 0 || a1 == 0 || n2 == 0 || a2 == 0 {
441	            match (n1 as i32).cmp(&(n2 as i32)) {
442	                std::cmp::Ordering::Equal => 0,
443	                std::cmp::Ordering::Greater => 1,
444	                std::cmp::Ordering::Less => -1,
445	            }
446	        } else {
447	            let len = (n1 as i32).min(n2 as i32) as u32;
448	            let (s1, s2) = (self.mem.slice(a1, len)?, self.mem.slice(a2, len)?);
449	            let f = |c: u8| if fold { c.to_ascii_lowercase() } else { c };
450	            match s1.iter().zip(s2).find(|(x, y)| f(**x) != f(**y)) {
451	                Some((x, y)) => f(*x).wrapping_sub(f(*y)) as i8 as i32,
452	                None => n1.wrapping_sub(n2) as i32,
453	            }
454	        };
455	        self.set_eax(r as u32);
456	        Ok(())
457	    }
