562	    fn resize(&mut self) -> R {
563	        let n = self.upop()?;
564	        let a = self.eax();
565	        let new = if a == 0 {
566	            self.heap.alloc(n)
567	        } else {
568	            match self.heap.size_of(a) {
569	                Some(old) => {
570	                    let new = self.heap.alloc(n);
571	                    if let Some(p) = new {
572	                        self.mem.move_forward(a, p, old.min(n))?;
573	                        self.heap.free(a);
574	                    }
575	                    new
576	                }
577	                None => None,
578	            }
579	        };
580	        self.set_eax(new.unwrap_or(0));
581	        self.setv(st::IOR, new.is_none() as u32)
582	    }
