#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn tm_known_dates() {
        assert_eq!(tm_from_unix(0), [0, 0, 0, 1, 0, 70, 4, 0, 0]);
        // 2000-02-29 12:34:56 UTC, a Tuesday, day 59 of a leap year
        assert_eq!(
