    fn sys_file(&mut self, host: &mut dyn Host, num: u32, a: &[u32; 6]) -> R<Option<u32>> {
        let r = match num {
            SYS_READ => self.sys_read(host, a[0], a[1], a[2])?,
            SYS_WRITE => self.sys_write(host, a[0], a[1], a[2])?,
