//! Digits, signs and base prefixes of Reva's number syntax.

/// The bases of the prefixes `#` `$` `%` `&` (and `'`, a character).
const BASES: [u32; 5] = [10, 16, 2, 8, 255];
const DIGITS: &[u8; 16] = b"0123456789ABCDEF";

/// What follows a number's sign.
#[derive(Debug, PartialEq, Eq)]
pub enum Prefix<'a> {
    /// `'c`: the character's code.
    Char(u32),
    /// Digits in a base (a prefix's, or the current one).
    Digits(u32, &'a [u8]),
}

/// The value of digit `c` (`0-9`, `A-Z`, `a-z`) if it is below `base`.
pub fn digit_value(c: u32, base: u32) -> Option<u32> {
    let v = match c {
        0x30..=0x39 => c - 0x30,
        0x41..=0x5a => c - 0x41 + 10,
        0x61..=0x7a => c - 0x61 + 10,
        _ => return None,
    };
    (v < base).then_some(v)
}

/// A leading `-` and the rest; `None` for an empty number or a lone `-`.
pub fn sign_split(s: &[u8]) -> Option<(bool, &[u8])> {
    match s.split_first()? {
        (b'-', []) => None,
        (b'-', rest) => Some((true, rest)),
        _ => Some((false, s)),
    }
}

/// A base prefix (`#$%&`, and `'` when `with_char`), or the digits as
/// they are; `None` when a prefix has nothing after it.
pub fn number_prefix(s: &[u8], base: u32, with_char: bool) -> Option<Prefix<'_>> {
    let top = if with_char { b'\'' } else { b'&' };
    if !(b'#'..=top).contains(&s[0]) {
        return Some(Prefix::Digits(base, s));
    }
    let k = (s[0] - b'#') as usize;
    if k == 4 {
        return s.get(1).map(|&c| Prefix::Char(c as u32));
    }
    let rest = &s[1..];
    (!rest.is_empty()).then_some(Prefix::Digits(BASES[k], rest))
}

/// `PROC todigit` (`>digit`): the digit for `n`; `None` (a divide error)
/// when `n` is 16 or more and the base is 0.
pub fn to_digit(n: u32, base: u32) -> Option<u32> {
    if n < 16 {
        return Some(DIGITS[n as usize] as u32);
    }
    if base == 0 {
        return None;
    }
    let c = n % base + 0x30;
    Some(if c > 0x39 { c + 39 } else { c })
}
EOF
cat > number.rs <<'EOF'
//! `single`, `double` and `(.r)`: numbers to and from text.

use crate::digits::{Prefix, digit_value, number_prefix, sign_split};

/// `PROC single`: `[-][#$%&]digits` or `'c`, in `base`.  Overflow is not
/// a number, as in the original (`jo .err`).
pub fn parse_single(s: &[u8], base: u32) -> Option<u32> {
    let (neg, rest) = sign_split(s)?;
    let sign = |v: u32| if neg { v.wrapping_neg() } else { v };
    match number_prefix(rest, base, true)? {
        Prefix::Char(c) => Some(sign(c)),
        Prefix::Digits(base, digits) => single_digits(digits, base).map(sign),
    }
}

/// The digits of a single: 32-bit, a signed overflow fails.
pub fn single_digits(digits: &[u8], base: u32) -> Option<u32> {
    digits.iter().try_fold(0u32, |acc, &c| {
        let d = digit_value(c as u32, base)?;
        let full = acc as u64 * base as u64;
        if full > u32::MAX as u64 {
            return None;
        }
        let (sum, overflow) = (full as u32 as i32).overflowing_add(d as i32);
        (!overflow).then_some(sum as u32)
    })
}

/// `PROC double`: like `single` with a trailing `L`; `.` and `,` are
/// ignored as separators; 64-bit wrap-around.  Low and high cells.
pub fn parse_double(s: &[u8], base: u32) -> Option<(u32, u32)> {
    let s = s.strip_suffix(b"L").filter(|s| !s.is_empty())?;
    let (neg, rest) = sign_split(s)?;
    let Prefix::Digits(base, digits) = number_prefix(rest, base, false)? else {
        return None;
    };
    let v = double_digits(digits, base)?;
    let v = if neg { v.wrapping_neg() } else { v };
    Some((v as u32, (v >> 32) as u32))
}

/// The digits of a double, skipping `.` and `,`.
pub fn double_digits(digits: &[u8], base: u32) -> Option<u64> {
    digits
        .iter()
        .filter(|&&c| c != b'.' && c != b',')
        .try_fold(0u64, |acc, &c| {
            let d = digit_value(c as u32, base)?;
            Some(acc.wrapping_mul(base as u64).wrapping_add(d as u64))
        })
}

/// `PROC _printr` (`(.r)`): `n` in `base` (2 or more; signed only in base
/// 10), right-aligned to `width` with `pad`.
pub fn format_r(n: u32, base: u32, width: u32, pad: u8) -> Vec<u8> {
    let neg = base == 10 && (n as i32) < 0;
    let mut v = if neg { n.wrapping_neg() } else { n };
    let mut out = Vec::new();
    loop {
        let mut c = (v % base) as u8 + b'0';
        if c > b'9' {
            c += 7;
        }
        out.push(c);
        v /= base;
        if v == 0 {
            break;
        }
    }
    if neg {
        out.push(b'-');
    }
    out.resize(out.len().max(width as usize), pad);
    out.reverse();
    out
}
EOF
cat > compare.rs <<'EOF'
//! `compare`, `comparei` and `fnvhash` over byte strings.

/// The order of two lengths, as `compare` gives it for empty strings.
pub fn length_order(n1: u32, n2: u32) -> i32 {
    match (n1 as i32).cmp(&(n2 as i32)) {
        std::cmp::Ordering::Equal => 0,
        std::cmp::Ordering::Greater => 1,
        std::cmp::Ordering::Less => -1,
    }
}

/// The difference of the first bytes that differ (case-folded when
/// `fold`), or `None` when the strings agree.
pub fn first_difference(s1: &[u8], s2: &[u8], fold: bool) -> Option<i32> {
    let f = |c: u8| if fold { c.to_ascii_lowercase() } else { c };
    s1.iter()
        .zip(s2)
        .find(|(x, y)| f(**x) != f(**y))
        .map(|(x, y)| f(*x).wrapping_sub(f(*y)) as i8 as i32)
}

/// `PROC fnvhash`: 32-bit FNV-1a; the offset basis for an empty string.
pub fn fnv_hash(bytes: &[u8]) -> u32 {
    bytes.iter().fold(2_166_136_261, |h: u32, &b| {
        (h ^ b as u32).wrapping_mul(16_777_619)
    })
}
EOF
cat > ../tests/text_tests.rs <<'EOF'
use reva_words_text::compare::{first_difference, fnv_hash, length_order};
use reva_words_text::digits::{digit_value, to_digit};
use reva_words_text::number::{format_r, parse_double, parse_single};

#[test]
fn digits() {
    assert_eq!(digit_value(b'7' as u32, 10), Some(7));
    assert_eq!(digit_value(b'f' as u32, 16), Some(15));
    assert_eq!(digit_value(b'F' as u32, 16), Some(15));
    assert_eq!(digit_value(b'9' as u32, 8), None);
    assert_eq!(digit_value(b'@' as u32, 36), None);
    assert_eq!(to_digit(11, 10), Some(b'B' as u32));
    assert_eq!(to_digit(20, 0), None);
}

#[test]
fn singles() {
    assert_eq!(parse_single(b"42", 10), Some(42));
    assert_eq!(parse_single(b"-$ff", 10), Some(0xffu32.wrapping_neg()));
    assert_eq!(parse_single(b"'A", 10), Some(65));
    assert_eq!(parse_single(b"'", 10), None);
    assert_eq!(parse_single(b"-", 10), None);
    assert_eq!(parse_single(b"#", 16), None);
    assert_eq!(parse_single(b"2147483648", 10), None);
    assert_eq!(parse_single(b"12x", 10), None);
}

#[test]
fn doubles() {
    assert_eq!(parse_double(b"1,000L", 10), Some((1000, 0)));
    assert_eq!(parse_double(b"-1L", 10), Some((u32::MAX, u32::MAX)));
    assert_eq!(parse_double(b"$100000000L", 10), Some((0, 1)));
    assert_eq!(parse_double(b"L", 10), None);
    assert_eq!(parse_double(b"'AL", 10), None);
    assert_eq!(parse_double(b"12", 10), None);
}

#[test]
fn formats() {
    assert_eq!(format_r(42, 10, 0, b' '), b"42");
    assert_eq!(format_r(-5i32 as u32, 10, 4, b' '), b"  -5");
    assert_eq!(format_r(255, 16, 4, b'0'), b"00FF");
}

#[test]
fn comparisons() {
    assert_eq!(length_order(2, 3), -1);
    assert_eq!(first_difference(b"abc", b"abd", false), Some(-1));
    assert_eq!(first_difference(b"ABC", b"abc", true), None);
    assert_eq!(fnv_hash(b""), 2_166_136_261);
}
