        0x70..=0x7f => Op::Jcc {
            cc: b & 15,
            target: c.rel8()?,
        },
        0x80 | 0x81 | 0x83 => {
            let size = if b == 0x80 { Size::B } else { osz };
            let (r, rm) = c.modrm()?;
            let imm = match b {
                0x80 => c.imm(Size::B)?,
                0x81 => c.imm(osz)?,
                _ => c.i8()?,
            };
            Op::Alu {
                op: ALU[r as usize],
                size,
                dst: rm,
                src: Opd::Imm(imm),
            }
        }
        0x84 | 0x85 => {
            let size = if b == 0x84 { Size::B } else { osz };
            let (r, rm) = c.modrm()?;
            Op::Test {
                size,
                a: rm,
                b: Opd::Reg(r),
            }
        }
        0x86 | 0x87 => {
            let size = if b == 0x86 { Size::B } else { osz };
            let (r, rm) = c.modrm()?;
            Op::Xchg {
                size,
                a: rm,
                b: Opd::Reg(r),
            }
        }
        0x88..=0x8b => {
            let size = if b & 1 == 0 { Size::B } else { osz };
            let (r, rm) = c.modrm()?;
            if b & 2 == 0 {
                Op::Mov {
                    size,
                    dst: rm,
                    src: Opd::Reg(r),
                }
            } else {
                Op::Mov {
                    size,
                    dst: Opd::Reg(r),
                    src: rm,
                }
            }
        }
        0x8d => match c.modrm()? {
            (r, Opd::Mem(m)) => Op::Lea { dst: r, mem: m },
            _ => return Err(c.bad()),
        },
        0x8f => match c.modrm()? {
            (0, rm) => Op::Pop(rm),
            _ => return Err(c.bad()),
        },
        0x90 => Op::Nop,
        // fwait: exceptions are masked, so there is nothing to wait for
        0x9b => Op::Nop,
        0xd8..=0xdf => Op::Fpu(fpu_op(&mut c, b)?),
        0x91..=0x97 => Op::Xchg {
            size: osz,
            a: Opd::Reg(EAX),
            b: Opd::Reg(b - 0x90),
        },
        0x98 if osz == Size::D => Op::Cwde,
        0x99 if osz == Size::D => Op::Cdq,
        0x98 => Op::Cbw,
        0x99 => Op::Cwd,
        // mov AL/EAX <-> [moffs32] (lib/util/locals emits a3)
        0xa0..=0xa3 => {
            let size = if b & 1 == 0 { Size::B } else { osz };
            let m = Opd::Mem(MemRef {
                base: None,
                index: None,
                scale: 1,
                disp: c.u32()?,
            });
            if b & 2 == 0 {
                Op::Mov {
                    size,
                    dst: Opd::Reg(EAX),
                    src: m,
                }
            } else {
                Op::Mov {
                    size,
                    dst: m,
                    src: Opd::Reg(EAX),
                }
            }
        }
        0xa4..=0xa7 | 0xaa..=0xaf => {
            let size = if b & 1 == 0 { Size::B } else { osz };
            let op = match b & !1 {
                0xa4 => StrOp::Movs,
                0xa6 => StrOp::Cmps,
                0xaa => StrOp::Stos,
                0xac => StrOp::Lods,
                _ => StrOp::Scas,
            };
            Op::Str { op, size, rep }
        }
        0xa8 => Op::Test {
            size: Size::B,
            a: Opd::Reg(EAX),
            b: Opd::Imm(c.imm(Size::B)?),
        },
        0xa9 => Op::Test {
            size: osz,
            a: Opd::Reg(EAX),
            b: Opd::Imm(c.imm(osz)?),
        },
        0xb0..=0xb7 => Op::Mov {
            size: Size::B,
            dst: Opd::Reg(b - 0xb0),
            src: Opd::Imm(c.imm(Size::B)?),
        },
        0xb8..=0xbf => Op::Mov {
            size: osz,
            dst: Opd::Reg(b - 0xb8),
            src: Opd::Imm(c.imm(osz)?),
        },
        0xc0 | 0xc1 | 0xd0..=0xd3 => {
            let size = if b & 1 == 0 { Size::B } else { osz };
            let (r, rm) = c.modrm()?;
            let count = match b {
                0xc0 | 0xc1 => Opd::Imm(c.u8()? as u32),
                0xd0 | 0xd1 => Opd::Imm(1),
                _ => Opd::Reg(ECX), // CL
            };
            Op::Shift {
                op: SHIFT[r as usize],
                size,
                dst: rm,
                count,
            }
        }
        0xc2 => Op::Ret(c.u16()?),
        0xc3 => Op::Ret(0),
        0xc6 | 0xc7 => {
            let size = if b == 0xc6 { Size::B } else { osz };
            match c.modrm()? {
                (0, rm) => Op::Mov {
                    size,
                    dst: rm,
                    src: Opd::Imm(c.imm(size)?),
                },
                _ => return Err(c.bad()),
            }
        }
        0xcc => Op::Int3,
        0xe0..=0xe3 => {
            let kind = match b {
                0xe0 => LoopKind::Loopne,
                0xe1 => LoopKind::Loope,
                0xe2 => LoopKind::Loop,
                _ => LoopKind::Jecxz,
            };
            Op::Loop {
                kind,
                target: c.rel8()?,
            }
        }
        0xe8 => Op::Call(c.rel32()?),
        0xe9 => Op::Jmp(c.rel32()?),
        0xeb => Op::Jmp(c.rel8()?),
        0xf4 => Op::Hlt,
        0xf5 => Op::Flag(FlagOp::Cmc),
        0xf6 | 0xf7 => {
            let size = if b == 0xf6 { Size::B } else { osz };
            let (r, rm) = c.modrm()?;
            match r {
                0 | 1 => Op::Test {
                    size,
                    a: rm,
                    b: Opd::Imm(c.imm(size)?),
                },
                2 => Op::Not { size, dst: rm },
                3 => Op::Neg { size, dst: rm },
                4 => Op::MulDiv {
                    op: MulDiv::Mul,
                    size,
                    src: rm,
                },
                5 => Op::MulDiv {
                    op: MulDiv::Imul,
                    size,
                    src: rm,
                },
                6 => Op::MulDiv {
                    op: MulDiv::Div,
                    size,
                    src: rm,
                },
                _ => Op::MulDiv {
                    op: MulDiv::Idiv,
                    size,
                    src: rm,
                },
            }
        }
        0xf8 => Op::Flag(FlagOp::Clc),
        0xf9 => Op::Flag(FlagOp::Stc),
        0xfc => Op::Flag(FlagOp::Cld),
        0xfd => Op::Flag(FlagOp::Std),
        0xfe => match c.modrm()? {
            (0, rm) => Op::Inc {
                size: Size::B,
                dst: rm,
            },
            (1, rm) => Op::Dec {
                size: Size::B,
                dst: rm,
            },
            _ => return Err(c.bad()),
        },
        0xff => match c.modrm()? {
            (0, rm) => Op::Inc { size: osz, dst: rm },
            (1, rm) => Op::Dec { size: osz, dst: rm },
            (2, rm) => Op::CallInd(rm),
            (4, rm) => Op::JmpInd(rm),
            (6, rm) => Op::Push(rm),
            _ => return Err(c.bad()),
        },
        0x0f => {
            let b2 = c.u8()?;
            match b2 {
                0x80..=0x8f => Op::Jcc {
                    cc: b2 & 15,
                    target: c.rel32()?,
                },
                0x90..=0x9f => Op::Setcc {
                    cc: b2 & 15,
                    dst: c.modrm()?.1,
                },
                0x40..=0x4f if osz == Size::D => {
                    let (r, rm) = c.modrm()?;
                    Op::Cmovcc {
                        cc: b2 & 15,
                        dst: r,
                        src: rm,
                    }
                }
                0xaf if osz == Size::D => {
                    let (r, rm) = c.modrm()?;
                    Op::Imul {
                        dst: r,
                        src: rm,
                        imm: None,
                    }
                }
                0xc8..=0xcf if osz == Size::D => Op::Bswap(b2 & 7),
                0xb6 | 0xb7 | 0xbe | 0xbf => {
                    let (r, rm) = c.modrm()?;
                    let from = if b2 & 1 == 0 { Size::B } else { Size::W };
                    Op::Movx {
                        signed: b2 >= 0xbe,
                        from,
                        dst: r,
                        src: rm,
                    }
                }
                _ => return Err(c.bad()),
            }
        }
        _ => return Err(c.bad()),
    };
    let len = c.pos.wrapping_sub(eip);
    if len > 15 {
        return Err(c.bad());
    }
    Ok(Insn { op, len: len as u8 })
}

