145	// status word bits
146	const IE: u16 = 0x0001;
147	const ZE: u16 = 0x0004;
148	const SF: u16 = 0x0040;
149	const C0: u16 = 0x0100;
150	const C1: u16 = 0x0200;
151	const C2: u16 = 0x0400;
152	const C3: u16 = 0x4000;
153	const CC: u16 = C0 | C1 | C2 | C3;
154	const TOP_SHIFT: u16 = 11;
155	
156	/// The value an invalid operation produces with exceptions masked.
157	const INDEFINITE: f64 = -f64::NAN; // 0xfff8_0000_0000_0000
158	/// `fninit`'s control word: all exceptions masked, extended precision,
159	/// round to nearest.
160	const CW_INIT: u16 = 0x037f;
161	
162	/// The x87 state.
163	#[derive(Clone, Debug)]
164	pub struct Fpu {
165	    /// Physical registers R0..R7; `st(i)` is `regs[(top + i) & 7]`.
166	    pub regs: [f64; 8],
167	    pub top: u8,
168	    /// Bit `n` set: `regs[n]` holds a value (else its tag is "empty").
169	    pub valid: u8,
170	    pub cw: u16,
171	    /// Status word without the `TOP` field (see [`Fpu::status`]).
172	    pub sw: u16,
173	}
174	
175	impl Default for Fpu {
176	    fn default() -> Fpu {
177	        Fpu {
178	            regs: [0.0; 8],
179	            top: 0,
180	            valid: 0,
181	            cw: CW_INIT,
182	            sw: 0,
183	        }
184	    }
185	}
186	
187	impl PartialEq for Fpu {
188	    fn eq(&self, o: &Fpu) -> bool {
189	        self.regs.map(f64::to_bits) == o.regs.map(f64::to_bits)
190	            && (self.top, self.valid, self.cw, self.sw) == (o.top, o.valid, o.cw, o.sw)
191	    }
192	}
193	
194	impl Eq for Fpu {}
195	
196	impl Fpu {
197	    fn phys(&self, i: u8) -> usize {
198	        ((self.top + i) & 7) as usize
199	    }
200	
201	    pub fn is_empty(&self, i: u8) -> bool {
202	        self.valid & (1 << self.phys(i)) == 0
203	    }
204	
205	    /// `st(i)`; an empty register is a stack underflow: invalid operation,
206	    /// and the indefinite NaN as the value.
207	    pub fn st(&mut self, i: u8) -> f64 {
208	        if self.is_empty(i) {
209	            self.sw = (self.sw & !C1) | IE | SF;
210	            return INDEFINITE;
211	        }
212	        self.regs[self.phys(i)]
213	    }
214	
215	    pub fn set(&mut self, i: u8, v: f64) {
216	        let p = self.phys(i);
217	        self.regs[p] = v;
218	        self.valid |= 1 << p;
219	    }
220	
221	    /// Push; onto a full stack this is an overflow (the value becomes the
222	    /// indefinite NaN), as the x87 does with exceptions masked.
223	    pub fn push(&mut self, v: f64) {
224	        self.top = (self.top + 7) & 7;
225	        if !self.is_empty(0) {
226	            self.sw |= IE | SF | C1;
227	            self.set(0, INDEFINITE);
228	        } else {
229	            self.set(0, v);
230	        }
231	    }
232	
233	    pub fn pop(&mut self) {
234	        self.valid &= !(1 << self.phys(0));
235	        self.top = (self.top + 1) & 7;
236	    }
237	
238	    /// The status word as `fnstsw` stores it.
239	    pub fn status(&self) -> u16 {
240	        (self.sw & !(7 << TOP_SHIFT)) | (u16::from(self.top) << TOP_SHIFT)
241	    }
242	
243	    fn set_cc(&mut self, c3: bool, c2: bool, c1: bool, c0: bool) {
244	        self.sw &= !CC;
245	        for (on, bit) in [(c3, C3), (c2, C2), (c1, C1), (c0, C0)] {
246	            if on {
247	                self.sw |= bit;
248	            }
249	        }
250	    }
251	
252	    /// Round to an integer as the control word's RC field says.
253	    fn round(&self, v: f64) -> f64 {
254	        match (self.cw >> 10) & 3 {
255	            0 => v.round_ties_even(),
256	            1 => v.floor(),
257	            2 => v.ceil(),
258	            _ => v.trunc(),
259	        }
260	    }
261	
262	    fn reset(&mut self) {
263	        *self = Fpu::default();
264	    }
265	}
