384	/// Inputs at or beyond 2^63 are out of range for `fsin` and friends: C2
385	/// is set and the operand is left alone.
386	const TRIG_LIMIT: f64 = (1u64 << 63) as f64;
387	
388	impl Cpu {
389	    fn fload(&mut self, mem: &Memory, src: FSrc) -> Result<f64, Fault> {
390	        let FSrc::Mem(fmt, m) = src else {
391	            let FSrc::St(i) = src else { unreachable!() };
392	            return Ok(self.fpu.st(i));
393	        };
394	        let a = self.ea(&m);
395	        Ok(match fmt {
396	            FMem::F32 => f64::from(f32::from_bits(mem.read_u32(a)?)),
397	            FMem::F64 => f64::from_bits(read_u64(mem, a)?),
398	            FMem::F80 => f80_to_f64(mem.slice(a, 10)?.try_into().unwrap()),
399	            FMem::I16 => f64::from(mem.read_u16(a)? as i16),
400	            FMem::I32 => f64::from(mem.read_u32(a)? as i32),
401	            FMem::I64 => read_u64(mem, a)? as i64 as f64,
402	        })
403	    }
404	
405	    fn fstore(&mut self, mem: &mut Memory, to: FMem, m: MemRef, v: f64, trunc: bool) -> R {
406	        let a = self.ea(&m);
407	        let int = |cpu: &mut Cpu, lo: f64, hi: f64| -> Option<f64> {
408	            let r = if trunc { v.trunc() } else { cpu.fpu.round(v) };
409	            if r >= lo && r < hi {
410	                Some(r)
411	            } else {
412	                cpu.fpu.sw |= IE;
413	                None
414	            }
415	        };
416	        match to {
417	            FMem::F32 => mem.write_u32(a, (v as f32).to_bits()),
418	            FMem::F64 => mem.write_bytes(a, &v.to_bits().to_le_bytes()),
419	            FMem::F80 => mem.write_bytes(a, &f64_to_f80(v)),
420	            FMem::I16 => {
421	                let r = int(self, -32768.0, 32768.0).map_or(0x8000, |r| r as i16 as u16);
422	                mem.write_u16(a, r)
423	            }
424	            FMem::I32 => {
425	                let r =
426	                    int(self, -2147483648.0, 2147483648.0).map_or(0x8000_0000, |r| r as i32 as u32);
427	                mem.write_u32(a, r)
428	            }
429	            FMem::I64 => {
430	                let r = int(self, -TRIG_LIMIT, TRIG_LIMIT).map_or(1 << 63, |r| r as i64 as u64);
431	                mem.write_bytes(a, &r.to_le_bytes())
432	            }
433	        }
434	    }
435	
436	    /// Execute one x87 instruction.
437	    pub(crate) fn fpu_exec(&mut self, mem: &mut Memory, op: FpuOp) -> R {
438	        let f = &mut self.fpu;
439	        match op {
440	            FpuOp::Load(src) => {
441	                let v = self.fload(mem, src)?;
442	                self.fpu.push(v);
443	            }
444	            FpuOp::LoadConst(c) => f.push(match c {
445	                FConst::One => 1.0,
446	                FConst::L2t => std::f64::consts::LOG2_10,
447	                FConst::L2e => std::f64::consts::LOG2_E,
448	                FConst::Pi => std::f64::consts::PI,
449	                FConst::Lg2 => std::f64::consts::LOG10_2,
450	                FConst::Ln2 => std::f64::consts::LN_2,
451	                FConst::Zero => 0.0,
452	            }),
453	            FpuOp::Store {
454	                to,
455	                mem: m,
456	                pop,
457	                trunc,
458	            } => {
459	                let v = self.fpu.st(0);
460	                self.fstore(mem, to, m, v, trunc)?;
461	                if pop {
462	                    self.fpu.pop();
463	                }
464	            }
465	            FpuOp::StoreSt { i, pop } => {
466	                let v = f.st(0);
467	                f.set(i, v);
468	                if pop {
469	                    f.pop();
470	                }
471	            }
472	            FpuOp::Arith { op, dst, src, pop } => {
473	                let s = self.fload(mem, src)?;
474	                let f = &mut self.fpu;
475	                let d = f.st(dst);
476	                let (num, den) = match op {
477	                    FArith::Div => (d, s),
478	                    FArith::Divr => (s, d),
479	                    _ => (1.0, 1.0),
480	                };
481	                if den == 0.0 && num.is_finite() && num != 0.0 {
482	                    f.sw |= ZE;
483	                }
484	                let r = match op {
485	                    FArith::Add => d + s,
486	                    FArith::Mul => d * s,
487	                    FArith::Sub => d - s,
488	                    FArith::Subr => s - d,
489	                    FArith::Div | FArith::Divr => num / den,
490	                };
491	                if r.is_nan() && !d.is_nan() && !s.is_nan() {
492	                    f.sw |= IE;
493	                }
494	                f.set(dst, r);
495	                if pop {
496	                    f.pop();
497	                }
498	            }
499	            FpuOp::Compare {
500	                src,
501	                pops,
502	                unordered,
503	            } => {
504	                let b = self.fload(mem, src)?;
505	                let f = &mut self.fpu;
506	                let a = f.st(0);
507	                let (c3, c2, c0) = compare(a, b);
508	                if c2 && !unordered {
509	                    f.sw |= IE;
510	                }
511	                f.set_cc(c3, c2, false, c0);
512	                for _ in 0..pops {
513	                    f.pop();
514	                }
515	            }
516	            FpuOp::Comi { i, pop, unordered } => {
517	                let (a, b) = (f.st(0), f.st(i));
518	                let (z, p, c) = compare(a, b);
519	                if p && !unordered {
520	                    f.sw |= IE;
521	                }
522	                f.sw &= !C1;
523	                if pop {
524	                    f.pop();
525	                }
526	                (self.zf, self.pf, self.cf, self.of, self.sf) = (z, p, c, false, false);
527	            }
528	            FpuOp::Cmov { cc, i } => {
529	                if self.cond(cc) {
530	                    let f = &mut self.fpu;
531	                    let v = f.st(i);
532	                    f.set(0, v);
533	                }
534	            }
535	            FpuOp::Tst => {
536	                let a = f.st(0);
537	                let (c3, c2, c0) = compare(a, 0.0);
538	                f.set_cc(c3, c2, false, c0);
539	            }
540	            FpuOp::Xam => {
541	                let p = f.phys(0);
542	                let v = f.regs[p];
543	                let sign = v.is_sign_negative();
544	                let (c3, c2, c0) = if f.is_empty(0) {
545	                    (true, false, true)
546	                } else if v.is_nan() {
547	                    (false, false, true)
548	                } else if v.is_infinite() {
549	                    (false, true, true)
550	                } else if v == 0.0 {
551	                    (true, false, false)
552	                } else if v.is_subnormal() {
553	                    (true, true, false)
554	                } else {
555	                    (false, true, false)
556	                };
557	                f.set_cc(c3, c2, sign && !f.is_empty(0), c0);
558	            }
559	            FpuOp::Xch(i) => {
560	                let (a, b) = (f.st(0), f.st(i));
561	                f.set(0, b);
562	                f.set(i, a);
563	                f.sw &= !C1;
564	            }
565	            FpuOp::Free(i) => {
566	                let p = f.phys(i);
567	                f.valid &= !(1 << p);
568	            }
569	            FpuOp::Unary(u) => {
570	                let v = f.st(0);
571	                if matches!(u, FUnary::Sin | FUnary::Cos) && v.abs() >= TRIG_LIMIT {
572	                    f.sw |= C2;
573	                    return Ok(());
574	                }
575	                let r = match u {
576	                    FUnary::Chs => -v,
577	                    FUnary::Abs => v.abs(),
578	                    FUnary::Sqrt => v.sqrt(),
579	                    FUnary::Rndint => f.round(v),
580	                    FUnary::F2xm1 => (v * std::f64::consts::LN_2).exp_m1(),
581	                    FUnary::Sin => v.sin(),
582	                    FUnary::Cos => v.cos(),
583	                };
584	                if r.is_nan() && !v.is_nan() {
585	                    f.sw |= IE;
586	                }
587	                if matches!(u, FUnary::Sin | FUnary::Cos) {
588	                    f.sw &= !C2;
589	                }
590	                f.set(0, r);
591	            }
592	            FpuOp::Yl2x | FpuOp::Yl2xp1 => {
593	                let (x, y) = (f.st(0), f.st(1));
594	                let l = if op == FpuOp::Yl2x {
595	                    x.log2()
596	                } else {
597	                    x.ln_1p() / std::f64::consts::LN_2
598	                };
599	                if x == 0.0 && op == FpuOp::Yl2x {
600	                    f.sw |= ZE;
601	                }
602	                f.set(1, y * l);
603	                f.pop();
604	            }
605	            FpuOp::Ptan | FpuOp::Sincos => {
606	                let v = f.st(0);
607	                if v.abs() >= TRIG_LIMIT {
608	                    f.sw |= C2;
609	                    return Ok(());
610	                }
611	                f.sw &= !C2;
612	                if op == FpuOp::Ptan {
613	                    f.set(0, v.tan());
614	                    f.push(1.0);
615	                } else {
616	                    f.set(0, v.sin());
617	                    f.push(v.cos());
618	                }
619	            }
620	            FpuOp::Patan => {
621	                let (x, y) = (f.st(0), f.st(1));
622	                f.set(1, y.atan2(x));
623	                f.pop();
624	            }
625	            FpuOp::Xtract => {
626	                let v = f.st(0);
627	                let (sig, exp) = if v == 0.0 {
628	                    f.sw |= ZE;
629	                    (v, f64::NEG_INFINITY)
630	                } else if !v.is_finite() {
631	                    (v, v.abs())
632	                } else {
633	                    let (s, e) = split(v.abs());
634	                    (s.copysign(v), e as f64)
635	                };
636	                f.set(0, exp);
637	                f.push(sig);
638	            }
639	            FpuOp::Prem | FpuOp::Prem1 => {
640	                let (a, b) = (f.st(0), f.st(1));
641	                if b == 0.0 || !a.is_finite() || b.is_nan() {
642	                    f.sw |= IE;
643	                    f.set(0, INDEFINITE);
644	                    f.set_cc(false, false, false, false);
645	                    return Ok(());
646	                }
647	                let mut r = a % b; // exact, the sign of `a`, as fprem
648	                let mut q = ((a - r) / b).abs();
649	                if op == FpuOp::Prem1 {
650	                    let (ar, ab) = (r.abs(), b.abs());
651	                    let odd = (q % 2.0) == 1.0;
652	                    if 2.0 * ar > ab || (2.0 * ar == ab && odd) {
653	                        r -= ab.copysign(r);
654	                        q += 1.0;
655	                    }
656	                }
657	                let q = if q < TRIG_LIMIT { q as u64 } else { 0 };
658	                f.set(0, r);
659	                f.set_cc(q & 2 != 0, false, q & 1 != 0, q & 4 != 0);
660	            }
661	            FpuOp::Scale => {
662	                let (v, s) = (f.st(0), f.st(1));
663	                let r = if s.is_nan() {
664	                    s
665	                } else {
666	                    ldexp(v, s.trunc().clamp(-1e5, 1e5) as i64)
