668	                f.set(0, r);
669	            }
670	            FpuOp::Decstp => f.top = (f.top + 7) & 7,
671	            FpuOp::Incstp => f.top = (f.top + 1) & 7,
672	            FpuOp::Ldcw(m) => self.fpu.cw = mem.read_u16(self.ea(&m))?,
673	            FpuOp::Stcw(m) => mem.write_u16(self.ea(&m), self.fpu.cw)?,
674	            FpuOp::Stsw(None) => {
675	                let s = self.fpu.status();
676	                self.set_reg(EAX, Size::W, u32::from(s));
677	            }
678	            FpuOp::Stsw(Some(m)) => mem.write_u16(self.ea(&m), self.fpu.status())?,
679	            FpuOp::Init => f.reset(),
680	            FpuOp::Clex => f.sw &= !0x80ff,
681	            FpuOp::Nop => {}
682	        }
683	        Ok(())
684	    }
685	}
