        FConst::L2t => std::f64::consts::LOG2_10,
        FConst::L2e => std::f64::consts::LOG2_E,
        FConst::Pi => std::f64::consts::PI,
        FConst::Lg2 => std::f64::consts::LOG10_2,
        FConst::Ln2 => std::f64::consts::LN_2,
