//! Scaling, splitting, comparing and classifying doubles.

/// `v * 2^n` without overflowing the intermediate power.
pub fn ldexp(mut v: f64, mut n: i64) -> f64 {
    let step = |k: i64| f64::from_bits(((k + 1023) as u64) << 52);
    while n > 1000 {
        v *= step(1000);
        n -= 1000;
        if v.is_infinite() {
            return v;
        }
    }
    while n < -1000 {
        v *= step(-1000);
        n += 1000;
        if v == 0.0 {
            return v;
        }
    }
    v * step(n)
}

