533	    /// Run up to `budget` steps (one instruction or one gateway each).
534	    pub fn run(&mut self, host: &mut dyn Host, budget: u64) -> Status {
535	        for _ in 0..budget {
536	            if let Some(code) = self.halted {
537	                return Status::Halted(code);
538	            }
539	            if self.restart {
540	                return Status::Restart;
541	            }
542	            if self.pending_call.is_some() {
543	                return Status::HostCall;
544	            }
545	            if std::mem::take(&mut self.interrupt) {
546	                self.input.clear();
547	                self.recover(host, Fault::Interrupted);
548	                continue;
549	            }
550	            match self.step(host) {
551	                Ok(Flow::Continue) => {}
552	                Ok(Flow::NeedInput) => return Status::NeedInput,
553	                Ok(Flow::HostCall) => return Status::HostCall,
554	                Ok(Flow::Halt(code)) => {
555	                    self.halted = Some(code);
556	                    return Status::Halted(code);
557	                }
558	                Ok(Flow::Restart) => {
559	                    self.restart = true;
560	                    return Status::Restart;
561	                }
562	                Ok(Flow::NestedReturn) => self.recover(
563	                    host,
564	                    Fault::BadGate {
565	                        addr: Gate::NestedReturn.addr(),
566	                    },
567	                ),
568	                Err(f) => self.recover(host, f),
569	            }
570	        }
571	        match self.halted {
572	            Some(code) => Status::Halted(code),
573	            None if self.restart => Status::Restart,
574	            None => Status::Yielded,
575	        }
576	    }
