655	            let xt = self.mem.read_u32(e + 4).unwrap_or(0);
656	            if xt <= addr && best.is_none_or(|(bx, _)| xt > bx) {
657	                best = Some((xt, e));
658	            }
659	            e = self.mem.read_u32(e).unwrap_or(0);
660	            guard += 1;
661	        }
662	        match best {
663	            Some((xt, e)) => {
664	                let n = self.mem.read_u8(e + 8).unwrap_or(0) as u32;
665	                let name = self.mem.slice(e + 9, n).unwrap_or(b"?");
666	                format!("{}+{:#x}", String::from_utf8_lossy(name), addr - xt)
667	            }
668	            None => format!("{addr:#010x}"),
669	        }
670	    }
