753	    /// Call Forth code at `target` from inside a Rust routine and run it to
754	    /// completion on the Rust stack.
755	    ///
756	    /// Used only for callbacks that are expected to be short and
757	    /// non-interactive (`do_cr`, `prompt`, `iterate` handlers, overridden
758	    /// `emit`/`type`).  If such code asks for input that has not arrived,
759	    /// the host gets one chance to supply it synchronously
760	    /// ([`Host::read_input_blocking`]); otherwise this faults.  Budgets do
761	    /// not apply inside a nested call.
762	    pub fn call_nested(&mut self, host: &mut dyn Host, target: u32) -> Result<(), Fault> {
763	        let saved_eip = self.cpu.eip;
764	        let entry_esp = self.cpu.r[ESP as usize];
765	        self.cpu.push32(&mut self.mem, Gate::NestedReturn.addr())?;
766	        self.cpu.eip = target;
767	        self.nested += 1;
768	        let result = loop {
769	            match self.step(host) {
770	                Ok(Flow::Continue) => {
771	                    if self.cpu.r[ESP as usize] > entry_esp {
772	                        break Err(Fault::UnwoundThroughHost);
773	                    }
774	                }
775	                Ok(Flow::NestedReturn) => break Ok(()),
776	                Ok(Flow::NeedInput) => match host.read_input_blocking() {
777	                    Some(bytes) if !bytes.is_empty() => self.input.extend(bytes),
778	                    Some(_) => self.input_closed = true,
779	                    None => break Err(Fault::InputInNestedCall),
780	                },
781	                Ok(Flow::Halt(code)) => {
782	                    self.halted = Some(code);
783	                    break Ok(());
784	                }
785	                Ok(Flow::Restart) => {
786	                    self.restart = true;
787	                    break Ok(());
788	                }
789	                Ok(Flow::HostCall) => {
790	                    self.pending_call = None;
791	                    break Err(Fault::Unavailable(
792	                        "a host call cannot wait inside a nested call".into(),
793	                    ));
794	                }
795	                Err(f) => break Err(f),
796	            }
797	        };
798	        self.nested -= 1;
799	        self.cpu.eip = saved_eip;
800	        result
801	    }
