826	        // which runs `interp` under `catch`) once booted; otherwise the
827	        // core's REPL, or `appstart` if a program installed its own.
828	        let entry = self.var(st::REPL_ENTRY);
829	        let app = self.var(st::APPSTART);
830	        self.cpu.eip = if entry != 0 {
831	            entry
832	        } else if app == Gate::Hello.addr() {
833	            Gate::Repl.addr()
834	        } else {
835	            app
836	        };
837	    }
