854	    /// Dictionary search (`__find`), returning the entry address.
855	    pub fn find_entry(&self, name: &[u8]) -> Option<u32> {
856	        let mut e = self.mem.read_u32(self.var(st::LAST)).ok()?;
857	        while e != 0 {
858	            let n = self.mem.read_u8(e + 8).ok()?;
859	            if n as usize == name.len() & 0xff
860	                && let Ok(s) = self.mem.slice(e + 9, name.len() as u32)
861	                && s == name
862	            {
863	                return Some(e);
864	            }
865	            e = self.mem.read_u32(e).ok()?;
866	        }
867	        None
868	    }
869	}
