impl Gate {
    #[inline]
    pub fn addr(self) -> u32 {
        GATE_BASE + GATE_STRIDE * self as u32
    }

    #[inline]
    pub fn from_addr(a: u32) -> Option<Gate> {
        let off = a.checked_sub(GATE_BASE)?;
        if off % GATE_STRIDE != 0 {
            return None;
        }
        Gate::ALL.get((off / GATE_STRIDE) as usize).copied()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn gates_fit_in_their_region() {
        assert!(Gate::ALL.len() as u32 * GATE_STRIDE <= GATE_END - GATE_BASE);
        for (i, g) in Gate::ALL.iter().enumerate() {
            assert_eq!(*g as usize, i);
            assert_eq!(Gate::from_addr(g.addr()), Some(*g));
        }
        assert_eq!(Gate::from_addr(GATE_BASE + 1), None);
        assert_eq!(Gate::from_addr(GATE_END), None);
    }
}
//! # Images
//!
//! An image is the state Reva's `(save)` wrote into an executable: statics,
//! dictionary, code, and heap — here without the executable around it, so
//! the same image runs on every host.  It holds vx86 bytes only; decode
//! caches and native translations are rebuilt after loading.
//!
//! Format (little-endian):
//!
//! ```text
//! magic "REVAVX86"  u32 version  u32 mem_size
//! u32 segment count, then per segment: u32 start, u32 len, bytes
//! heap allocator state (see heap.rs)
//! ```
//!
//! Loading starts the machine at `cold`, as a saved Reva program did.

use crate::heap::Heap;
use crate::layout::*;
use crate::machine::{Machine, st};

const MAGIC: &[u8; 8] = b"REVAVX86";
const VERSION: u32 = 1;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ImageError {
    BadMagic,
    BadVersion(u32),
    Truncated,
    BadSegment { start: u32, len: u32 },
}

impl std::fmt::Display for ImageError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ImageError::BadMagic => write!(f, "not a Reva vx86 image"),
            ImageError::BadVersion(v) => write!(f, "unsupported image version {v}"),
            ImageError::Truncated => write!(f, "image is truncated"),
            ImageError::BadSegment { start, len } => {
                write!(f, "image segment {start:#x}+{len:#x} is out of range")
            }
        }
    }
}

impl std::error::Error for ImageError {}

impl Machine {
    /// Serialize the machine's persistent state: between [`Machine::run`]
    /// calls, or from `(save)` while Forth code runs (loading resets the
    /// interpreter's source and catch state, so either works).
    pub fn save_image(&self) -> Vec<u8> {
        let mut out = Vec::new();
        out.extend_from_slice(MAGIC);
        out.extend_from_slice(&VERSION.to_le_bytes());
        out.extend_from_slice(&self.mem.size().to_le_bytes());
        let segments = [
            (GATE_END, D0),
            (D0, self.var(st::D)),
            (H0, self.var(st::H)),
            (HEAP_BASE, self.heap.top()),
        ];
        out.extend_from_slice(&(segments.len() as u32).to_le_bytes());
        for (start, end) in segments {
            let len = end.saturating_sub(start);
            out.extend_from_slice(&start.to_le_bytes());
            out.extend_from_slice(&len.to_le_bytes());
            out.extend_from_slice(self.mem.slice(start, len).unwrap_or(&[]));
        }
        self.heap.save(&mut out);
        out
    }

    /// Recreate a machine from an image; `args` replace `argc`/`(argv)`.
    pub fn load_image(bytes: &[u8], args: &[&str]) -> Result<Machine, ImageError> {
        let mut r = Reader { b: bytes, at: 0 };
        if r.take(8)? != MAGIC {
            return Err(ImageError::BadMagic);
        }
        let version = r.u32()?;
        if version != VERSION {
            return Err(ImageError::BadVersion(version));
        }
        let mem_size = r.u32()?;
        let mut m = Machine::with_memory(mem_size);
        for _ in 0..r.u32()? {
            let (start, len) = (r.u32()?, r.u32()?);
            let data = r.take(len as usize)?;
            m.mem
                .write_bytes(start, data)
                .map_err(|_| ImageError::BadSegment { start, len })?;
        }
        let mut words = std::iter::from_fn(|| r.u32().ok());
        m.heap = Heap::load(&mut words).ok_or(ImageError::Truncated)?;
        // A saved program started with no source file and no catch frame,
        // whatever was running when `(save)` wrote the image.
        for (var, v) in [
            (st::SOURCE, 0),
            (st::TP, TIB),
            (st::TIN, TIB),
            (st::IS_COMPILING, 0),
            (st::HANDLER, 0),
        ] {
            m.mem
                .write_u32(var, v)
                .map_err(|_| ImageError::BadSegment { start: var, len: 4 })?;
        }
        m.set_args(args);
        m.reset_cpu();
        Ok(m)
    }
}

struct Reader<'a> {
    b: &'a [u8],
    at: usize,
}

impl<'a> Reader<'a> {
    fn take(&mut self, n: usize) -> Result<&'a [u8], ImageError> {
        let end = self.at.checked_add(n).ok_or(ImageError::Truncated)?;
        let s = self.b.get(self.at..end).ok_or(ImageError::Truncated)?;
        self.at = end;
        Ok(s)
    }
    fn u32(&mut self) -> Result<u32, ImageError> {
        let s = self.take(4)?;
        Ok(u32::from_le_bytes([s[0], s[1], s[2], s[3]]))
    }
}
//! A small first-fit allocator for `allocate`/`free`/`resize` and `slurp`.
//!
//! Book-keeping lives on the Rust side (not in VM memory) so a wild store
//! from Forth cannot corrupt the allocator; [`Heap::save`]/[`Heap::load`]
//! carry it through images.

use std::collections::BTreeMap;

pub struct Heap {
    base: u32,
    limit: u32,
    top: u32,
    used: BTreeMap<u32, u32>,
    free: BTreeMap<u32, u32>,
}

const ALIGN: u32 = 8;

impl Heap {
    pub fn new(base: u32, limit: u32) -> Heap {
        Heap {
            base,
            limit,
            top: base,
            used: BTreeMap::new(),
            free: BTreeMap::new(),
        }
    }

    /// Highest address handed out so far (end of the used heap).
    pub fn top(&self) -> u32 {
        self.top
    }

    pub fn size_of(&self, addr: u32) -> Option<u32> {
        self.used.get(&addr).copied()
    }

    /// Allocate `n` bytes; `None` when the heap is exhausted.
    pub fn alloc(&mut self, n: u32) -> Option<u32> {
        let n = n.max(1).checked_add(ALIGN - 1)? & !(ALIGN - 1);
        let hit = self
            .free
            .iter()
            .find(|&(_, &sz)| sz >= n)
            .map(|(&a, &sz)| (a, sz));
        let addr = match hit {
            Some((a, sz)) => {
                self.free.remove(&a);
                if sz > n {
                    self.free.insert(a + n, sz - n);
                }
                a
            }
            None => {
                let a = self.top;
                let end = a.checked_add(n)?;
                if end > self.limit {
                    return None;
                }
                self.top = end;
                a
            }
        };
        self.used.insert(addr, n);
        Some(addr)
    }

    /// Free a block.  Returns false for an address that was not allocated
    /// (Reva's C `free` would have crashed; we just report it).
    pub fn free(&mut self, addr: u32) -> bool {
        let Some(mut n) = self.used.remove(&addr) else {
            return false;
        };
        let mut a = addr;
        if let Some((&pa, &pn)) = self.free.range(..a).next_back()
            && pa + pn == a
        {
            self.free.remove(&pa);
            a = pa;
            n += pn;
        }
        if let Some(&nn) = self.free.get(&(a + n)) {
            self.free.remove(&(a + n));
            n += nn;
        }
        if a + n == self.top {
            self.top = a;
        } else {
            self.free.insert(a, n);
        }
        true
    }

    pub fn save(&self, out: &mut Vec<u8>) {
        for v in [
            self.base,
            self.limit,
            self.top,
            self.used.len() as u32,
            self.free.len() as u32,
        ] {
            out.extend_from_slice(&v.to_le_bytes());
        }
        for (a, n) in self.used.iter().chain(self.free.iter()) {
            out.extend_from_slice(&a.to_le_bytes());
            out.extend_from_slice(&n.to_le_bytes());
        }
    }

    pub fn load(words: &mut impl Iterator<Item = u32>) -> Option<Heap> {
        let (base, limit, top, nu, nf) = (
            words.next()?,
            words.next()?,
            words.next()?,
            words.next()?,
            words.next()?,
        );
        let mut h = Heap::new(base, limit);
        h.top = top;
        for _ in 0..nu {
            h.used.insert(words.next()?, words.next()?);
        }
        for _ in 0..nf {
            h.free.insert(words.next()?, words.next()?);
        }
        Some(h)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn alloc_free_reuse_and_coalesce() {
        let mut h = Heap::new(0x1000, 0x2000);
        let a = h.alloc(10).unwrap();
        let b = h.alloc(10).unwrap();
        let c = h.alloc(10).unwrap();
        assert_eq!((a, b, c), (0x1000, 0x1010, 0x1020));
        assert!(h.free(a));
        assert!(h.free(b));
        assert_eq!(h.alloc(32).unwrap(), 0x1000); // a+b coalesced
        assert!(h.free(c));
        assert!(!h.free(c));
        assert!(h.alloc(0x2000).is_none());
    }
}
//! # Hooks for native and WebAssembly translators
//!
//! The vx86 interpreter is the reference tier: it runs everywhere and defines
//! the semantics.  Faster tiers translate *basic blocks* of vx86 code into
//! host code and keep the result as a cache:
//!
//! * **x86-64**: nearly 1:1.  VM registers map to host 32-bit registers,
//!   memory operands gain a base register (`[r15 + rax]`), ESP becomes a
//!   pinned register holding the VM return-stack offset.
//! * **ARM64**: one or two instructions per vx86 instruction; flags map to
//!   NZCV (note: AArch64's carry after subtraction is inverted relative to
//!   x86's borrow), memory is `[x28, w_n, uxtw]`.
//! * **WebAssembly**: a block becomes a function over `(memory, regs)`; the
//!   browser's JIT does the rest.
//!
//! Gateway addresses (Rust core routines) always end a block and are called
//! through the interpreter's dispatcher, so translators never need to know
//! about them beyond "exit to the dispatcher with EIP = gateway".
//!
//! The contract with the rest of the VM is small:
//!
//! 1. A translator sees a [`Block`] produced by [`decode_block`]; it may
//!    decline (`None`) and the interpreter keeps running that block.
//! 2. Translations are invalidated by page when code is written; the machine
//!    forwards every dirty code page to [`Translator::invalidate`].
//! 3. Images never contain translations — only vx86 bytes — so an image runs
//!    on every host and translations are rebuilt lazily after loading.
//!
//! Step 1 provides the block decoder, the invalidation plumbing, and this
//! trait.  No native translator is installed yet.

use crate::fault::Fault;
use crate::layout::{GATE_BASE, GATE_END};
use crate::mem::Memory;
use crate::x86::{Insn, decode};

/// Straight-line vx86 code: `insns` run in order; the last one (if
/// `ends_with_branch`) transfers control.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Block {
    pub start: u32,
    pub insns: Vec<(u32, Insn)>,
    /// First address after the block.
    pub end: u32,
    pub ends_with_branch: bool,
}

/// Decode the basic block starting at `start`, up to `max_insns`.
pub fn decode_block(mem: &Memory, start: u32, max_insns: usize) -> Result<Block, Fault> {
    let mut insns = Vec::new();
    let mut at = start;
    let mut ends_with_branch = false;
    while insns.len() < max_insns && !(GATE_BASE..GATE_END).contains(&at) {
        let i = decode(mem, at)?;
        insns.push((at, i));
        at = at.wrapping_add(i.len as u32);
        if i.ends_block() {
            ends_with_branch = true;
            break;
        }
    }
    Ok(Block {
        start,
        insns,
        end: at,
        ends_with_branch,
    })
}

/// Opaque handle to translated code owned by a translator.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct NativeHandle(pub u64);

pub trait Translator {
    fn name(&self) -> &'static str;
    /// Translate a block, or decline.
    fn translate(&mut self, block: &Block) -> Option<NativeHandle>;
    /// Code in `[page_start, page_start + len)` was written; drop any
    /// translation that read bytes from it.
    fn invalidate(&mut self, page_start: u32, len: u32);
}

