pub struct BufferHost {
    pub out: Vec<u8>,
    pub fs: MemFs,
    pub env: HashMap<String, String>,
    /// What `now` reports: set by the embedder (the browser sets it before
    /// each run); `None` (the default) keeps tests deterministic.
    pub clock: Option<(u64, u32)>,
