/// A move: whether the drawing still had room, or `None` for another gate.
pub fn draw(c: &mut Canvas, g: Gate, args: &[u32]) -> Option<bool> {
    Some(match g {
        Gate::TtForward => c.forward(int(args, 0)),
        Gate::TtStep => c.step(),
        Gate::TtSetxy => c.move_to(int(args, 0), int(args, 1)),
        _ => return None,
    })
