1	//! The terminal line editor's logic: key decoding, editing, history
2	//! recall, Ctrl-R search and drawing.  No I/O here (see `term.rs`), so all
3	//! of it is unit tested.
4	//!
5	//! The keys are the web page's (`www/lineedit.js`); `docs/repl.md` has
6	//! the table.  The line is drawn on one terminal row after the prompt,
7	//! scrolling sideways when it is wider than the terminal, so a redraw is
8	//! always "carriage return, prompt, visible text, clear to end of row,
9	//! move to the cursor" and never depends on where wrapped rows went.
10	
11	use crate::history::History;
12	
13	/// A decoded key.
14	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
15	pub enum Key {
16	    Char(char),
17	    /// Ctrl plus a letter (`'a'..='z'`), except the ones below.
18	    Ctrl(char),
19	    /// Alt (Meta, Esc prefix) plus a character.
20	    Alt(char),
21	    Enter,
22	    Backspace,
23	    AltBackspace,
24	    Delete,
25	    Left,
26	    Right,
27	    WordLeft,
28	    WordRight,
29	    Home,
30	    End,
31	    Up,
32	    Down,
33	    Esc,
34	    /// A sequence this editor does not use.
35	    Ignored,
36	}
37	
38	/// Turns terminal input bytes into [`Key`]s: UTF-8, control bytes, and the
39	/// `ESC [`/`ESC O` sequences xterm-like terminals (and Windows consoles
40	/// with virtual terminal input) send.  A lone Esc followed by a character
41	/// is Alt plus that character, as in readline, so no timing is needed.
42	#[derive(Debug, Default)]
43	pub struct Decoder {
44	    pending: Vec<u8>,
45	    after_cr: bool,
46	}
47	
48	impl Decoder {
49	    /// Feed one byte; returns a key once one is complete.
50	    pub fn push(&mut self, b: u8) -> Option<Key> {
51	        let after_cr = std::mem::take(&mut self.after_cr);
52	        if self.pending.is_empty() {
53	            return match b {
54	                b'\r' => {
55	                    self.after_cr = true;
56	                    Some(Key::Enter)
57	                }
58	                b'\n' if after_cr => None, // CR LF (pasted text): one Enter
59	                b'\n' => Some(Key::Enter),
60	                0x1b => {
61	                    self.pending.push(b);
62	                    None
63	                }
64	                8 | 0x7f => Some(Key::Backspace),
65	                b'\t' => Some(Key::Char(' ')),
66	                1..=26 => Some(Key::Ctrl((b'a' + b - 1) as char)),
67	                0..=31 => Some(Key::Ignored),
68	                0x20..=0x7e => Some(Key::Char(b as char)),
69	                _ => {
70	                    self.pending.push(b);
71	                    self.utf8()
72	                }
73	            };
74	        }
75	        self.pending.push(b);
76	        if self.pending[0] == 0x1b {
77	            self.escape()
78	        } else {
79	            self.utf8()
80	        }
81	    }
82	
83	    fn utf8(&mut self) -> Option<Key> {
84	        let need = match self.pending[0] {
85	            0xc0..=0xdf => 2,
86	            0xe0..=0xef => 3,
87	            0xf0..=0xf7 => 4,
88	            _ => 1,
89	        };
90	        if self.pending.len() < need {
91	            return None;
92	        }
93	        let k = std::str::from_utf8(&self.pending)
94	            .ok()
95	            .and_then(|s| s.chars().next())
96	            .map_or(Key::Ignored, Key::Char);
97	        self.pending.clear();
98	        Some(k)
99	    }
100	
101	    fn escape(&mut self) -> Option<Key> {
102	        let p = &self.pending;
103	        if p.len() == 2 {
104	            return match p[1] {
105	                b'[' | b'O' => None,
106	                0x7f | 8 => self.done(Key::AltBackspace),
107	                0x1b => self.done(Key::Esc),
108	                c if c.is_ascii_graphic() => self.done(Key::Alt(c.to_ascii_lowercase() as char)),
109	                _ => self.done(Key::Esc),
110	            };
111	        }
112	        let last = *p.last().unwrap();
113	        if !(0x40..=0x7e).contains(&last) {
114	            // parameters and intermediates; give up on runaway sequences
115	            return if p.len() > 16 {
116	                self.done(Key::Ignored)
117	            } else {
118	                None
119	            };
120	        }
121	        let params = String::from_utf8_lossy(&p[2..p.len() - 1]).into_owned();
122	        let modified = params.ends_with(";5") || params.ends_with(";3");
123	        let k = match (last, params.as_str()) {
124	            (b'A', _) => Key::Up,
125	            (b'B', _) => Key::Down,
126	            (b'C', _) if modified => Key::WordRight,
127	            (b'D', _) if modified => Key::WordLeft,
128	            (b'C', _) => Key::Right,
129	            (b'D', _) => Key::Left,
130	            (b'H', _) => Key::Home,
131	            (b'F', _) => Key::End,
132	            (b'~', "1" | "7") => Key::Home,
133	            (b'~', "4" | "8") => Key::End,
134	            (b'~', "3") => Key::Delete,
135	            _ => Key::Ignored,
136	        };
137	        self.done(k)
138	    }
139	
140	    fn done(&mut self, k: Key) -> Option<Key> {
141	        self.pending.clear();
142	        Some(k)
143	    }
144	}
145	
146	/// What a key did to the line.
147	#[derive(Debug, PartialEq, Eq)]
148	pub enum Outcome {
149	    /// Still editing: redraw.
150	    Edit,
151	    /// Enter: the finished line (without newline).
152	    Line(String),
153	    /// Ctrl-C: drop the line, start a new one.
154	    Cancel,
155	    /// Ctrl-D on an empty line: end of input.
156	    Eof,
157	    /// Ctrl-L: clear the screen, then redraw.
158	    Clear,
159	}
160	
161	#[derive(Debug)]
162	struct Search {
163	    back: bool,
164	    query: String,
165	    /// The history entry shown, if any matched.
166	    at: Option<usize>,
167	    failed: bool,
168	    original: (Vec<char>, usize),
169	}
170	
171	/// One line being edited, with history recall and search.
172	#[derive(Debug, Default)]
173	pub struct Editor {
174	    buf: Vec<char>,
175	    pos: usize,
176	    kill: Vec<char>,
177	    /// History entry shown (`None`: the draft).
178	    index: Option<usize>,
179	    draft: Vec<char>,
180	    search: Option<Search>,
181	    last_query: String,
182	    /// First char shown, when the line is wider than the terminal.
183	    scroll: usize,
184	}
185	
186	fn is_word(c: char) -> bool {
187	    c.is_alphanumeric() || c == '_'
188	}
189	
190	impl Editor {
191	    /// Start a new, empty line (the kill buffer and last search are kept).
192	    pub fn reset(&mut self) {
193	        let kill = std::mem::take(&mut self.kill);
194	        let last_query = std::mem::take(&mut self.last_query);
195	        *self = Editor {
196	            kill,
197	            last_query,
198	            ..Editor::default()
199	        };
200	    }
201	
202	    /// The text being edited.
203	    pub fn text(&self) -> String {
204	        self.buf.iter().collect()
205	    }
206	
207	    fn set(&mut self, text: &str) {
208	        self.buf = text.chars().collect();
209	        self.pos = self.buf.len();
210	    }
211	
212	    fn word_left(&self) -> usize {
213	        let mut i = self.pos;
214	        while i > 0 && !is_word(self.buf[i - 1]) {
215	            i -= 1;
216	        }
217	        while i > 0 && is_word(self.buf[i - 1]) {
218	            i -= 1;
219	        }
220	        i
221	    }
222	
223	    fn word_right(&self) -> usize {
224	        let mut i = self.pos;
225	        while i < self.buf.len() && !is_word(self.buf[i]) {
226	            i += 1;
227	        }
228	        while i < self.buf.len() && is_word(self.buf[i]) {
229	            i += 1;
230	        }
231	        i
232	    }
233	
234	    fn cut(&mut self, a: usize, b: usize) {
235	        if a < b {
236	            self.kill = self.buf.drain(a..b).collect();
237	        }
238	        self.pos = a;
239	    }
240	
241	    fn recall(&mut self, h: &History, to: Option<usize>) {
242	        if self.index.is_none() {
243	            self.draft = self.buf.clone();
244	        }
245	        self.index = to;
246	        match to.and_then(|i| h.get(i)) {
247	            Some(t) => self.set(t),
248	            None => {
249	                self.buf = self.draft.clone();
250	                self.pos = self.buf.len();
251	            }
252	        }
253	    }
254	
255	    /// Apply `k`.
256	    pub fn key(&mut self, k: Key, h: &History) -> Outcome {
257	        if self.search.is_some()
258	            && let Some(o) = self.search_key(k, h)
259	        {
260	            return o;
261	        }
262	        let n = self.buf.len();
263	        match k {
264	            Key::Char(c) => {
265	                self.buf.insert(self.pos, c);
266	                self.pos += 1;
267	            }
268	            Key::Enter => return Outcome::Line(self.text()),
269	            Key::Ctrl('c') => return Outcome::Cancel,
270	            Key::Ctrl('d') if n == 0 => return Outcome::Eof,
271	            Key::Ctrl('l') => return Outcome::Clear,
272	            Key::Ctrl('a') | Key::Home => self.pos = 0,
273	            Key::Ctrl('e') | Key::End => self.pos = n,
274	            Key::Ctrl('b') | Key::Left => self.pos = self.pos.saturating_sub(1),
275	            Key::Ctrl('f') | Key::Right => self.pos = (self.pos + 1).min(n),
276	            Key::Alt('b') | Key::WordLeft => self.pos = self.word_left(),
277	            Key::Alt('f') | Key::WordRight => self.pos = self.word_right(),
278	            Key::Ctrl('d') | Key::Delete => {
279	                if self.pos < n {
280	                    self.buf.remove(self.pos);
281	                }
282	            }
283	            Key::Ctrl('h') | Key::Backspace => {
284	                if self.pos > 0 {
285	                    self.pos -= 1;
286	                    self.buf.remove(self.pos);
287	                }
288	            }
289	            Key::Ctrl('k') => self.cut(self.pos, n),
290	            Key::Ctrl('u') => self.cut(0, self.pos),
291	            Key::Ctrl('w') | Key::AltBackspace => self.cut(self.word_left(), self.pos),
292	            Key::Alt('d') => {
293	                let (p, e) = (self.pos, self.word_right());
294	                self.cut(p, e);
295	            }
296	            Key::Ctrl('y') => {
297	                let k = self.kill.clone();
298	                self.buf.splice(self.pos..self.pos, k.iter().copied());
299	                self.pos += k.len();
300	            }
301	            Key::Ctrl('t') if n >= 2 && self.pos > 0 => {
302	                let p = if self.pos == n { n - 1 } else { self.pos };
303	                self.buf.swap(p - 1, p);
304	                self.pos = p + 1;
305	            }
306	            Key::Ctrl('p') | Key::Up => {
307	                let to = self.index.unwrap_or(h.len()).checked_sub(1);
308	                if let Some(i) = to {
309	                    self.recall(h, Some(i));
310	                }
311	            }
312	            Key::Ctrl('n') | Key::Down => {
313	                if let Some(i) = self.index {
314	                    self.recall(h, (i + 1 < h.len()).then_some(i + 1));
315	                }
316	            }
317	            Key::Ctrl('r') | Key::Ctrl('s') => {
318	                self.search = Some(Search {
319	                    back: k == Key::Ctrl('r'),
320	                    query: String::new(),
321	                    at: None,
322	                    failed: false,
323	                    original: (self.buf.clone(), self.pos),
324	                });
325	            }
326	            _ => {}
327	        }
328	        Outcome::Edit
329	    }
330	
331	    /// A key while searching: `Some` if it was the search's, `None` if it
332	    /// ended the search and should now be applied to the line.
333	    fn search_key(&mut self, k: Key, h: &History) -> Option<Outcome> {
334	        let s = self.search.as_mut().unwrap();
335	        match k {
336	            Key::Ctrl('r') | Key::Ctrl('s') => {
337	                s.back = k == Key::Ctrl('r');
338	                if s.query.is_empty() {
339	                    s.query = self.last_query.clone();
340	                }
341	                let from = s.at;
342	                self.find(h, from, false);
343	            }
344	            Key::Char(c) => {
345	                s.query.push(c);
346	                let from = s.at;
347	                self.find(h, from, true);
348	            }
349	            Key::Backspace => {
350	                s.query.pop();
351	                s.at = None;
352	                self.find(h, None, true);
353	            }
354	            Key::Ctrl('g') | Key::Ctrl('c') | Key::Esc => {
355	                let s = self.search.take().unwrap();
356	                self.last_query = s.query;
357	                (self.buf, self.pos) = s.original;
358	            }
359	            _ => {
360	                let s = self.search.take().unwrap();
361	                if !s.query.is_empty() {
362	                    self.last_query = s.query;
363	                }
364	                self.index = s.at;
365	                return None;
366	            }
367	        }
368	        Some(Outcome::Edit)
369	    }
370	
371	    /// Look for the query from history entry `from`; `stay`: the entry at
372	    /// `from` itself may match (the query grew).
373	    fn find(&mut self, h: &History, from: Option<usize>, stay: bool) {
374	        let s = self.search.as_mut().unwrap();
375	        let found = if s.query.is_empty() {
376	            None
377	        } else if s.back {
378	            let start = from.map_or(h.len(), |i| if stay { i + 1 } else { i });
379	            h.search_back(&s.query, start)
380	        } else {
381	            match from {
382	                Some(i) if stay && h.get(i).is_some_and(|t| t.contains(&s.query)) => Some(i),
383	                Some(i) => h.search_forward(&s.query, i),
384	                None => (0..h.len()).find(|&i| h.get(i).is_some_and(|t| t.contains(&s.query))),
385	            }
386	        };
387	        s.failed = found.is_none() && !s.query.is_empty();
388	        if let Some(i) = found {
389	            s.at = Some(i);
390	            let text = h.get(i).unwrap_or("");
391	            let q = s.query.clone();
392	            self.set(text);
393	            if let Some(b) = text.find(&q) {
394	                self.pos = text[..b].chars().count();
395	            }
396	        }
397	    }
398	
399	    /// The bytes that redraw the line on the current row: `prompt` (what
400	    /// the program printed last on this row), then the line, scrolled to
401	    /// fit `width` columns, with the cursor placed.
402	    pub fn render(&mut self, prompt: &str, width: usize) -> String {
403	        let shown;
404	        let prompt = match &self.search {
405	            Some(s) => {
406	                shown = format!(
407	                    "({}{}-i-search)`{}': ",
408	                    if s.failed { "failed " } else { "" },
409	                    if s.back { "reverse" } else { "forward" },
410	                    s.query
411	                );
412	                shown.as_str()
413	            }
414	            None => prompt,
415	        };
416	        let pw = visible_width(prompt);
417	        let room = width.saturating_sub(pw + 1).max(8);
418	        if self.pos < self.scroll {
419	            self.scroll = self.pos;
420	        } else if self.pos > self.scroll + room {
421	            self.scroll = self.pos - room;
422	        }
423	        if self.buf.len() <= room {
424	            self.scroll = 0;
425	        }
426	        let end = (self.scroll + room).min(self.buf.len());
427	        let text: String = self.buf[self.scroll..end].iter().collect();
428	        let col = pw + self.pos - self.scroll;
429	        let mut out = format!("\r{prompt}{text}\x1b[K\r");
430	        if col > 0 {
431	            out.push_str(&format!("\x1b[{col}C"));
432	        }
433	        out
434	    }
435	}
436	
437	/// Columns `s` takes, leaving out escape sequences (one per char otherwise).
438	pub fn visible_width(s: &str) -> usize {
439	    let mut n = 0;
440	    let mut chars = s.chars().peekable();
441	    while let Some(c) = chars.next() {
442	        if c == '\x1b' {
443	            if chars.peek() == Some(&'[') {
444	                chars.next();
445	                for c in chars.by_ref() {
446	                    if ('@'..='~').contains(&c) {
447	                        break;
448	                    }
449	                }
450	            }
451	        } else if !c.is_control() {
452	            n += 1;
453	        }
454	    }
455	    n
456	}
457	
458	#[cfg(test)]
459	mod tests {
460	    use super::*;
461	
462	    fn keys(bytes: &[u8]) -> Vec<Key> {
463	        let mut d = Decoder::default();
464	        bytes.iter().filter_map(|&b| d.push(b)).collect()
465	    }
466	
467	    fn typed(e: &mut Editor, h: &History, bytes: &[u8]) -> Vec<Outcome> {
468	        keys(bytes)
469	            .into_iter()
470	            .map(|k| e.key(k, h))
471	            .filter(|o| *o != Outcome::Edit)
472	            .collect()
473	    }
474	
475	    fn hist(lines: &[&str]) -> History {
476	        let mut h = History::in_memory();
477	        for l in lines {
478	            h.add(l);
479	        }
480	        h
481	    }
482	
483	    #[test]
484	    fn decodes_keys() {
485	        use Key::*;
486	        assert_eq!(
487	            keys(b"a\x01\x7f\r\n\x1b[A\x1b[D\x1bOH\x1b[3~\x1b[1;5C\x1bb\x1b\x7f\x1b[200~"),
488	            [
489	                Char('a'),
490	                Ctrl('a'),
491	                Backspace,
492	                Enter,
493	                Up,
494	                Left,
495	                Home,
496	                Delete,
497	                WordRight,
498	                Alt('b'),
499	                AltBackspace,
500	                Ignored
501	            ]
502	        );
503	        assert_eq!(keys("é€".as_bytes()), [Char('é'), Char('€')]);
504	    }
505	
506	    #[test]
507	    fn edits() {
508	        let h = History::in_memory();
509	        let mut e = Editor::default();
510	        typed(&mut e, &h, b"dup swap drop\x1bb\x0b\x01\x19");
511	        assert_eq!(e.text(), "dropdup swap ");
512	        typed(&mut e, &h, b"\x05\x17");
513	        assert_eq!(e.text(), "dropdup ");
514	        typed(&mut e, &h, b"\x15ab\x14");
515	        assert_eq!(e.text(), "ba");
516	        assert_eq!(typed(&mut e, &h, b"\r"), [Outcome::Line("ba".into())]);
517	    }
518	
519	    #[test]
520	    fn ctrl_d_and_c() {
521	        let h = History::in_memory();
522	        let mut e = Editor::default();
523	        assert_eq!(typed(&mut e, &h, b"ab\x02\x04"), []);
524	        assert_eq!(e.text(), "a");
525	        assert_eq!(typed(&mut e, &h, b"\x03"), [Outcome::Cancel]);
526	        e.reset();
527	        assert_eq!(typed(&mut e, &h, b"\x04"), [Outcome::Eof]);
528	    }
529	
530	    #[test]
531	    fn history_recall_keeps_draft() {
532	        let h = hist(&["1 .", "2 ."]);
533	        let mut e = Editor::default();
534	        typed(&mut e, &h, b"dr\x1b[A");
535	        assert_eq!(e.text(), "2 .");
536	        typed(&mut e, &h, b"\x10\x10");
