131	
132	    unsafe extern "C" {
133	        fn tcgetattr(fd: c_int, t: *mut Termios) -> c_int;
134	        fn tcsetattr(fd: c_int, action: c_int, t: *const Termios) -> c_int;
135	        fn cfmakeraw(t: *mut Termios);
136	        #[allow(dead_code)]
137	        fn ioctl(fd: c_int, req: c_ulong, ...) -> c_int;
138	    }
139	    const TCSANOW: c_int = 0;
140	
141	    /// The mode to put back, for the panic hook.
142	    static SAVED: Mutex<Option<Termios>> = Mutex::new(None);
143	
144	    /// Raw mode on stdin until dropped.
145	    pub struct Raw(Termios);
146	
147	    impl Raw {
148	        pub fn enter() -> Option<Raw> {
149	            let mut t: Termios = [0; 32];
150	            // SAFETY: `t` is larger than any termios; fd 0 is stdin.
151	            unsafe {
152	                if tcgetattr(0, &mut t) != 0 {
153	                    return None;
154	                }
155	                let saved = t;
156	                cfmakeraw(&mut t);
157	                if tcsetattr(0, TCSANOW, &t) != 0 {
158	                    return None;
159	                }
160	                install_hook();
161	                *SAVED.lock().ok()? = Some(saved);
162	                Some(Raw(saved))
163	            }
164	        }
165	    }
166	
167	    impl Drop for Raw {
168	        fn drop(&mut self) {
169	            // SAFETY: restores the mode tcgetattr gave us.
170	            unsafe { tcsetattr(0, TCSANOW, &self.0) };
171	            if let Ok(mut s) = SAVED.lock() {
172	                *s = None;
173	            }
174	        }
175	    }
176	
177	    /// Release builds abort on panic without unwinding, so Drop would not
178	    /// run: put the terminal back from the hook.
179	    fn install_hook() {
180	        static ONCE: std::sync::Once = std::sync::Once::new();
181	        ONCE.call_once(|| {
182	            let prev = std::panic::take_hook();
183	            std::panic::set_hook(Box::new(move |info| {
184	                if let Ok(Some(t)) = SAVED.try_lock().map(|s| *s) {
185	                    // SAFETY: as in Drop.
186	                    unsafe { tcsetattr(0, TCSANOW, &t) };
187	                }
188	                prev(info);
189	            }));
190	        });
191	    }
