193	    // Linux: 0x5413, except on MIPS, PowerPC and SPARC, which use the BSD
194	    // encoding.  Should the ioctl fail, $COLUMNS (or 80) is used.
195	    #[cfg(any(target_os = "linux", target_os = "android"))]
196	    const TIOCGWINSZ: c_ulong = if cfg!(any(
197	        target_arch = "mips",
198	        target_arch = "mips64",
199	        target_arch = "powerpc",
200	        target_arch = "powerpc64",
201	        target_arch = "sparc64"
202	    )) {
203	        0x4008_7468
204	    } else {
205	        0x5413
206	    };
207	    #[cfg(any(
208	        target_os = "macos",
209	        target_os = "ios",
210	        target_os = "freebsd",
211	        target_os = "openbsd",
212	        target_os = "netbsd",
213	        target_os = "dragonfly"
214	    ))]
215	    const TIOCGWINSZ: c_ulong = 0x4008_7468;
216	
