231	        let ok = unsafe { ioctl(1, TIOCGWINSZ, ws.as_mut_ptr()) } == 0;
232	        (ok && ws[1] > 0)
233	            .then_some(ws[1] as usize)
234	            .or_else(super::columns)
235	    }
