238	    #[cfg(not(any(
239	        target_os = "linux",
240	        target_os = "android",
241	        target_os = "macos",
242	        target_os = "ios",
243	        target_os = "freebsd",
244	        target_os = "openbsd",
245	        target_os = "netbsd",
246	        target_os = "dragonfly"
247	    )))]
