254	mod raw {
255	    use std::ffi::c_void;
256	
257	    type Handle = *mut c_void;
258	    const STD_INPUT_HANDLE: u32 = -10i32 as u32;
259	    const STD_OUTPUT_HANDLE: u32 = -11i32 as u32;
260	    const ENABLE_PROCESSED_INPUT: u32 = 0x1;
261	    const ENABLE_LINE_INPUT: u32 = 0x2;
262	    const ENABLE_ECHO_INPUT: u32 = 0x4;
263	    const ENABLE_VIRTUAL_TERMINAL_INPUT: u32 = 0x200;
264	    const ENABLE_VIRTUAL_TERMINAL_PROCESSING: u32 = 0x4;
265	
266	    #[repr(C)]
267	    #[derive(Default)]
268	    struct BufferInfo {
269	        size: [i16; 2],
270	        cursor: [i16; 2],
271	        attributes: u16,
272	        window: [i16; 4], // left, top, right, bottom
273	        max: [i16; 2],
274	    }
275	
276	    #[link(name = "kernel32")]
277	    extern "system" {
278	        fn GetStdHandle(n: u32) -> Handle;
279	        fn GetConsoleMode(h: Handle, mode: *mut u32) -> i32;
280	        fn SetConsoleMode(h: Handle, mode: u32) -> i32;
281	        fn GetConsoleScreenBufferInfo(h: Handle, info: *mut BufferInfo) -> i32;
282	    }
283	
284	    /// Raw (VT input) mode on the console until dropped.
285	    pub struct Raw {
286	        input: u32,
287	        output: u32,
288	    }
289	
290	    impl Raw {
291	        pub fn enter() -> Option<Raw> {
292	            // SAFETY: plain console API calls on the process's handles.
293	            unsafe {
294	                let (i, o) = (
295	                    GetStdHandle(STD_INPUT_HANDLE),
296	                    GetStdHandle(STD_OUTPUT_HANDLE),
297	                );
298	                let (mut input, mut output) = (0, 0);
299	                if GetConsoleMode(i, &mut input) == 0 || GetConsoleMode(o, &mut output) == 0 {
300	                    return None;
301	                }
302	                let raw_in = (input
303	                    & !(ENABLE_LINE_INPUT | ENABLE_ECHO_INPUT | ENABLE_PROCESSED_INPUT))
304	                    | ENABLE_VIRTUAL_TERMINAL_INPUT;
305	                if SetConsoleMode(i, raw_in) == 0 {
306	                    return None;
307	                }
308	                if SetConsoleMode(o, output | ENABLE_VIRTUAL_TERMINAL_PROCESSING) == 0 {
309	                    SetConsoleMode(i, input);
310	                    return None;
311	                }
312	                Some(Raw { input, output })
313	            }
314	        }
315	    }
316	
317	    impl Drop for Raw {
318	        fn drop(&mut self) {
319	            // SAFETY: restores the modes read in `enter`.
320	            unsafe {
321	                SetConsoleMode(GetStdHandle(STD_INPUT_HANDLE), self.input);
322	                SetConsoleMode(GetStdHandle(STD_OUTPUT_HANDLE), self.output);
323	            }
324	        }
325	    }
326	
327	    /// Console columns.
328	    pub fn width() -> Option<usize> {
329	        let mut info = BufferInfo::default();
330	        // SAFETY: fills the struct it is given.
331	        let ok =
332	            unsafe { GetConsoleScreenBufferInfo(GetStdHandle(STD_OUTPUT_HANDLE), &mut info) } != 0;
333	        let w = (info.window[2] - info.window[0] + 1) as usize;
334	        (ok && w > 0).then_some(w).or_else(super::columns)
335	    }
336	}
337	
338	#[cfg(not(any(unix, windows)))]
339	mod raw {
340	    pub struct Raw;
341	    impl Raw {
342	        pub fn enter() -> Option<Raw> {
343	            None
344	        }
345	    }
346	    pub fn width() -> Option<usize> {
347	        super::columns()
348	    }
349	}
350	
351	/// `$COLUMNS`, when the terminal cannot be asked.
352	#[allow(dead_code)]
353	fn columns() -> Option<usize> {
354	    std::env::var("COLUMNS")
355	        .ok()?
356	        .parse()
357	        .ok()
358	        .filter(|&c| c > 0)
359	}
