1	//! `reva` — command-line host for the portable Reva core.
2	//!
3	//! ```text
4	//! reva [options] [file ...]
5	//! ```
6	//!
7	//! Boots `reva.f` (embedded), includes each file, evaluates each `-e` text,
8	//! then reads standard input: line by line with a prompt on a terminal, or
9	//! to end of input otherwise (so `reva x.f < /dev/null` is a batch run).
10	//! The exit status is the `bye` code (0 at end of input).
11	//!
12	//! `restart` starts over the way this run started (boot or `--image`),
13	//! includes the files and evaluates the `-e` texts again, then goes on
14	//! reading the input that is left.
15	//!
16	//! At a terminal, the line is edited before Forth sees it: history
17	//! (`~/.reva_history`, or `$REVA_HISTORY`), Up/Down, Ctrl-R search and
18	//! Emacs keys (see `lineedit.rs`, `term.rs` and docs/repl.md).
19	
20	use reva_vm::prelude::Input as _;
21	use reva_vm::prelude::*;
22	use std::io::{self, IsTerminal, Read, Write};
23	use std::process::ExitCode;
24	use std::time::{Duration, SystemTime, UNIX_EPOCH};
25	
26	use reva_vm::host::{Console, Platform, Resources};
27	use reva_vm::vfs::FileSystem;
28	use reva_vm::{Machine, Start, Status, embedded, version};
29	
30	const USAGE: &str = "\
31	usage: reva [options] [file ...]
32	
33	  -e, --eval TEXT      evaluate TEXT after the files (repeatable)
34	      --boot PATH      boot from PATH instead of the embedded reva.f
35	      --no-boot        start from the bare core (no reva.f at all)
36	      --image PATH     start from a saved image instead of booting
37	      --save-image PATH  after files and -e, save an image and exit
38	      --show-boot      print what booting printed (progress digits, errors)
39	      --trace          trace every VM step to stderr (very slow)
40	      --allow-shell    let `shell` (C `system`) run OS commands; off by default
41	      --no-edit        at a terminal, read plain lines (no history or line editing)
42	      --color WHEN     colour in `pp`/`hl-type` listings: auto (default), always, never
43	  -h, --help           this text
44	  -V, --version        version
45	";
46	
47	mod fs;
48	mod history;
49	mod lineedit;
50	mod sql;
51	mod term;
