53	use term::{Input, LineReader};
54	
55	struct StdHost {
56	    out: io::BufWriter<io::Stdout>,
57	    fs: fs::StdFs,
58	    allow_shell: bool,
59	    /// While booting: output is collected here so the progress digits
60	    /// stay quiet.
61	    capture: Option<Vec<u8>>,
62	    /// Whether `pp`/`hl-type` may write colour escapes (`--color`).
63	    color: bool,
64	    /// Interactive: reads (and edits) lines from the terminal.
65	    reader: Option<LineReader>,
66	    /// What was printed since the last newline: the prompt, for redraws.
67	    tail: Vec<u8>,
68	    /// SQLite for `lib/db/sqlite` (host calls; see sql.rs).
69	    sql: reva_sqlite::Sqlite,
70	}
71	
72	impl StdHost {
73	    /// The next line typed (interactive runs only), with its newline.
74	    fn read_line(&mut self) -> Input {
75	        let _ = self.out.flush();
76	        let prompt = String::from_utf8_lossy(&self.tail).into_owned();
77	        self.tail.clear();
78	        match &mut self.reader {
79	            Some(r) => r.read_line(&prompt),
80	            None => Input::Eof,
81	        }
82	    }
83	}
84	
85	/// Output and the terminal.
86	impl Console for StdHost {
87	    fn write(&mut self, bytes: &[u8]) {
88	        match &mut self.capture {
89	            Some(c) => c.extend_from_slice(bytes),
90	            None => {
91	                let _ = self.out.write_all(bytes);
92	                match bytes.iter().rposition(|&b| b == b'\n') {
93	                    Some(i) => {
94	                        self.tail.clear();
95	                        self.tail.extend_from_slice(&bytes[i + 1..]);
96	                    }
97	                    None => self.tail.extend_from_slice(bytes),
98	                }
99	                if self.tail.len() > 256 {
100	                    self.tail.drain(..self.tail.len() - 256);
101	                }
102	            }
103	        }
104	    }
105	
106	    fn color(&mut self) -> bool {
107	        self.color
108	    }
109	
110	    /// VM notes go to stderr, after what Forth printed so far.
111	    fn diag(&mut self, line: &str) {
112	        let _ = self.out.flush();
113	        eprint!("{line}");
114	    }
115	
116	    fn read_input_blocking(&mut self) -> Option<Vec<u8>> {
117	        if self.capture.is_some() {
118	            return None;
119	        }
120	        match self.read_line() {
121	            Input::Line(l) => Some(l.into_bytes()),
122	            Input::Eof => Some(Vec::new()),
123	        }
124	    }
125	}
126	
127	/// Process environment, clock and the shell.
128	impl Platform for StdHost {
129	    fn getenv(&mut self, name: &str) -> Option<String> {
130	        std::env::var(name).ok()
131	    }
132	
133	    fn setenv(&mut self, name: &str, value: &str) {
134	        // SAFETY: reva-cli runs on one thread (it starts none), so no
135	        // other thread can read the environment while it changes.
136	        unsafe { std::env::set_var(name, value) };
137	    }
138	
139	    fn now(&mut self) -> Option<(u64, u32)> {
140	        let d = SystemTime::now().duration_since(UNIX_EPOCH).ok()?;
141	        Some((d.as_secs(), d.subsec_micros()))
142	    }
143	
144	    fn sleep_ms(&mut self, ms: u32) {
145	        std::thread::sleep(Duration::from_millis(ms.into()));
146	    }
147	
148	    /// `system(3)`: `sh -c cmd`, returning the wait status as C does.
149	    /// Only with `--allow-shell`: Reva programs run OS commands freely, so
150	    /// that is a choice for whoever starts them, not for the program.
151	    fn system(&mut self, cmd: &str) -> Option<i32> {
152	        if !self.allow_shell {
153	            return None;
154	        }
155	        let _ = self.out.flush();
156	        let status = std::process::Command::new("sh").arg("-c").arg(cmd).status();
157	        Some(match status {
158	            Ok(s) => wait_status(s),
159	            Err(_) => 127 << 8,
160	        })
161	    }
162	}
163	
164	/// The real file system, and SQLite through host calls.
165	impl Resources for StdHost {
166	    fn fs(&mut self) -> Option<&mut dyn FileSystem> {
167	        Some(&mut self.fs)
168	    }
169	
170	    fn host_call(&mut self, call: &reva_vm::hostcall::HostCall) -> reva_vm::hostcall::HostAnswer {
171	        sql::answer(&mut self.sql, &mut self.fs, call)
172	    }
173	}
174	
175	#[cfg(unix)]
176	fn wait_status(s: std::process::ExitStatus) -> i32 {
177	    use std::os::unix::process::ExitStatusExt;
178	    s.into_raw()
179	}
180	
181	#[cfg(not(unix))]
182	fn wait_status(s: std::process::ExitStatus) -> i32 {
183	    s.code().unwrap_or(-1)
184	}
185	
186	#[derive(Default)]
187	struct Options {
188	    files: Vec<String>,
189	    evals: Vec<String>,
190	    boot: Option<String>,
191	    no_boot: bool,
192	    image: Option<String>,
193	    save_image: Option<String>,
194	    show_boot: bool,
195	    trace: bool,
196	    allow_shell: bool,
197	    no_edit: bool,
198	    color: Option<bool>,
199	}
200	
201	fn parse_args() -> Result<Options, String> {
202	    let mut o = Options::default();
203	    let mut args = std::env::args().skip(1);
204	    while let Some(a) = args.next() {
205	        let mut value = |name: &str| args.next().ok_or(format!("{name} needs a value"));
206	        match a.as_str() {
207	            "-e" | "--eval" => o.evals.push(value(&a)?),
208	            "--boot" => o.boot = Some(value(&a)?),
209	            "--no-boot" => o.no_boot = true,
210	            "--image" => o.image = Some(value(&a)?),
211	            "--save-image" => o.save_image = Some(value(&a)?),
212	            "--show-boot" => o.show_boot = true,
213	            "--trace" => o.trace = true,
214	            "--allow-shell" => o.allow_shell = true,
215	            "--no-edit" => o.no_edit = true,
216	            "--color" => {
217	                o.color = match value(&a)?.as_str() {
218	                    "auto" => None,
219	                    "always" => Some(true),
220	                    "never" => Some(false),
221	                    w => return Err(format!("--color {w}: expected auto, always or never")),
222	                }
223	            }
224	            "-h" | "--help" => {
225	                print!("{USAGE}");
226	                std::process::exit(0);
227	            }
228	            "-V" | "--version" => {
229	                print!("{}", version::info());
230	                std::process::exit(0);
231	            }
232	            s if s.starts_with('-') && s.len() > 1 => return Err(format!("unknown option {s}")),
233	            _ => o.files.push(a),
234	        }
235	    }
236	    Ok(o)
237	}
238	
239	/// `--color auto`: stdout is a terminal that takes ANSI escapes, and
240	/// `NO_COLOR` (no-color.org) is unset.  On Windows only where the console is
241	/// known to take them (Windows Terminal, or a `TERM` such as mintty's).
242	fn color_auto() -> bool {
243	    let env = |n: &str| std::env::var(n).ok().filter(|v| !v.is_empty());
244	    let ansi = if cfg!(windows) {
245	        env("WT_SESSION").is_some() || env("TERM").is_some_and(|t| t != "dumb")
246	    } else {
247	        env("TERM").is_none_or(|t| t != "dumb")
248	    };
249	    io::stdout().is_terminal() && env("NO_COLOR").is_none() && ansi
250	}
251	
252	fn exit_code(code: i32) -> ExitCode {
253	    ExitCode::from((code & 0xff) as u8)
254	}
255	
256	fn main() -> ExitCode {
257	    let opts = match parse_args() {
258	        Ok(o) => o,
259	        Err(e) => {
260	            eprintln!("reva: {e}\n{USAGE}");
261	            return ExitCode::from(2);
262	        }
263	    };
264	
265	    let boot_path = opts
266	        .boot
267	        .clone()
268	        .unwrap_or_else(|| embedded::BOOT_PATH.to_string());
269	    let (start, mut vm) = match &opts.image {
270	        Some(path) => {
271	            let loaded = std::fs::read(path)
272	                .map_err(|e| e.to_string())
273	                .and_then(|b| Start::image(b).map_err(|e| e.to_string()));
274	            match loaded {
275	                Ok(sm) => sm,
276	                Err(e) => {
277	                    eprintln!("reva: {path}: {e}");
278	                    return ExitCode::from(2);
279	                }
280	            }
281	        }
282	        None => {
283	            let mut args = vec!["reva".to_string()];
284	            if !opts.no_boot {
285	                args.push(boot_path);
286	            }
287	            let start = Start::Boot(args);
288	            let vm = start
289	                .machine()
290	                .expect("a boot start always makes a machine");
291	            (start, vm)
292	        }
293	    };
294	    let run = Run {
295	        interactive: io::stdin().is_terminal() && opts.save_image.is_none(),
296	        opts: &opts,
297	        start,
298	    };
299	    let mut host = StdHost {
300	        out: io::BufWriter::new(io::stdout()),
301	        fs: fs::StdFs::default(),
302	        capture: None,
303	        allow_shell: opts.allow_shell,
304	        reader: run.interactive.then(|| LineReader::new(!opts.no_edit)),
305	        tail: Vec::new(),
306	        color: opts.color.unwrap_or_else(color_auto),
307	        sql: sql::new(),
308	    };
309	    if let Err(code) = run.begin(&mut vm, &mut host) {
310	        return code;
311	    }
312	    let status = run.until_blocked(&mut vm, &mut host);
313	    let _ = host.out.flush();
314	    match status {
315	        Ok(Status::Halted(code)) => return exit_code(code),
316	        Err(code) => return code,
317	        Ok(_) => {}
318	    }
319	
320	    if let Some(path) = &opts.save_image {
321	        if let Err(e) = std::fs::write(path, vm.save_image()) {
322	            eprintln!("reva: {path}: {e}");
323	            return ExitCode::from(2);
324	        }
325	        return ExitCode::SUCCESS;
326	    }
327	
328	    let stdin = io::stdin();
329	    if !stdin.is_terminal() {
330	        let mut all = Vec::new();
331	        if let Err(e) = stdin.lock().read_to_end(&mut all) {
332	            eprintln!("reva: stdin: {e}");
333	        }
334	        vm.feed(&all);
335	        vm.close_input();
336	        let status = run.until_blocked(&mut vm, &mut host);
337	        let _ = host.out.flush();
338	        return match status {
339	            Ok(Status::Halted(code)) => exit_code(code),
340	            Err(code) => code,
341	            Ok(_) => ExitCode::SUCCESS,
342	        };
343	    }
344	
345	    // Interactive: one line at a time; reva.f prints the prompt.
346	    loop {
347	        match host.read_line() {
348	            Input::Eof => vm.close_input(),
349	            Input::Line(l) => vm.feed(l.as_bytes()),
350	        }
351	        let status = run.until_blocked(&mut vm, &mut host);
352	        let _ = host.out.flush();
353	        match status {
354	            Ok(Status::Halted(code)) => return exit_code(code),
355	            Err(code) => return code,
356	            Ok(_) => {}
357	        }
358	    }
359	}
360	
361	/// How this run starts, kept for `restart`.
362	struct Run<'a> {
363	    opts: &'a Options,
364	    start: Start,
365	    interactive: bool,
366	}
367	
368	impl Run<'_> {
369	    /// Start `vm`: boot quietly (reva.f prints progress marks, then, as the
370	    /// restarted system, its banner and first prompt; anything else means
371	    /// the boot went wrong, so show it), then queue the files and `-e`
372	    /// texts.
373	    fn begin(&self, vm: &mut Machine, host: &mut StdHost) -> Result<(), ExitCode> {
374	        let opts = self.opts;
375	        host.capture = Some(Vec::new());
376	        let status = vm.run_until_blocked(host);
377	        let boot_out = host.capture.take().unwrap_or_default();
378	        match status {
379	            Status::Halted(code) => {
380	                io::stdout().write_all(&boot_out).ok();
381	                eprintln!("reva: halted during boot");
382	                return Err(exit_code(code));
383	            }
384	            Status::Restart => {
385	                io::stdout().write_all(&boot_out).ok();
386	                eprintln!("reva: restart during boot");
387	                return Err(ExitCode::from(2));
388	            }
389	            _ => {}
390	        }
391	        let boot_out = String::from_utf8_lossy(&boot_out).into_owned();
392	        let (marks, rest) = embedded::split_boot_output(&boot_out);
393	        let normal =
394	            !rest.contains("***") && (rest.is_empty() || rest.starts_with(version::BANNER));
395	        if opts.show_boot || !normal {
396	            eprint!("{marks}{rest}");
397	            if !boot_out.ends_with('\n') && !boot_out.is_empty() {
398	                eprintln!();
399	            }
400	        }
401	        if self.interactive {
402	            // The banner and first `ok>` prompt, as Reva showed them.
403	            if normal && !opts.show_boot {
404	                host.write(rest.as_bytes());
405	            }
406	        } else {
407	            vm.quiet_prompt();
408	        }
409	        vm.set_trace(opts.trace);
410	
411	        let mut pending = Vec::new();
412	        for f in &opts.files {
413	            pending.extend_from_slice(format!("include {f}\n").as_bytes());
414	        }
415	        for e in &opts.evals {
416	            pending.extend_from_slice(e.as_bytes());
417	            pending.push(b'\n');
418	        }
419	        vm.feed(&pending);
420	        Ok(())
421	    }
422	
423	    /// Run until `vm` needs input or halts; on `restart`, start a new
424	    /// machine the same way and hand it the input not yet read.
425	    fn until_blocked(&self, vm: &mut Machine, host: &mut StdHost) -> Result<Status, ExitCode> {
426	        loop {
427	            match vm.run_until_blocked(host) {
428	                Status::Restart => {
429	                    let (input, closed) = vm.take_input();
430	                    *vm = self.start.machine().map_err(|e| {
431	                        eprintln!("reva: restart: {e}");
432	                        ExitCode::from(2)
433	                    })?;
434	                    self.begin(vm, host)?;
435	                    vm.feed(&input);
436	                    if closed {
437	                        vm.close_input();
438	                    }
439	                }
440	                s => return Ok(s),
441	            }
442	        }
443	    }
444	}
