1	//! The real file system, for `reva.f`'s file words on the command line.
2	//!
3	//! Paths are resolved against the process's working directory (which
4	//! `chdir` changes).  The core's virtual install prefix `/reva/` maps to
5	//! [`install_root`]; below it, `lib/` falls back to the copy compiled into
6	//! the core when the file is not on disk, so an installed `reva` binary
7	//! runs `needs` without a checkout.
8	
9	use std::collections::BTreeMap;
10	use std::fs::{self, File};
11	use std::io::{self, Read, Seek, SeekFrom, Write};
12	use std::path::{Path, PathBuf};
13	use std::time::UNIX_EPOCH;
14	
15	use reva_vm::embedded;
16	use reva_vm::vfs::{self, Access, Errno, FIRST_FD, FsDirs, FsFiles, FsMeta, Stat, errno::*};
17	
18	/// Where `/reva/...` lives on disk: `$REVA_HOME`, else the checkout this
19	/// binary was built from.
20	pub fn install_root() -> PathBuf {
21	    match std::env::var_os("REVA_HOME") {
22	        Some(h) => PathBuf::from(h),
23	        None => Path::new(env!("CARGO_MANIFEST_DIR")).join("../../../.."),
24	    }
25	}
26	
27	/// An `io::Error` as a Linux `errno`.
28	fn errno(e: io::Error) -> Errno {
29	    #[cfg(target_os = "linux")]
30	    if let Some(n) = e.raw_os_error() {
31	        return n as Errno;
32	    }
33	    match e.kind() {
34	        io::ErrorKind::NotFound => ENOENT,
35	        io::ErrorKind::PermissionDenied => EACCES,
36	        io::ErrorKind::AlreadyExists => EEXIST,
37	        _ => EINVAL,
38	    }
39	}
40	
41	enum Handle {
42	    Disk {
43	        file: File,
44	        access: Access,
45	    },
46	    /// An embedded library file (read-only).
47	    Embedded {
48	        data: &'static [u8],
49	        pos: u64,
50	    },
51	}
52	
53	#[derive(Default)]
54	pub struct StdFs {
55	    open: BTreeMap<u32, Handle>,
56	}
57	
58	impl StdFs {
59	    /// (virtual absolute path, host path)
60	    pub(crate) fn resolve(&mut self, path: &str) -> (String, PathBuf) {
61	        let v = vfs::normalize(&self.cwd(), path);
62	        let host = match embedded::install_relative(&v) {
63	            Some(rel) => install_root().join(rel),
64	            None => host_path(&v, cfg!(windows)),
65	        };
66	        (v, host)
67	    }
68	
69	    fn insert(&mut self, h: Handle) -> u32 {
70	        let fd = (FIRST_FD..)
71	            .find(|f| !self.open.contains_key(f))
72	            .unwrap_or(u32::MAX);
73	        self.open.insert(fd, h);
74	        fd
75	    }
76	
77	    fn handle(&mut self, fd: u32) -> Result<&mut Handle, Errno> {
78	        self.open.get_mut(&fd).ok_or(EBADF)
79	    }
80	}
81	
82	fn stat_of(m: &fs::Metadata) -> Stat {
83	    let mtime = m
84	        .modified()
85	        .ok()
86	        .and_then(|t| t.duration_since(UNIX_EPOCH).ok())
87	        .map_or(0, |d| d.as_secs());
88	    Stat {
89	        size: m.len(),
90	        dir: m.is_dir(),
91	        mtime,
92	    }
93	}
94	
95	impl FsFiles for StdFs {
96	    fn open(&mut self, path: &str, access: Access) -> Result<u32, Errno> {
97	        let (v, p) = self.resolve(path);
98	        if p.is_dir() {
99	            return Err(EISDIR);
100	        }
101	        let file = match access {
102	            Access::Read => File::open(&p),
103	            Access::ReadWrite => File::options().read(true).write(true).open(&p),
104	            Access::Create => File::create(&p),
105	        };
106	        match file {
107	            Ok(file) => Ok(self.insert(Handle::Disk { file, access })),
108	            Err(e) if e.kind() == io::ErrorKind::NotFound && access == Access::Read => {
109	                let data = embedded::lib_file(&v).ok_or(ENOENT)?;
110	                Ok(self.insert(Handle::Embedded { data, pos: 0 }))
111	            }
112	            Err(e) => Err(errno(e)),
113	        }
114	    }
115	
116	    fn close(&mut self, fd: u32) -> Result<(), Errno> {
117	        self.open.remove(&fd).map(drop).ok_or(EBADF)
118	    }
119	
120	    fn read(&mut self, fd: u32, buf: &mut [u8]) -> Result<usize, Errno> {
121	        match self.handle(fd)? {
122	            Handle::Disk {
123	                access: Access::Create,
124	                ..
125	            } => Err(EBADF),
126	            Handle::Disk { file, .. } => file.read(buf).map_err(errno),
127	            Handle::Embedded { data, pos } => {
128	                let start = (*pos as usize).min(data.len());
129	                let n = buf.len().min(data.len() - start);
130	                buf[..n].copy_from_slice(&data[start..start + n]);
131	                *pos += n as u64;
132	                Ok(n)
133	            }
134	        }
135	    }
136	
137	    fn write(&mut self, fd: u32, data: &[u8]) -> Result<usize, Errno> {
138	        match self.handle(fd)? {
139	            Handle::Disk {
140	                access: Access::Read,
141	                ..
142	            }
143	            | Handle::Embedded { .. } => Err(EBADF),
144	            Handle::Disk { file, .. } => file.write_all(data).map(|()| data.len()).map_err(errno),
145	        }
146	    }
147	
148	    fn seek(&mut self, fd: u32, offset: i64, whence: u32) -> Result<u64, Errno> {
149	        let to = match whence {
150	            vfs::SEEK_SET => SeekFrom::Start(u64::try_from(offset).map_err(|_| EINVAL)?),
151	            vfs::SEEK_CUR => SeekFrom::Current(offset),
152	            vfs::SEEK_END => SeekFrom::End(offset),
153	            _ => return Err(EINVAL),
154	        };
155	        match self.handle(fd)? {
156	            Handle::Disk { file, .. } => file.seek(to).map_err(errno),
157	            Handle::Embedded { data, pos } => {
158	                let base = match to {
159	                    SeekFrom::Start(_) => 0,
160	                    SeekFrom::Current(_) => *pos as i64,
161	                    SeekFrom::End(_) => data.len() as i64,
162	                };
163	                let p = base.checked_add(offset).filter(|p| *p >= 0).ok_or(EINVAL)?;
164	                *pos = p as u64;
165	                Ok(*pos)
166	            }
167	        }
168	    }
169	}
170	
171	impl FsMeta for StdFs {
172	    fn fstat(&mut self, fd: u32) -> Result<Stat, Errno> {
173	        match self.handle(fd)? {
174	            Handle::Disk { file, .. } => file.metadata().map(|m| stat_of(&m)).map_err(errno),
175	            Handle::Embedded { data, .. } => Ok(Stat {
176	                size: data.len() as u64,
177	                ..Stat::default()
178	            }),
179	        }
180	    }
181	
182	    fn stat(&mut self, path: &str) -> Result<Stat, Errno> {
183	        let (v, p) = self.resolve(path);
184	        match fs::metadata(&p) {
185	            Ok(m) => Ok(stat_of(&m)),
186	            Err(e) => match (embedded::lib_file(&v), embedded::lib_dir(&v)) {
187	                (Some(d), _) => Ok(Stat {
188	                    size: d.len() as u64,
189	                    ..Stat::default()
190	                }),
191	                (None, Some(_)) => Ok(Stat {
192	                    dir: true,
193	                    ..Stat::default()
194	                }),
195	                _ => Err(errno(e)),
196	            },
197	        }
198	    }
199	
200	    fn remove(&mut self, path: &str) -> Result<(), Errno> {
201	        let (_, p) = self.resolve(path);
202	        if p.is_dir() {
203	            return Err(EISDIR);
204	        }
205	        fs::remove_file(p).map_err(errno)
206	    }
207	
208	    fn rename(&mut self, from: &str, to: &str) -> Result<(), Errno> {
209	        let (_, a) = self.resolve(from);
210	        let (_, b) = self.resolve(to);
211	        fs::rename(a, b).map_err(errno)
212	    }
213	
