133	        let mut h = History::in_memory();
134	        for l in ["dup", "swap", "dup dup", "drop"] {
135	            h.add(l);
136	        }
137	        assert_eq!(h.search_back("dup", 4), Some(2));
138	        assert_eq!(h.search_back("dup", 2), Some(0));
139	        assert_eq!(h.search_back("dup", 0), None);
140	        assert_eq!(h.search_forward("dup", 0), Some(2));
141	        assert_eq!(h.search_forward("dup", 2), None);
142	    }
143	
144	    #[test]
145	    fn file_round_trip_and_trim() {
146	        let dir = std::env::temp_dir().join(format!("reva-hist-{}", std::process::id()));
147	        let _ = fs::create_dir_all(&dir);
148	        let path = dir.join("h");
149	        let many: String = (0..2 * MAX + 5).map(|i| format!("{i} .\n")).collect();
150	        fs::write(&path, many).unwrap();
151	        let mut h = History::open(path.clone());
152	        assert_eq!(h.len(), MAX);
153	        assert_eq!(h.get(MAX - 1), Some(&*format!("{} .", 2 * MAX + 4)));
154	        h.add("words");
155	        let again = History::open(path.clone());
156	        assert_eq!(again.get(again.len() - 1), Some("words"));
157	        assert_eq!(fs::read_to_string(&path).unwrap().lines().count(), MAX + 1);
158	        let _ = fs::remove_dir_all(dir);
159	    }
160	}
