1	//! The real file system, for `reva.f`'s file words on the command line.
2	//!
3	//! Paths are resolved against the process's working directory (which
4	//! `chdir` changes).  The core's virtual install prefix `/reva/` maps to
5	//! [`install_root`]; below it, `lib/` falls back to the copy compiled into
6	//! the core when the file is not on disk, so an installed `reva` binary
7	//! runs `needs` without a checkout.
8	
9	use std::collections::BTreeMap;
10	use std::fs::{self, File};
11	use std::io::{self, Read, Seek, SeekFrom, Write};
12	use std::path::{Path, PathBuf};
13	use std::time::UNIX_EPOCH;
14	
15	use reva_vm::embedded;
16	use reva_vm::vfs::{self, Access, Errno, FIRST_FD, FsDirs, FsFiles, FsMeta, Stat, errno::*};
17	
18	/// Where `/reva/...` lives on disk: `$REVA_HOME`, else the checkout this
19	/// binary was built from.
20	pub fn install_root() -> PathBuf {
21	    match std::env::var_os("REVA_HOME") {
22	        Some(h) => PathBuf::from(h),
23	        None => Path::new(env!("CARGO_MANIFEST_DIR")).join("../../../.."),
24	    }
25	}
26	
27	/// An `io::Error` as a Linux `errno`.
28	fn errno(e: io::Error) -> Errno {
29	    #[cfg(target_os = "linux")]
30	    if let Some(n) = e.raw_os_error() {
31	        return n as Errno;
32	    }
33	    match e.kind() {
34	        io::ErrorKind::NotFound => ENOENT,
35	        io::ErrorKind::PermissionDenied => EACCES,
36	        io::ErrorKind::AlreadyExists => EEXIST,
37	        _ => EINVAL,
38	    }
39	}
40	
41	enum Handle {
42	    Disk {
43	        file: File,
44	        access: Access,
45	    },
46	    /// An embedded library file (read-only).
47	    Embedded {
48	        data: &'static [u8],
49	        pos: u64,
50	    },
51	}
52	
53	#[derive(Default)]
54	pub struct StdFs {
55	    open: BTreeMap<u32, Handle>,
56	}
57	
58	impl StdFs {
59	    /// (virtual absolute path, host path)
60	    pub(crate) fn resolve(&mut self, path: &str) -> (String, PathBuf) {
61	        let v = vfs::normalize(&self.cwd(), path);
62	        let host = match embedded::install_relative(&v) {
63	            Some(rel) => install_root().join(rel),
64	            None => host_path(&v, cfg!(windows)),
65	        };
66	        (v, host)
67	    }
68	
69	    fn insert(&mut self, h: Handle) -> u32 {
70	        let fd = (FIRST_FD..)
71	            .find(|f| !self.open.contains_key(f))
72	            .unwrap_or(u32::MAX);
73	        self.open.insert(fd, h);
74	        fd
75	    }
76	
77	    fn handle(&mut self, fd: u32) -> Result<&mut Handle, Errno> {
78	        self.open.get_mut(&fd).ok_or(EBADF)
79	    }
80	}
81	
82	fn stat_of(m: &fs::Metadata) -> Stat {
83	    let mtime = m
84	        .modified()
85	        .ok()
86	        .and_then(|t| t.duration_since(UNIX_EPOCH).ok())
87	        .map_or(0, |d| d.as_secs());
88	    Stat {
89	        size: m.len(),
90	        dir: m.is_dir(),
91	        mtime,
92	    }
93	}
94	
95	impl FsFiles for StdFs {
96	    fn open(&mut self, path: &str, access: Access) -> Result<u32, Errno> {
97	        let (v, p) = self.resolve(path);
98	        if p.is_dir() {
99	            return Err(EISDIR);
100	        }
101	        let file = match access {
102	            Access::Read => File::open(&p),
103	            Access::ReadWrite => File::options().read(true).write(true).open(&p),
104	            Access::Create => File::create(&p),
105	        };
106	        match file {
107	            Ok(file) => Ok(self.insert(Handle::Disk { file, access })),
108	            Err(e) if e.kind() == io::ErrorKind::NotFound && access == Access::Read => {
109	                let data = embedded::lib_file(&v).ok_or(ENOENT)?;
110	                Ok(self.insert(Handle::Embedded { data, pos: 0 }))
111	            }
112	            Err(e) => Err(errno(e)),
113	        }
114	    }
115	
116	    fn close(&mut self, fd: u32) -> Result<(), Errno> {
117	        self.open.remove(&fd).map(drop).ok_or(EBADF)
118	    }
119	
120	    fn read(&mut self, fd: u32, buf: &mut [u8]) -> Result<usize, Errno> {
121	        match self.handle(fd)? {
122	            Handle::Disk {
123	                access: Access::Create,
124	                ..
125	            } => Err(EBADF),
126	            Handle::Disk { file, .. } => file.read(buf).map_err(errno),
127	            Handle::Embedded { data, pos } => {
128	                let start = (*pos as usize).min(data.len());
129	                let n = buf.len().min(data.len() - start);
130	                buf[..n].copy_from_slice(&data[start..start + n]);
131	                *pos += n as u64;
132	                Ok(n)
133	            }
134	        }
135	    }
136	
137	    fn write(&mut self, fd: u32, data: &[u8]) -> Result<usize, Errno> {
138	        match self.handle(fd)? {
139	            Handle::Disk {
140	                access: Access::Read,
141	                ..
142	            }
143	            | Handle::Embedded { .. } => Err(EBADF),
144	            Handle::Disk { file, .. } => file.write_all(data).map(|()| data.len()).map_err(errno),
145	        }
146	    }
147	
148	    fn seek(&mut self, fd: u32, offset: i64, whence: u32) -> Result<u64, Errno> {
149	        let to = match whence {
150	            vfs::SEEK_SET => SeekFrom::Start(u64::try_from(offset).map_err(|_| EINVAL)?),
151	            vfs::SEEK_CUR => SeekFrom::Current(offset),
152	            vfs::SEEK_END => SeekFrom::End(offset),
153	            _ => return Err(EINVAL),
154	        };
155	        match self.handle(fd)? {
156	            Handle::Disk { file, .. } => file.seek(to).map_err(errno),
157	            Handle::Embedded { data, pos } => {
158	                let base = match to {
159	                    SeekFrom::Start(_) => 0,
160	                    SeekFrom::Current(_) => *pos as i64,
161	                    SeekFrom::End(_) => data.len() as i64,
162	                };
163	                let p = base.checked_add(offset).filter(|p| *p >= 0).ok_or(EINVAL)?;
164	                *pos = p as u64;
165	                Ok(*pos)
166	            }
167	        }
168	    }
169	}
170	
171	impl FsMeta for StdFs {
172	    fn fstat(&mut self, fd: u32) -> Result<Stat, Errno> {
173	        match self.handle(fd)? {
174	            Handle::Disk { file, .. } => file.metadata().map(|m| stat_of(&m)).map_err(errno),
175	            Handle::Embedded { data, .. } => Ok(Stat {
176	                size: data.len() as u64,
177	                ..Stat::default()
178	            }),
179	        }
180	    }
181	
182	    fn stat(&mut self, path: &str) -> Result<Stat, Errno> {
183	        let (v, p) = self.resolve(path);
184	        match fs::metadata(&p) {
185	            Ok(m) => Ok(stat_of(&m)),
186	            Err(e) => match (embedded::lib_file(&v), embedded::lib_dir(&v)) {
187	                (Some(d), _) => Ok(Stat {
188	                    size: d.len() as u64,
189	                    ..Stat::default()
190	                }),
191	                (None, Some(_)) => Ok(Stat {
192	                    dir: true,
193	                    ..Stat::default()
194	                }),
195	                _ => Err(errno(e)),
196	            },
197	        }
198	    }
199	
200	    fn remove(&mut self, path: &str) -> Result<(), Errno> {
201	        let (_, p) = self.resolve(path);
202	        if p.is_dir() {
203	            return Err(EISDIR);
204	        }
205	        fs::remove_file(p).map_err(errno)
206	    }
207	
208	    fn rename(&mut self, from: &str, to: &str) -> Result<(), Errno> {
209	        let (_, a) = self.resolve(from);
210	        let (_, b) = self.resolve(to);
211	        fs::rename(a, b).map_err(errno)
212	    }
213	
214	    fn mkdir(&mut self, path: &str) -> Result<(), Errno> {
215	        let (_, p) = self.resolve(path);
216	        fs::create_dir(p).map_err(errno)
217	    }
218	}
219	
220	impl FsDirs for StdFs {
221	    fn rmdir(&mut self, path: &str) -> Result<(), Errno> {
222	        let (_, p) = self.resolve(path);
223	        fs::remove_dir(p).map_err(errno)
224	    }
225	
226	    fn list_dir(&mut self, path: &str) -> Result<Vec<String>, Errno> {
227	        let (v, p) = self.resolve(path);
228	        let mut names: Vec<String> = match fs::read_dir(&p) {
229	            Ok(rd) => rd
230	                .flatten()
231	                .map(|e| e.file_name().to_string_lossy().into_owned())
232	                .collect(),
233	            Err(e) => match embedded::lib_dir(&v) {
234	                Some(_) => Vec::new(),
235	                None => return Err(errno(e)),
236	            },
237	        };
238	        for n in embedded::lib_dir(&v).unwrap_or_default() {
239	            if !names.contains(&n) {
240	                names.push(n);
241	            }
242	        }
243	        Ok(names)
244	    }
245	
246	    fn chdir(&mut self, path: &str) -> Result<(), Errno> {
247	        let (_, p) = self.resolve(path);
248	        std::env::set_current_dir(p).map_err(errno)
249	    }
250	
251	    fn cwd(&mut self) -> String {
252	        std::env::current_dir()
253	            .map(|p| vm_path(&p.to_string_lossy(), cfg!(windows)))
254	            .unwrap_or_else(|_| "/".to_string())
255	    }
256	}
257	
258	/// A host path as the VM sees it: rooted at `/` and `/`-separated, which is
259	/// what [`vfs::normalize`] works on.  On Windows `C:\a\b` is `/C:/a/b` (and
260	/// a verbatim `\\?\` prefix is dropped); elsewhere the path is unchanged.
261	fn vm_path(host: &str, windows: bool) -> String {
262	    if !windows {
263	        return host.to_string();
264	    }
265	    let p = host
266	        .strip_prefix(r"\\?\")
267	        .unwrap_or(host)
268	        .replace('\\', "/");
269	    if p.starts_with('/') {
270	        p
271	    } else {
272	        format!("/{p}")
273	    }
274	}
275	
276	/// The host path for a VM path: the inverse of [`vm_path`].  On Windows
277	/// `/C:/a/b` is `C:/a/b`, which Windows accepts; a VM path without a drive
278	/// (`/a/b`) stays on the current drive.
279	fn host_path(vm: &str, windows: bool) -> PathBuf {
280	    let b = vm.as_bytes();
281	    if windows && b.len() >= 3 && b[0] == b'/' && b[1].is_ascii_alphabetic() && b[2] == b':' {
282	        PathBuf::from(&vm[1..])
283	    } else {
284	        PathBuf::from(vm)
285	    }
286	}
287	
288	#[cfg(test)]
289	mod tests {
290	    use super::*;
291	
292	    #[test]
293	    fn windows_paths_round_trip_through_the_vm() {
294	        let v = vm_path(r"C:\Users\mike\cosy", true);
295	        assert_eq!(v, "/C:/Users/mike/cosy");
296	        assert_eq!(vm_path(r"\\?\D:\work", true), "/D:/work");
297	        let file = vfs::normalize(&v, "../reva/t.f");
298	        assert_eq!(file, "/C:/Users/mike/reva/t.f");
299	        assert_eq!(
300	            host_path(&file, true),
301	            PathBuf::from("C:/Users/mike/reva/t.f")
302	        );
303	        assert_eq!(host_path("/tmp/x", true), PathBuf::from("/tmp/x"));
304	    }
305	
306	    #[test]
307	    fn unix_paths_are_unchanged() {
308	        assert_eq!(vm_path("/home/mike", false), "/home/mike");
309	        assert_eq!(host_path("/C:/x", false), PathBuf::from("/C:/x"));
310	    }
311	}
312

1	//! REPL history: the lines typed at the prompt, oldest first, kept in a
2	//! plain text file (one entry per line) so they survive `bye`, crashes and
3	//! the `run-cosy` restart loop.
4	//!
5	//! Where: `$REVA_HISTORY` if set (empty: keep history in memory only),
6	//! else `~/.reva_history`.  A package's launcher picks its own file
7	//! (`run-cosy` uses `~/.cosy_history`), so packages keep their histories
8	//! apart, as the web page does with its per-package storage key.
9	//!
10	//! Each accepted line is appended to the file at once (no rewrite, so two
11	//! sessions at a time lose nothing; their lines interleave).  The file is
12	//! rewritten only when loading finds it at more than twice [`MAX`]
13	//! entries, to keep it bounded.  Blank lines and a repeat of the last entry
14	//! are not recorded.  Errors are ignored: history is a convenience and must
15	//! never stop the REPL.
16	
17	use std::fs::{self, OpenOptions};
18	use std::io::Write;
19	use std::path::PathBuf;
20	
21	/// Entries kept (and loaded).
22	pub const MAX: usize = 1000;
23	
24	/// The history list, and the file it is kept in.
25	#[derive(Debug, Default)]
26	pub struct History {
27	    entries: Vec<String>,
28	    path: Option<PathBuf>,
29	}
30	
31	impl History {
32	    /// An empty history kept in memory only (tests, `REVA_HISTORY=`).
33	    pub fn in_memory() -> Self {
34	        Self::default()
35	    }
36	
37	    /// The history at the default place (see the module docs), loaded.
38	    pub fn open_default() -> Self {
39	        let path = match std::env::var_os("REVA_HISTORY") {
40	            Some(p) if p.is_empty() => None,
41	            Some(p) => Some(PathBuf::from(p)),
42	            None => home().map(|h| h.join(".reva_history")),
43	        };
44	        match path {
45	            Some(p) => Self::open(p),
46	            None => Self::in_memory(),
47	        }
48	    }
49	
50	    /// The history kept in `path`, loaded (a missing file is empty).
51	    pub fn open(path: PathBuf) -> Self {
52	        let text = fs::read_to_string(&path).unwrap_or_default();
53	        let all: Vec<String> = text
54	            .lines()
55	            .filter(|l| !l.trim().is_empty())
56	            .map(str::to_string)
57	            .collect();
58	        let entries = all[all.len().saturating_sub(MAX)..].to_vec();
59	        if all.len() > 2 * MAX {
60	            let mut keep = entries.join("\n");
61	            keep.push('\n');
62	            let _ = fs::write(&path, keep);
63	        }
64	        Self {
65	            entries,
66	            path: Some(path),
67	        }
68	    }
69	
70	    /// Number of entries.
71	    pub fn len(&self) -> usize {
72	        self.entries.len()
73	    }
74	
75	    /// Entry `i` (0 is the oldest).
76	    pub fn get(&self, i: usize) -> Option<&str> {
77	        self.entries.get(i).map(String::as_str)
78	    }
79	
80	    /// Record `line` (without its newline), unless it is blank or repeats
81	    /// the last entry.
82	    pub fn add(&mut self, line: &str) {
83	        let line = line.trim_end_matches(['\r', '\n']);
84	        if line.trim().is_empty() || self.entries.last().map(String::as_str) == Some(line) {
85	            return;
86	        }
87	        self.entries.push(line.to_string());
88	        if self.entries.len() > MAX {
89	            self.entries.remove(0);
90	        }
91	        if let Some(path) = &self.path
92	            && let Ok(mut f) = OpenOptions::new().create(true).append(true).open(path)
93	        {
94	            let _ = writeln!(f, "{line}");
95	        }
96	    }
97	
98	    /// The newest entry before `from` (exclusive) containing `query`.
99	    pub fn search_back(&self, query: &str, from: usize) -> Option<usize> {
100	        (0..from.min(self.entries.len()))
101	            .rev()
102	            .find(|&i| self.entries[i].contains(query))
103	    }
104	
105	    /// The oldest entry after `from` (exclusive) containing `query`.
