//! The embedded site: files by path, and their media types.

/// What `build.rs` embedded: `NAME`, `PORT`, `FILES`.
pub mod embedded {
    include!(concat!(env!("OUT_DIR"), "/site.rs"));
}

/// The embedded site.
pub static SITE: Site = Site {
    name: embedded::NAME,
    files: embedded::FILES,
};

/// The path that tells a running copy of this app apart from other servers
/// (see [`Site::probe`]).
pub const PROBE: &str = "/.reva-serve";

/// A static site: `(path, bytes)` sorted by path, paths relative, `/`-separated.
pub struct Site {
    /// The app's name (`reva`, `cosy`, ...).
    pub name: &'static str,
    /// The files, sorted by path.
    pub files: &'static [(&'static str, &'static [u8])],
}

impl Site {
    /// The file for URL path `path` (absolute, decoded): `/` and `/dir/`
    /// mean `index.html` there.  Returns the file's own path and bytes.
    pub fn lookup(&self, path: &str) -> Option<(&'static str, &'static [u8])> {
        let rel = path.strip_prefix('/')?;
        if rel.split('/').any(|s| s == "..") {
            return None;
        }
        let want = if rel.is_empty() || rel.ends_with('/') {
            format!("{rel}index.html")
        } else {
            rel.to_string()
        };
        let i = self
            .files
            .binary_search_by(|(p, _)| (*p).cmp(want.as_str()))
            .ok()?;
        Some(self.files[i])
    }

    /// What [`PROBE`] answers: `reva-serve NAME VERSION`, so a second launch
    /// can recognise the first and just open the browser on it.
    pub fn probe(&self) -> String {
        format!("reva-serve {} {}\n", self.name, env!("CARGO_PKG_VERSION"))
    }
}

/// The media type for a file, by extension.  `.wasm` must be
/// `application/wasm` for streaming compilation; `.f` and other Forth
/// sources are text.
pub fn mime(path: &str) -> &'static str {
    let ext = path.rsplit_once('.').map_or("", |(_, e)| e);
    match ext.to_ascii_lowercase().as_str() {
        "html" | "htm" => "text/html; charset=utf-8",
        "js" | "mjs" => "text/javascript; charset=utf-8",
        "css" => "text/css; charset=utf-8",
        "json" => "application/json",
        "wasm" => "application/wasm",
        "png" => "image/png",
        "ico" => "image/x-icon",
        "svg" => "image/svg+xml",
        "jpg" | "jpeg" => "image/jpeg",
        "txt" | "md" | "f" | "fs" | "4th" | "csv" => "text/plain; charset=utf-8",
        _ => "application/octet-stream",
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    static FILES: &[(&str, &[u8])] = &[
        ("a.js", b"js"),
        ("index.html", b"top"),
        ("pkg/index.html", b"pkg"),
        ("pkg/x.f", b"x"),
    ];
    const SITE: Site = Site {
        name: "t",
        files: FILES,
    };

    #[test]
    fn finds_files_and_index_pages() {
        assert_eq!(SITE.lookup("/").map(|f| f.1), Some(&b"top"[..]));
        assert_eq!(SITE.lookup("/pkg/").map(|f| f.1), Some(&b"pkg"[..]));
        assert_eq!(SITE.lookup("/pkg/x.f").map(|f| f.0), Some("pkg/x.f"));
        assert_eq!(SITE.lookup("/pkg"), None);
        assert_eq!(SITE.lookup("/nope"), None);
        assert_eq!(SITE.lookup("/pkg/../a.js"), None);
        assert_eq!(SITE.lookup("a.js"), None);
    }

    #[test]
    fn media_types() {
        assert_eq!(mime("reva.wasm"), "application/wasm");
        assert_eq!(mime("x/CoSy.f"), "text/plain; charset=utf-8");
        assert_eq!(mime("INDEX.HTML"), "text/html; charset=utf-8");
        assert_eq!(mime("noext"), "application/octet-stream");
    }
}
//! Just enough HTTP/1.1 to serve static files to one local browser.
//!
//! One request per connection (`Connection: close`): the page loads about a
//! dozen files once, so keep-alive would save nothing worth its code.
//! Only `GET` and `HEAD`.  The `Host` header must name the loopback address
//! the server is on, which stops DNS-rebinding pages from reading the site
//! through a name of their own.

use std::io::{self, BufRead, BufReader, Read, Write};
use std::net::TcpStream;
use std::time::Duration;

use crate::site::{self, Site};

/// The longest request head read; anything longer is refused.
const MAX_HEAD: usize = 16 << 10;
/// A client that sends nothing for this long is dropped.
const TIMEOUT: Duration = Duration::from_secs(10);

/// A parsed request line and the headers we use.
#[derive(Debug, PartialEq, Eq)]
pub struct Request {
    /// `GET` or `HEAD` (others are refused while parsing).
    pub method: String,
    /// The path, percent-decoded, without the query.
    pub path: String,
    /// The `Host` header, if any.
    pub host: Option<String>,
}

/// Why a request was not served from the site.
#[derive(Debug, PartialEq, Eq)]
pub enum Refusal {
    /// 400: not a request we understand.
    Bad,
    /// 405: a method other than GET or HEAD.
    Method,
    /// 421: a `Host` that is not this server's loopback address.
    Host,
}

/// Parse a request head (the request line and headers, CRLF or LF).
pub fn parse(head: &str) -> Result<Request, Refusal> {
    let mut lines = head.lines();
    let mut first = lines.next().ok_or(Refusal::Bad)?.split(' ');
    stream.flush()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_get_and_strips_the_query() {
        let r = parse("GET /a%20b.f?x=1 HTTP/1.1\r\nHost: 127.0.0.1:8421\r\n\r\n").unwrap();
        assert_eq!(r.method, "GET");
        assert_eq!(r.path, "/a b.f");
        assert_eq!(r.host.as_deref(), Some("127.0.0.1:8421"));
    }

    #[test]
    fn refuses_what_it_does_not_serve() {
        assert_eq!(parse("POST / HTTP/1.1\r\n\r\n"), Err(Refusal::Method));
        assert_eq!(parse("GET /\r\n\r\n"), Err(Refusal::Bad));
        assert_eq!(parse("GET x HTTP/1.1\r\n\r\n"), Err(Refusal::Bad));
        assert_eq!(parse("GET /%zz HTTP/1.1\r\n\r\n"), Err(Refusal::Bad));
        assert_eq!(parse(""), Err(Refusal::Bad));
    }

    #[test]
    fn only_loopback_hosts_on_our_port() {
        assert!(host_ok(Some("127.0.0.1:8421"), 8421));
        assert!(host_ok(Some("localhost:8421"), 8421));
        assert!(!host_ok(Some("localhost:8422"), 8421));
        assert!(!host_ok(Some("evil.example:8421"), 8421));
        assert!(!host_ok(Some("127.0.0.1"), 8421));
        assert!(!host_ok(None, 8421));
    }
}
//! The server end to end, on real loopback sockets.

use std::io::{Read, Write};
use std::net::{Ipv4Addr, TcpListener, TcpStream};

use reva_serve::site::SITE;
use reva_serve::{Bound, bind, probe, serve};

/// Serve the embedded site on a free port, in the background.
fn start() -> u16 {
    let Ok(Bound::Listening(l, port)) = bind(&SITE, 0) else {
        panic!("no port")
    };
    std::thread::spawn(move || serve(l, &SITE, port));
    port
}

fn get(port: u16, path: &str, host: &str) -> (String, Vec<u8>) {
