100	/// What run time cannot change, and needs a separate bundle or entry: the
101	/// macOS Finder and Launchpad icon (from the `.app` bundle's `.icns`), the
102	/// Windows Explorer and pinned-taskbar icon (from the `.exe` resource or a
103	/// shortcut's icon), and the Linux launcher entry (a `.desktop` file with
104	/// `StartupWMClass=<id>`).  See docs/desktop.md, "Branding".
105	#[derive(Default)]
106	struct Branding {
107	    title: String,
108	    /// RGBA pixels, width, height.
109	    icon: Option<(Vec<u8>, u32, u32)>,
110	    /// The icon file as read, for the macOS Dock (NSImage decodes it).
111	    icon_png: Option<Vec<u8>>,
