116	/// A Linux app id: what GTK accepts as a program name and a `.desktop`
117	/// file can match, kept to letters, digits, `.`, `-` and `_`.
118	fn valid_id(id: &str) -> bool {
119	    (1..=64).contains(&id.len())
120	        && id
121	            .chars()
122	            .all(|c| c.is_ascii_alphanumeric() || matches!(c, '.' | '-' | '_'))
