126	fn package_file(dir: &Path, rel: &str) -> Option<PathBuf> {
127	    let rel = Path::new(rel);
128	    let plain = rel.components().all(|c| matches!(c, Component::Normal(_)));
129	    (plain && !rel.as_os_str().is_empty()).then(|| dir.join(rel))
130	}
