132	/// Decode a PNG to RGBA, with the `png` crate Tauri already builds on
133	/// (its own `image-png` feature would add four more crates).
134	fn decode_png(bytes: &[u8]) -> Result<(Vec<u8>, u32, u32), String> {
135	    use png::{ColorType, Transformations};
136	    let mut d = png::Decoder::new(std::io::Cursor::new(bytes));
137	    d.set_transformations(Transformations::normalize_to_color8() | Transformations::ALPHA);
138	    let mut r = d.read_info().map_err(|e| e.to_string())?;
139	    let mut buf = vec![0; r.output_buffer_size().ok_or("image too large")?];
140	    let info = r.next_frame(&mut buf).map_err(|e| e.to_string())?;
141	    buf.truncate(info.buffer_size());
142	    let rgba = match info.color_type {
143	        ColorType::Rgba => buf,
144	        ColorType::GrayscaleAlpha => buf
145	            .chunks_exact(2)
146	            .flat_map(|ga| [ga[0], ga[0], ga[0], ga[1]])
147	            .collect(),
148	        c => return Err(format!("unexpected color type {c:?}")),
149	    };
150	    Ok((rgba, info.width, info.height))
151	}
