153	fn branding(dir: Option<&Path>, m: &Manifest, notes: &mut Vec<String>) -> Branding {
154	    let title = match (&m.title, &m.name) {
155	        (Some(t), _) => t.clone(),
156	        (None, Some(n)) => format!("{n} on Reva"),
157	        (None, None) => "Reva Forth".to_string(),
158	    };
159	    let mut icon_png = None;
160	    let icon = match (dir, &m.icon) {
161	        (Some(dir), Some(rel)) => match package_file(dir, rel).map(fs::read) {
162	            Some(Ok(b)) => match decode_png(&b) {
163	                Ok(img) => {
164	                    icon_png = Some(b);
165	                    Some(img)
166	                }
167	                Err(e) => {
168	                    notes.push(format!("icon {rel}: not a usable PNG ({e}); using Reva's"));
169	                    None
170	                }
171	            },
172	            Some(Err(e)) => {
173	                notes.push(format!("icon {rel}: {e}; using Reva's"));
174	                None
175	            }
176	            None => {
177	                notes.push(format!("icon {rel} is not a path inside the package"));
178	                None
179	            }
180	        },
181	        _ => None,
182	    };
183	    let id = match &m.id {
184	        Some(id) if valid_id(id) => Some(id.clone()),
185	        Some(id) => {
186	            notes.push(format!("id {id:?} ignored: use letters, digits, . - _"));
187	            None
188	        }
189	        None => None,
190	    };
191	    Branding {
192	        title,
193	        icon,
194	        icon_png,
195	        id,
196	    }
197	}
