199	/// Show `png` as the app's Dock and app-switcher icon.  macOS takes these
200	/// from the running bundle, not from windows, so `set_icon` alone leaves
201	/// Reva's; NSApplication's `applicationIconImage` replaces it until the app
202	/// quits.  Finder and Launchpad still show the bundle's own icon.
203	#[cfg(target_os = "macos")]
204	fn set_dock_icon(png: &[u8]) {
205	    use objc2::{AllocAnyThread, MainThreadMarker};
206	    use objc2_app_kit::{NSApplication, NSImage};
207	    use objc2_foundation::NSData;
208	    let Some(mtm) = MainThreadMarker::new() else {
209	        return;
210	    };
211	    let data = NSData::with_bytes(png);
212	    if let Some(img) = NSImage::initWithData(NSImage::alloc(), &data) {
213	        // SAFETY: on the main thread (mtm), with a non-nil image.
214	        unsafe { NSApplication::sharedApplication(mtm).setApplicationIconImage(Some(&img)) };
215	    }
216	}
