245	#[derive(Default)]
246	struct Options {
247	    package: Option<PathBuf>,
248	    root: Option<PathBuf>,
249	    evals: Vec<String>,
250	    print_output: bool,
251	    canvas: Option<String>,
252	}
253	
254	fn parse_args() -> Result<Options, String> {
255	    let mut o = Options::default();
256	    let mut args = std::env::args().skip(1);
257	    while let Some(a) = args.next() {
258	        let mut value = |name: &str| args.next().ok_or(format!("{name} needs a value"));
259	        match a.as_str() {
260	            "--package" => o.package = Some(value(&a)?.into()),
261	            "--root" => o.root = Some(value(&a)?.into()),
262	            "--canvas" => {
263	                let v = value(&a)?;
264	                if !CANVAS.contains(&v.as_str()) {
265	                    return Err(format!("--canvas {v}: use one of {}", CANVAS.join(", ")));
266	                }
267	                o.canvas = Some(v);
268	            }
269	            "-e" | "--eval" => o.evals.push(value(&a)?),
270	            "--print-output" => o.print_output = true,
271	            "-h" | "--help" => {
272	                print!("{USAGE}");
273	                std::process::exit(0);
274	            }
275	            "-V" | "--version" => {
276	                println!("reva-desktop {}", env!("CARGO_PKG_VERSION"));
277	                std::process::exit(0);
278	            }
279	            // macOS passes -psn_... when launched from Finder
280	            s if s.starts_with("-psn_") => {}
281	            s => return Err(format!("unknown option {s}")),
282	        }
283	    }
284	    Ok(o)
285	}
