287	fn home() -> PathBuf {
288	    std::env::var_os("HOME")
289	        .or_else(|| std::env::var_os("USERPROFILE"))
290	        .map(PathBuf::from)
291	        .unwrap_or_else(|| PathBuf::from("."))
