294	fn build_state(o: Options) -> Result<State, String> {
295	    let mut notes = Vec::new();
296	    let (root, manifest) = match &o.package {
297	        Some(dir) => {
298	            let dir = fs::canonicalize(dir).map_err(|e| format!("{}: {e}", dir.display()))?;
299	            let mpath = dir.join("reva-package.json");
300	            let manifest = match fs::read(&mpath) {
301	                Ok(b) => serde_json::from_slice::<Manifest>(&b)
302	                    .map_err(|e| format!("{}: {e}", mpath.display()))?,
303	                Err(_) => {
304	                    notes.push(format!(
305	                        "no reva-package.json in {}; opening it as a folder",
306	                        dir.display()
307	                    ));
308	                    Manifest::default()
309	                }
310	            };
311	            (dir, manifest)
312	        }
313	        None => {
314	            let root = o.root.clone().unwrap_or_else(|| home().join("Reva"));
315	            fs::create_dir_all(&root).map_err(|e| format!("{}: {e}", root.display()))?;
316	            let root = fs::canonicalize(&root).map_err(|e| format!("{}: {e}", root.display()))?;
317	            (root, Manifest::default())
318	        }
319	    };
320	    let start = manifest
321	        .start
322	        .iter()
323	        .map(|f| format!("include {f}"))
324	        .collect();
325	    let package = o.package.is_some().then_some(root.as_path());
326	    let brand = branding(package, &manifest, &mut notes);
327	    let canvas = match (o.canvas, manifest.canvas) {
328	        (Some(c), _) => Some(c),
329	        (None, Some(c)) if CANVAS.contains(&c.as_str()) => Some(c),
330	        (None, Some(c)) => {
331	            notes.push(format!(
332	                "canvas {c:?} ignored: use one of {}",
333	                CANVAS.join(", ")
334	            ));
335	            None
336	        }
337	        (None, None) => None,
338	    };
339	    Ok(State {
340	        session: Session {
341	            title: brand.title.clone(),
342	            root: root.display().to_string(),
343	            start,
344	            input: o.evals,
345	            print_output: o.print_output,
346	            canvas,
347	            package: package.map(|_| {
348	                serde_json::json!({
349	                    "name": manifest.name,
350	                    "id": manifest.id,
351	                    "title": manifest.title,
352	                    "about": manifest.about,
353	                    "hint": manifest.hint,
354	                })
355	            }),
356	            notes,
357	        },
358	        sql: sql::new(root.clone()),
359	        root,
360	        brand,
361	    })
362	}
