364	/// The real file for VM path `vm`, if it is a plain path under the root
365	/// (no `..`, not the built-in library).
366	fn real_path(root: &Path, vm: &str) -> Option<PathBuf> {
367	    if vm.starts_with(BUILTIN) || !vm.starts_with('/') {
368	        return None;
369	    }
370	    let rel = Path::new(&vm[1..]);
371	    if rel.components().any(|c| !matches!(c, Component::Normal(_))) {
372	        return None;
373	    }
374	    Some(root.join(rel))
375	}
