377	/// Bytes as a string of chars U+0000..U+00FF, one per byte: what the page's
378	/// Web Storage format already uses, and cheap to carry in JSON.
379	fn to_latin1(b: &[u8]) -> String {
380	    b.iter().map(|&c| c as char).collect()
381	}
382	
383	fn from_latin1(s: &str) -> Option<Vec<u8>> {
384	    s.chars().map(|c| u8::try_from(c as u32).ok()).collect()
385	}
386	
387	/// Every file under `root`, as (VM path, bytes), within the size limits.
388	fn snapshot(root: &Path, notes: &mut Vec<String>) -> Vec<(String, String)> {
389	    let mut out = Vec::new();
390	    let mut total = 0u64;
391	    let mut stack = vec![root.to_path_buf()];
392	    while let Some(dir) = stack.pop() {
393	        let Ok(entries) = fs::read_dir(&dir) else {
394	            continue;
395	        };
396	        let mut entries: Vec<_> = entries.flatten().collect();
397	        entries.sort_by_key(|e| e.file_name());
398	        for e in entries {
399	            let p = e.path();
400	            let Ok(meta) = e.metadata() else { continue };
401	            let name = e.file_name();
402	            if name.to_string_lossy().starts_with('.') {
403	                continue; // .git and friends
404	            }
405	            if meta.is_dir() {
406	                stack.push(p);
407	                continue;
408	            }
409	            let Ok(rel) = p.strip_prefix(root) else {
410	                continue;
411	            };
412	            let vm = format!("/{}", rel.to_string_lossy().replace('\\', "/"));
413	            if meta.len() > MAX_FILE || total + meta.len() > MAX_TOTAL {
414	                notes.push(format!("not loaded (too large): {vm}"));
415	                continue;
416	            }
417	            if let Ok(bytes) = fs::read(&p) {
418	                total += bytes.len() as u64;
419	                out.push((vm, to_latin1(&bytes)));
420	            }
421	        }
422	    }
423	    out
424	}
