441	#[tauri::command]
442	fn write_file(
443	    state: tauri::State<'_, Mutex<State>>,
444	    path: String,
445	    data: String,
446	) -> Result<(), String> {
447	    let st = state.lock().unwrap();
448	    let Some(p) = real_path(&st.root, &path) else {
449	        return Ok(());
450	    };
451	    let bytes = from_latin1(&data).ok_or("file data is not bytes")?;
452	    if let Some(dir) = p.parent() {
453	        fs::create_dir_all(dir).map_err(|e| format!("{path}: {e}"))?;
454	    }
455	    fs::write(&p, bytes).map_err(|e| format!("{path}: {e}"))
456	}
