458	#[tauri::command]
459	fn remove_file(state: tauri::State<'_, Mutex<State>>, path: String) -> Result<(), String> {
460	    let st = state.lock().unwrap();
461	    let Some(p) = real_path(&st.root, &path) else {
462	        return Ok(());
463	    };
464	    match fs::remove_file(&p) {
465	        Err(e) if e.kind() != std::io::ErrorKind::NotFound => Err(format!("{path}: {e}")),
466	        _ => Ok(()),
467	    }
468	}
