478	/// Windows `open_window` may open: each is `<name>.html` from the page.
479	const WINDOWS: &[(&str, f64, f64)] = &[("canvas", 820.0, 880.0)];
480	
481	/// Open window `name` (or show it if it is open).
482	#[tauri::command]
483	fn open_window(app: tauri::AppHandle, name: String, title: String) -> Result<(), String> {
484	    use tauri::{Manager, WebviewUrl, WebviewWindowBuilder};
485	    let &(name, w, h) = WINDOWS
486	        .iter()
487	        .find(|(n, _, _)| *n == name)
488	        .ok_or(format!("no window named {name}"))?;
489	    if let Some(win) = app.get_webview_window(name) {
490	        let _ = win.show();
491	        let _ = win.set_focus();
492	        return Ok(());
493	    }
494	    // Placement is left to the window manager.
495	    WebviewWindowBuilder::new(&app, name, WebviewUrl::App(format!("{name}.html").into()))
496	        .title(title)
497	        .inner_size(w, h)
498	        .build()
499	        .map(drop)
500	        .map_err(|e| format!("{name}: {e}"))
501	}
