503	/// Open an http(s) link (the About dialog's) in the system browser.  Any
504	/// other scheme is refused, so the page cannot launch local programs.
505	#[tauri::command]
506	fn open_url(url: String) -> Result<(), String> {
507	    if !web_url(&url) {
508	        return Err(format!("not an http(s) link: {url}"));
509	    }
510	    let mut c = if cfg!(target_os = "macos") {
511	        std::process::Command::new("open")
512	    } else if cfg!(windows) {
513	        std::process::Command::new("explorer")
514	    } else {
515	        std::process::Command::new("xdg-open")
516	    };
517	    c.arg(&url)
518	        .spawn()
519	        .map(|mut child| drop(std::thread::spawn(move || child.wait())))
520	        .map_err(|e| format!("{url}: {e}"))
521	}
522	
523	/// An `http://` or `https://` URL with no whitespace or control characters.
524	fn web_url(url: &str) -> bool {
525	    let lower = url.to_ascii_lowercase();
526	    (lower.starts_with("https://") || lower.starts_with("http://"))
527	        && url.len() < 2048
528	        && !url.chars().any(|c| c.is_whitespace() || c.is_control())
529	}
