535	
536	fn main() -> ExitCode {
537	    let mut state = match parse_args().and_then(build_state) {
538	        Ok(s) => s,
539	        Err(e) => {
540	            eprintln!("reva-desktop: {e}\n{USAGE}");
541	            return ExitCode::from(2);
542	        }
543	    };
544	    // Before GTK starts (Builder::build), or it keeps "reva-desktop".
545	    #[cfg(target_os = "linux")]
546	    if let Some(id) = &state.brand.id {
547	        glib::set_prgname(Some(id.as_str()));
548	        glib::set_application_name(&state.brand.title);
549	    }
550	    let title = state.brand.title.clone();
551	    let icon = state.brand.icon.take();
552	    #[cfg_attr(not(target_os = "macos"), allow(unused_variables))]
553	    let dock_png = state.brand.icon_png.take();
554	    let app = tauri::Builder::default()
555	        .manage(Mutex::new(state))
556	        .invoke_handler(tauri::generate_handler![
557	            session,
558	            write_file,
559	            remove_file,
560	            print,
561	            open_window,
562	            open_url,
563	            halt,
564	            sql::host_call
565	        ])
566	        .on_window_event(|win, ev| {
567	            use tauri::{Emitter, Manager};
568	            if let tauri::WindowEvent::Destroyed = ev {
569	                let name = win.label().to_string();
570	                if name != "main" {
571	                    let msg = serde_json::json!({ "type": "closed", "window": name });
572	                    let _ = win.app_handle().emit_to("main", "reva-ui-up", msg);
573	                }
574	            }
575	        })
576	        // The window is made here, not in tauri.conf.json, so it opens with
577	        // the package's title and icon instead of showing Reva's first.
578	        .setup(move |app| {
579	            let mut w = tauri::WebviewWindowBuilder::new(app, "main", Default::default())
580	                .title(&title)
581	                .inner_size(960.0, 680.0);
582	            if let Some((rgba, width, height)) = icon {
583	                w = w.icon(tauri::image::Image::new_owned(rgba, width, height))?;
584	            }
585	            w.build()?;
586	            Ok(())
587	        })
588	        .build(tauri::generate_context!());
589	    match app {
590	        Ok(app) => {
591	            // On Ready, after macOS has finished launching and applied the
592	            // bundle's icon, which would otherwise replace ours.
593	            let code = app.run_return(move |_, ev| {
594	                #[cfg(target_os = "macos")]
595	                if let (tauri::RunEvent::Ready, Some(png)) = (&ev, &dock_png) {
596	                    set_dock_icon(png);
597	                }
598	                let _ = &ev;
599	            });
600	            ExitCode::from(code.clamp(0, 255) as u8)
601	        }
602	        Err(e) => {
603	            eprintln!("reva-desktop: {e}");
604	            ExitCode::FAILURE
605	        }
606	    }
607	}
