//! Host calls from the page (docs/design.md 3.11): SQLite through the
//! reva-sqlite crate, with every database inside the app's folder.  The
//! VM runs in the page's worker, so its `lib/db/sqlite` calls arrive here
//! as the `host_call` command and go back as `{ int }`, `{ bytes }` or
//! `{ error }` (see components/web/crates/reva-web/www/reva.js, `Reva.resume`).

use std::path::PathBuf;
use std::sync::Mutex;

use reva_sqlite::{Reply, Sqlite};
use serde::Deserialize;
use serde_json::{Value, json};

/// A host call as the page sends it (`Reva.hostCall`).
#[derive(Deserialize)]
pub struct Call {
    service: String,
    op: String,
    ints: Vec<i64>,
    bytes: Vec<Vec<u8>>,
}

/// SQLite for the folder `root`.  A database name is a VM path (a name
/// without a leading `/` is taken from `/`), mapped into the folder as the
/// file words map paths; one that would leave the folder does not open.
pub fn new(root: PathBuf) -> Sqlite {
    Sqlite::new(Box::new(move |name| {
        let vm = if name.starts_with('/') {
            name.to_string()
        } else {
            format!("/{name}")
        };
        crate::real_path(&root, &vm)
    }))
}

#[tauri::command]
pub fn host_call(state: tauri::State<'_, Mutex<crate::State>>, call: Call) -> Value {
    if call.service != "sqlite" {
        return json!({ "error": format!("{} is not available in the desktop app", call.service) });
    }
    let mut st = state.lock().unwrap();
    match st.sql.call(&call.op, &call.ints, &call.bytes) {
        Some(Reply::Int(v)) => json!({ "int": v }),
        Some(Reply::Bytes(b)) => json!({ "bytes": b }),
        None => json!({ "error": format!("reva-sqlite has no operation {}", call.op) }),
    }
}
# The desktop app is its own component (workspace) so the core components
# keep (nearly) zero dependencies: Tauri brings a few hundred crates, and
# building or testing the core should never need them.  See README.md.
[workspace]
resolver = "2"
members = ["crates/reva-desktop"]

[workspace.package]
version = "0.1.0"
edition = "2024"
rust-version = "1.85"
publish = false
[dependencies]
tauri = { version = "2", features = [] }
# Decodes a package's icon; already in the tree through Tauri.
png = "0.18"
serde = { version = "1", features = ["derive"] }
serde_json = "1"
# SQLite for lib/db/sqlite (host calls), through rusqlite's safe API.
reva-sqlite = { path = "../../../sqlite/crates/reva-sqlite" }

# Sets the program name before GTK starts, so a package's `id` becomes the
# Wayland app_id / X11 WM_CLASS (see Branding in main.rs).  Already in the
# tree through Tauri's GTK stack, so it adds no crate.
[target.'cfg(target_os = "linux")'.dependencies]
glib = "0.18"

# Sets the Dock icon from a package's icon (set_dock_icon in main.rs).  The
# same objc2 crates Tauri's macOS backend (tao, wry) already builds, with
# features it already enables, so it adds no crate.
[target.'cfg(target_os = "macos")'.dependencies]
objc2 = "0.6"
objc2-app-kit = { version = "0.3", default-features = false, features = ["std", "NSApplication", "NSImage", "NSResponder"] }
objc2-foundation = { version = "0.3", default-features = false, features = ["std", "NSData"] }

