use reva_vm::host::{Console, Platform, Resources};
use reva_vm::hostcall::{HostAnswer, HostCall, HostReply};
use reva_vm::prelude::*;
use reva_vm::{BufferHost, Machine, Status, embedded};

struct H { inner: BufferHost, calls: Vec<HostCall> }
impl Console for H { fn write(&mut self, b: &[u8]) { self.inner.write(b) } }
impl Platform for H {}
impl Resources for H { fn host_call(&mut self, c: &HostCall) -> HostAnswer { self.calls.push(c.clone()); HostAnswer::Later } }

fn drive(vm: &mut Machine, h: &mut H, sql: &mut reva_sqlite::Sqlite) {
    loop {
        match vm.run_until_blocked(h) {
            Status::HostCall => {
                let c = vm.pending_host_call().unwrap().clone();
                let r = sql.call(c.op, &c.ints, &c.bytes);
                eprintln!("call {} {:?} -> {:?}", c.op, c.ints, r.as_ref().map(|r| match r { reva_sqlite::Reply::Int(v) => format!("int {v}"), reva_sqlite::Reply::Bytes(b) => format!("bytes {}", String::from_utf8_lossy(b)) }));
                match r { Some(reva_sqlite::Reply::Int(v)) => vm.resume(HostReply::Int(v)), Some(reva_sqlite::Reply::Bytes(b)) => vm.resume(HostReply::Bytes(b)), None => vm.refuse("no".into()) }
            }
            _ => return,
        }
    }
}

#[test]
fn sql_through_later() {
    let dir = std::env::temp_dir().join(format!("tmpsql{}", std::process::id()));
    let _ = std::fs::create_dir_all(&dir);
    let d2 = dir.clone();
    let mut sql = reva_sqlite::Sqlite::new(Box::new(move |n| Some(d2.join(n.trim_start_matches('/')))));
    let mut vm = Machine::new(&["reva", embedded::BOOT_PATH]);
    let mut h = H { inner: BufferHost::new(), calls: vec![] };
    vm.run_until_blocked(&mut h);
    vm.quiet_prompt();
    h.inner.take_output();
    vm.feed(b"needs db/sqlite with~ ~db \" pets.db\" sql_open value db\ndb \" create table p(n text); insert into p values('cat');\" sql_exec db \" select n from p\" sql_fetch$ type cr\n");
    drive(&mut vm, &mut h, &mut sql);
    eprintln!("OUT: {:?}", h.inner.take_output());
}
EOF
