reva_macros::machine_trait! {
    /// The virtual library `reva-sqlite`.
    pub trait SqliteLib {
        /// `(call)` of a reva-sqlite function with `n` cells: ask the host and,
        /// once the reply is in, consume the call's cells and push the result.
        /// `None` if `g` is not one of them.
        fn sqlite_call(&mut self, host: &mut dyn Host, g: Gate, n: u32) -> Option<Result<Next, Fault>> {
            if g == Gate::SqPtr {
                let p = self.sql_ptr;
                return Some(self.ffi_finish(n, p).map(|()| Next::Ret));
            }
            let (op, shape) = spec(g)?;
            Some(self.sqlite_answer(host, op, shape, n))
    }

    fn sqlite_answer(
        &mut self,
        host: &mut dyn Host,
        op: &'static str,
        shape: &[Arg],
        n: u32,
    ) -> Result<Next, Fault> {
        let call = self.sqlite_args(op, shape, n)?;
        let answer = match self.host_reply.take() {
            Some(answer) => answer,
            None => host.host_call(&call),
        };
        match answer {
            HostAnswer::Reply(HostReply::Int(v)) => self.ffi_finish(n, v as u32)?,
            HostAnswer::Reply(HostReply::Bytes(b)) => {
                let p = self.sqlite_buffer(&call, b.len() as u32)?;
                self.mem.write_bytes(p, &b)?;
                self.sql_ptr = p;
                self.ffi_finish(n, b.len() as u32)?;
            }
            HostAnswer::Later => {
                self.pending_call = Some(call);
                return Ok(Next::HostCall);
            }
            HostAnswer::Unavailable(why) => return Err(Fault::Unavailable(why)),
        }
        Ok(Next::Ret)
    }

    /// The call's arguments, read without popping (`n` cells under the
    /// function address and the count, the first argument deepest).
    fn sqlite_args(&self, op: &'static str, shape: &[Arg], n: u32) -> Result<HostCall, Fault> {
        let width: u32 = shape.iter().map(|a| matches!(a, Str) as u32 + 1).sum();
        if width != n {
            return Err(Fault::NotImplemented(
                "reva-sqlite: wrong number of arguments",
            ));
        }
        let esi = self.cpu.r[ESI as usize];
        let cell = |i: u32| self.mem.read_u32(esi + 4 * (n - i));
        let (mut ints, mut bytes, mut i) = (Vec::new(), Vec::new(), 0);
        for a in shape {
            match a {
                Int => ints.push(i64::from(cell(i)? as i32)),
                Str => {
                    let (a, len) = (cell(i)?, cell(i + 1)?);
                    bytes.push(self.mem.slice(a, len)?.to_vec());
                    i += 1;
                }
            }
            i += 1;
        }
        Ok(HostCall {
            service: "sqlite",
            op,
            ints,
            bytes,
        })
    }

    /// A heap buffer for a bytes reply of `len` bytes.  Column replies get
    /// one per (statement, column), so the texts of a row's columns stay
    /// valid together until the next step, as SQLite's own pointers do;
    /// other replies share one.  Host state: not part of an image.
    fn sqlite_buffer(&mut self, call: &HostCall, len: u32) -> Result<u32, Fault> {
        let key = match call.op {
            "column_text" | "column_blob" | "getcol" => (call.ints[0], call.ints[1]),
            _ => (0, -1),
        };
        if let Some(&(p, cap)) = self.sql_bufs.get(&key) {
            if cap >= len {
                return Ok(p);
            }
            self.heap.free(p);
        }
        let cap = len.max(64);
        let p = self.heap.alloc(cap).ok_or(Fault::OutOfSpace("heap"))?;
        self.sql_bufs.insert(key, (p, cap));
        Ok(p)
    }
    }
}

//! `reva` — command-line host for the portable Reva core.
//!
//! ```text
//! reva [options] [file ...]
//! ```
//!
//! Boots `reva.f` (embedded), includes each file, evaluates each `-e` text,
//! then reads standard input: line by line with a prompt on a terminal, or
//! to end of input otherwise (so `reva x.f < /dev/null` is a batch run).
//! The exit status is the `bye` code (0 at end of input).
//!
//! `restart` starts over the way this run started (boot or `--image`),
//! includes the files and evaluates the `-e` texts again, then goes on
//! reading the input that is left.
//!
//! At a terminal, the line is edited before Forth sees it: history
//! (`~/.reva_history`, or `$REVA_HISTORY`), Up/Down, Ctrl-R search and
//! Emacs keys (see reva-lineedit, reva-term and docs/repl.md).
//!
//! The parts: [`options`] (the command line), [`run`] (booting and
//! `restart`), [`session`] (what follows: an image to save, piped input, or
//! the interactive loop); the host is reva-stdhost's `StdHost`.

mod options;
mod run;
mod session;

use std::io::{self, IsTerminal};
use std::process::ExitCode;

use options::{Options, USAGE, color_auto, parse_args};
use reva_stdhost::host::StdHost;
use reva_term::reader::LineReader;
use reva_vm::{Machine, Start, embedded};
use run::Run;

fn main() -> ExitCode {
    let opts = match parse_args() {
        Ok(o) => o,
        Err(e) => {
            eprintln!("reva: {e}\n{USAGE}");
            return ExitCode::from(2);
        }
    };
    let (start, mut vm) = match start_machine(&opts) {
        Ok(sm) => sm,
        Err(code) => return code,
    };
    let interactive = io::stdin().is_terminal() && opts.save_image.is_none();
    let run = Run {
        opts: &opts,
        start,
        interactive,
    };
    let reader = interactive.then(|| LineReader::new(!opts.no_edit));
    let color = opts.color.unwrap_or_else(color_auto);
    let mut host = StdHost::new(opts.allow_shell, color, reader);
    session::session(&run, &mut vm, &mut host)
}

/// The machine to start with: from `--image`, or booted (`reva.f`, the
/// `--boot` file, or nothing with `--no-boot`); and how it was started,
/// for `restart`.
fn start_machine(opts: &Options) -> Result<(Start, Machine), ExitCode> {
    let boot_path = opts
        .boot
        .clone()
        .unwrap_or_else(|| embedded::BOOT_PATH.to_string());
    match &opts.image {
        Some(path) => {
            let loaded = std::fs::read(path)
                .map_err(|e| e.to_string())
                .and_then(|b| Start::image(b).map_err(|e| e.to_string()));
            match loaded {
                Ok(sm) => Ok(sm),
                Err(e) => {
                    eprintln!("reva: {path}: {e}");
                    Err(ExitCode::from(2))
                }
            }
        }
        None => {
            let mut args = vec!["reva".to_string()];
            if !opts.no_boot {
                args.push(boot_path);
            }
            let start = Start::Boot(args);
            let vm = start
                .machine()
                .expect("a boot start always makes a machine");
            Ok((start, vm))
        }
    }
}

//! WebAssembly host for the portable Reva core.
//!
//! Deliberately free of `wasm-bindgen`: the interface is a few C-ABI
//! functions over one VM instance, so the module has **no imports** and any
//! JavaScript (browser or Node) can drive it with plain `WebAssembly`
//! calls.  See `www/reva.js` for the JavaScript side.
//!
//! Protocol (mirrors [`reva_vm::Machine`]):
//!
//! 1. `reva_boot()` — create the VM and run `reva.f`; returns a status.
//!    Or start from a saved image: copy its bytes to
//!    `reva_fs_buffer(n)` and call `reva_boot_image(n)`; it returns -2 if
//!    the bytes are not an image this core loads (the reason is the
//!    `reva_fs_len()` bytes at `reva_fs_data()`).
//! 2. To send input: `p = reva_input_buffer(n)`, copy `n` bytes to `p`,
//!    then `reva_feed(n)`.  `reva_feed_start(n)` instead marks the bytes as
//!    *start input* (a page's start files): fed now, and again after every
//!    `restart`, as the CLI re-runs its file arguments.
//! 3. `reva_run(budget)` → 0 yielded (call again soon), 1 needs input,
//!    2 halted (`reva_exit_code()`).  Keep budgets small enough that the
//!    page stays responsive; JavaScript yields to the event loop between
//!    calls.  `restart` is handled inside `reva_run`: the VM is made again
//!    the way it was first made (reva.f or the image), keeps its files,
//!    reads the start input again, then the input not yet read, and prints
//!    its banner again.
//! 4. Output accumulates; read `reva_output_len()` bytes at
//!    `reva_output_ptr()` and then `reva_output_clear()`.
//!
//! Files (an in-memory [`MemFs`] over the embedded `lib/`; see
//! `reva_vm::vfs`):
//!
//! * `p = reva_fs_buffer(n)`, copy a path and then the file's bytes to
//!   `p`, and `reva_fs_put(path_len)` adds the file.  This works before
//!   `reva_boot` too, so a page can restore saved files and bundle its
//!   own before `reva.f` runs.
//! * `n = reva_fs_changes()` collects every file written or removed since
//!   the last call into the buffer at `reva_fs_data()`: records of
//!   `kind:u8` (1 written, 0 removed), `path_len:u32le`, path,
//!   `data_len:u32le`, data.  `www/reva.js` keeps them in `localStorage`.
//!
//! Build information (the page's footer): `reva_build_info_len()` bytes
//! at `reva_build_info_ptr()`, `key\tvalue` lines from
//! `reva_vm::version::fields()`: name, version, copyright, license,
//! repository, build_host, build_commit and build_time.  Works before boot.
//!
//! The canvas (turtle graphics; see `reva_vm::canvas` for the op format):
//!
//! * `n = reva_canvas_take()` moves the drawing ops not yet taken (at most
//!   `reva_vm::canvas::MAX_OPS_PER_TAKE` records) into a buffer of `n`
//!   `f32`s at `reva_canvas_ptr()`; call it after each [`reva_run`] slice
//!   until it returns 0.
//! * `reva_canvas_resend()`: the next takes start over with the whole
//!   drawing (a window opened).
//! * `reva_canvas_reset()` returns 1 once after `restart` made a new
//!   machine (its drawing is empty: windows should clear), else 0.
//!
//! The exports live in reva-web-run and reva-web-io (over reva-web-state's
//! one VM); this crate is the module that re-exports them, so they are
//! linked in and exported.

