64	fn start_machine(opts: &Options) -> Result<(Start, Machine), ExitCode> {
65	    let boot_path = opts
66	        .boot
67	        .clone()
68	        .unwrap_or_else(|| embedded::BOOT_PATH.to_string());
69	    match &opts.image {
70	        Some(path) => {
71	            let loaded = std::fs::read(path)
72	                .map_err(|e| e.to_string())
73	                .and_then(|b| Start::image(b).map_err(|e| e.to_string()));
74	            match loaded {
75	                Ok(sm) => Ok(sm),
76	                Err(e) => {
77	                    eprintln!("reva: {path}: {e}");
78	                    Err(ExitCode::from(2))
79	                }
80	            }
81	        }
82	        None => {
83	            let mut args = vec!["reva".to_string()];
84	            if !opts.no_boot {
85	                args.push(boot_path);
86	            }
87	            let start = Start::Boot(args);
88	            let vm = start
89	                .machine()
90	                .expect("a boot start always makes a machine");
