use reva_ui_base::change::Change;
use reva_ui_base::codec::{decode, encode, escape, unescape};
use reva_ui_base::keys::{CTRL, SHIFT, code, from_name, name, printable};
use reva_ui_base::kind::{Kind, Role, from_name as kind_named, name as kind_name, role};

#[test]
fn kinds_by_iup_class_name() {
    assert_eq!(kind_name(Kind::MultiLine), "multiline");
    assert_eq!(kind_named("vbox"), Some(Kind::Vbox));
    assert_eq!(kind_named("window"), None);
    assert_eq!(role(Kind::Dialog), Role::Container);
    assert_eq!(role(Kind::Item), Role::MenuEntry);
    assert_eq!(role(Kind::Timer), Role::Other);
}

#[test]
fn key_names_as_tui_uses_them() {
    for n in ["K_F1", "K_F6", "K_F12", "K_sF6", "K_sF11", "K_cS", "K_cF6", "K_cF9", "K_a", "K_Z", "K_0", "K_SP", "K_CR"] {
        let c = from_name(n).unwrap_or_else(|| panic!("{n}"));
        assert_eq!(name(c).as_deref(), Some(n), "{n} -> {c:#x}");
    }
    assert_eq!(from_name("K_F6"), Some(0xFFC3));
    assert_eq!(from_name("K_sF6"), Some(0xFFC3 | SHIFT));
    assert_eq!(from_name("K_cS"), Some('S' as u32 | CTRL));
    assert_eq!(from_name("K_xF6"), None);
    assert_eq!(from_name("F6"), None);
}

#[test]
fn key_codes_from_a_renderer() {
    assert_eq!(name(code(0xFFC3, true, false, false)).as_deref(), Some("K_sF6"));
    assert_eq!(name(code('s' as u32, false, true, false)).as_deref(), Some("K_cS"));
    // Shift is part of a character, not a modifier.
    assert_eq!(code('A' as u32, true, false, false), 'A' as u32);
    assert_eq!(printable('A' as u32), Some('A'));
    assert_eq!(printable('é' as u32), Some('é'));
    assert_eq!(printable('a' as u32 | CTRL), None);
    assert_eq!(printable(0xFFC3), None);
    assert_eq!(printable(13), None);
}

#[test]
fn changes_survive_their_text_form() {
    let all = [
        Change::Created { handle: 1, kind: Kind::Dialog },
        Change::Appended { parent: 1, child: 2 },
        Change::Detached { child: 2 },
        Change::Destroyed { handle: 2 },
        Change::Attr { handle: 3, name: "VALUE".into(), value: Some("a b\\c\nd\te\r".into()) },
        Change::Attr { handle: 3, name: "TITLE".into(), value: Some(String::new()) },
        Change::Attr { handle: 3, name: "TIP".into(), value: None },
        Change::Shown { handle: 1, x: -1, y: 20, modal: true },
        Change::Hidden { handle: 1 },
        Change::Focus { handle: 3 },
    ];
    for c in all {
        let line = encode(&c);
        assert!(!line.contains('\n'), "{line}");
        assert_eq!(decode(&line), Some(c), "{line}");
    }
    assert_eq!(encode(&Change::Attr { handle: 3, name: "VALUE".into(), value: Some("a b".into()) }), "attr 3 VALUE =a\\sb");
    assert_eq!(decode("created 1 window"), None);
    assert_eq!(decode("shown 1 2"), None);
    assert_eq!(decode("attr 1 X =bad\\q"), None);
}

#[test]
fn escaping() {
    assert_eq!(escape("a b\n"), "a\\sb\\n");
    assert_eq!(unescape("a\\sb\\n").as_deref(), Some("a b\n"));
    assert_eq!(unescape("trailing\\"), None);
}

use reva_ui_base::keys::{BS, CR, CTRL, DEL, DOWN, END, HOME, LEFT, SHIFT, UP};
use reva_ui_text::attr::{format_pos, format_range, parse_pos, parse_range};
use reva_ui_text::pos::{index, line_bounds, line_col, line_count, moved};
use reva_ui_text::text::{Motion, Text};

fn chars(s: &str) -> Vec<char> {
    s.chars().collect()
}

fn value(t: &Text) -> String {
    t.chars.iter().collect()
}

#[test]
fn lines_and_columns() {
    let c = chars("ab\ncde\n\nf");
    assert_eq!(line_count(&c), 4);
    assert_eq!(line_count(&[]), 1);
    assert_eq!(line_col(&c, 0), (0, 0));
    assert_eq!(line_col(&c, 4), (1, 1));
    assert_eq!(line_col(&c, 7), (2, 0));
    assert_eq!(line_col(&c, 99), (3, 1));
    assert_eq!(line_bounds(&c, 1), (3, 6));
    assert_eq!(line_bounds(&c, 2), (7, 7));
    assert_eq!(line_bounds(&c, 9), (9, 9));
    assert_eq!(index(&c, 1, 1000), 6);
    assert_eq!(moved(&c, 5, Motion::Up), 2);
    assert_eq!(moved(&c, 1, Motion::Down), 4);
    assert_eq!(moved(&c, 8, Motion::Down), 9);
    assert_eq!(moved(&c, 4, Motion::LineEnd), 6);
}

#[test]
fn iup_positions() {
    let m = Text::new("ab\ncde", true);
    assert_eq!(format_pos(&m, 4), "2,2");
    assert_eq!(parse_pos(&m, "2,2"), Some(4));
    assert_eq!(parse_pos(&m, "1,1000"), Some(2));
    // gui's line-text?: SELECTION "n,1:n,1000", then SELECTEDTEXT.
    assert_eq!(parse_range(&m, "2,1:2,1000"), Some((3, 6)));
    assert_eq!(format_range(&m, (3, 6)), "2,1:2,4");
    assert_eq!(parse_range(&m, "ALL"), Some((0, 6)));
    assert_eq!(parse_range(&m, "NONE"), Some((6, 6)));
    assert_eq!(parse_range(&m, "2,1"), None);
    let s = Text::new("hello", false);
    assert_eq!(format_pos(&s, 2), "3");
    assert_eq!(parse_pos(&s, "3"), Some(2));
    assert_eq!(parse_pos(&s, "x"), None);
}

#[test]
fn editing() {
    let mut t = Text::new("hello world", false);
    t.select(0, 5);
    assert_eq!(t.selection(), Some((0, 5)));
    t.insert("bye");
    assert_eq!((value(&t), t.caret, t.selection()), ("bye world".into(), 3, None));
    t.delete(false);
    t.delete(true);
    assert_eq!(value(&t), "byworld");
    t.insert("two\nlines");
    assert_eq!(value(&t), "bytwolinesworld", "a single line drops newlines");
    t.select(2, 2);
    t.delete(false);
    t.select(0, 0);
    t.delete(false);
    assert_eq!(value(&t), "btwolinesworld");
}

#[test]
fn keys_edit() {
    let mut t = Text::new("ab\ncd", true);
    for k in [HOME | CTRL, 'x' as u32, DOWN, END, CR, 'y' as u32] {
        assert!(t.key(k), "{k:#x}");
    }
    assert_eq!(value(&t), "xab\ncd\ny");
    assert!(t.key(UP));
    assert!(t.key(HOME | SHIFT));
    assert!(t.key(LEFT | SHIFT));
    assert_eq!(t.selection(), Some((3, 4)), "the selection grows with Shift");
    assert!(t.key(BS));
    assert_eq!(value(&t), "xabcd\ny");
    assert!(t.key(END | CTRL) && t.key(DEL) && t.key(BS));
    assert_eq!(value(&t), "xabcd\n");
    assert!(!t.key(0xFFC3), "F6 does not edit");
    assert!(!t.key('s' as u32 | CTRL));
    let mut s = Text::new("", false);
    assert!(!s.key(CR), "Enter does not edit a single line");
}

