//! Placing a dialog's elements.
//!
//! A box lays its children out one after another (a vbox down, an hbox
//! across) at their natural sizes, then shares the space left equally
//! among the children that expand along it.  Across, a child that expands
//! takes the box's whole width (or height); the others go where the box's
//! ALIGNMENT puts them.  Other containers give each child their inside:
//! all of it where the child expands, its natural size elsewhere.

use reva_ui_base::change::Handle;
use reva_ui_base::kind::{Kind, Role, role};
use reva_ui_tree::tree::Tree;

use crate::geom::{Placed, Rect, Size};
use crate::natural::{expands, natural};
use crate::units::{spacing, user_size};

/// Where every element of `dialog` goes, the dialog first, in a window of
/// `avail` cells: the dialog at its SIZE, else its natural size, at most
/// `avail`.
pub fn layout(tree: &Tree, dialog: Handle, avail: Size) -> Vec<Placed> {
    let n = natural(tree, dialog);
    let (cols, rows) = user_size(tree, dialog);
    let cols = cols.unwrap_or(n.cols).min(avail.cols);
    let rows = rows.unwrap_or(n.rows).min(avail.rows);
    let mut out = Vec::new();
    place(tree, dialog, Rect { col: 0, row: 0, cols, rows }, &mut out);
    out
}

/// Place `h` at `rect`, and what is in it.
fn place(tree: &Tree, h: Handle, rect: Rect, out: &mut Vec<Placed>) {
    out.push(Placed { handle: h, rect });
    let Some(node) = tree.node(h) else {
        return;
    };
    let kids: Vec<Handle> = node.children.iter().copied().filter(|c| laid_out(tree, *c)).collect();
    match node.kind {
        Kind::Vbox | Kind::Hbox => boxed(tree, h, &kids, rect, node.kind == Kind::Vbox, out),
        kind if role(kind) == Role::Container => {
            let inside = inside(tree, h, kind, rect);
            for c in kids {
                let (n, e) = (natural(tree, c), expands(tree, c));
                let cols = if e.horizontal { inside.cols } else { n.cols.min(inside.cols) };
                let rows = if e.vertical { inside.rows } else { n.rows.min(inside.rows) };
                place(tree, c, Rect { cols, rows, ..inside }, out);
            }
        }
        _ => {}
    }
}

/// Whether `h` takes part in the layout (menus, timers and the like do not).
fn laid_out(tree: &Tree, h: Handle) -> bool {
    tree.node(h).is_some_and(|n| matches!(role(n.kind), Role::Container | Role::Control))
}

/// The inside of a container's border: a dialog's and a frame's one cell
/// (and a dialog's menu bar), tabs' border and tab row.
fn inside(tree: &Tree, h: Handle, kind: Kind, r: Rect) -> Rect {
    let menu = u16::from(tree.attr(h, "MENU").is_some());
    let (top, side, bottom) = match kind {
        Kind::Dialog => (1 + menu, 1, 1),
        Kind::Frame => (1, 1, 1),
        Kind::Tabs => (2, 1, 1),
        _ => (0, 0, 0),
    };
    Rect { col: r.col + side, row: r.row + top, cols: r.cols.saturating_sub(2 * side), rows: r.rows.saturating_sub(top + bottom) }
}

/// Lay out the children `kids` of box `h` in `rect`.
fn boxed(tree: &Tree, h: Handle, kids: &[Handle], rect: Rect, vertical: bool, out: &mut Vec<Placed>) {
    let (margin, gap) = spacing(tree, h, vertical);
    let area = Rect {
        col: rect.col + margin.cols,
        row: rect.row + margin.rows,
        cols: rect.cols.saturating_sub(2 * margin.cols),
        rows: rect.rows.saturating_sub(2 * margin.rows),
    };
    let flip = |r: Rect| if vertical { r } else { Rect { col: r.row, row: r.col, cols: r.rows, rows: r.cols } };
    let a = flip(area); // `row`/`rows` along the box, `col`/`cols` across
    let sizes: Vec<(Size, bool, bool)> = kids.iter().map(|c| {
        let (n, e) = (natural(tree, *c), expands(tree, *c));
        if vertical { (n, e.vertical, e.horizontal) } else { (Size { cols: n.rows, rows: n.cols }, e.horizontal, e.vertical) }
    }).collect();
    let used: u32 = sizes.iter().map(|s| u32::from(s.0.rows)).sum::<u32>() + u32::from(gap) * kids.len().saturating_sub(1) as u32;
    let extra = u32::from(a.rows).saturating_sub(used);
    let growers = sizes.iter().filter(|s| s.1).count() as u32;
    let how = tree.attr(h, "ALIGNMENT").unwrap_or_default();
    let (mut at, mut grown) = (a.row, 0);
    for (c, (n, along, across)) in kids.iter().zip(sizes) {
        let len = n.rows + if along { grown += 1; share(extra, growers, grown - 1) } else { 0 };
        let cols = if across { a.cols } else { n.cols.min(a.cols) };
        let col = a.col + align(&how, a.cols - cols);
        place(tree, *c, flip(Rect { col, row: at, cols, rows: len }), out);
        at = at.saturating_add(len).saturating_add(gap);
    }
}

/// The part of `extra` cells the `i`th of `n` growing children gets.
fn share(extra: u32, n: u32, i: u32) -> u16 {
    (extra / n + u32::from(i < extra % n)) as u16
}

/// Where a child `room` cells smaller than its box goes across it.
fn align(how: &str, room: u16) -> u16 {
    match how.split(':').next().unwrap_or("") {
        "ACENTER" => room / 2,
        "ARIGHT" | "ABOTTOM" => room,
        _ => 0,
    }
}

