/// A box: its children one after another along its direction, with the
/// gaps between them and the margins around.
fn box_size(tree: &Tree, h: Handle, kids: &[Size], vertical: bool) -> Size {
    let (margin, gap) = spacing(tree, h, vertical);
    let (along, across): (fn(&Size) -> u16, fn(&Size) -> u16) = if vertical {
        (|s| s.rows, |s| s.cols)
    } else {
        (|s| s.cols, |s| s.rows)
    };
    let gaps = u32::from(gap) * kids.len().saturating_sub(1) as u32;
    let length = kids.iter().map(|s| u32::from(along(s))).sum::<u32>() + gaps;
    let length = clamp(length + 2 * u32::from(if vertical { margin.rows } else { margin.cols }));
    let width = clamp(
        u32::from(kids.iter().map(across).max().unwrap_or(0))
            + 2 * u32::from(if vertical { margin.cols } else { margin.rows }),
    );
    if vertical {
        Size {
            cols: width,
            rows: length,
        }
    } else {
        Size {
            cols: length,
            rows: width,
        }
    }
}

/// A count of cells, at most what a [`Size`] holds.
pub fn clamp(n: u32) -> u16 {
    n.min(u32::from(u16::MAX)) as u16
}

