109	/// Lay out the children `kids` of box `h` in `rect`.
110	fn boxed(
111	    tree: &Tree,
112	    h: Handle,
113	    kids: &[Handle],
114	    rect: Rect,
115	    vertical: bool,
116	    out: &mut Vec<Placed>,
117	) {
118	    let (margin, gap) = spacing(tree, h, vertical);
119	    let area = Rect {
120	        col: rect.col.saturating_add(margin.cols),
121	        row: rect.row.saturating_add(margin.rows),
122	        cols: rect.cols.saturating_sub(2 * margin.cols),
123	        rows: rect.rows.saturating_sub(2 * margin.rows),
124	    };
125	    let flip = |r: Rect| {
126	        if vertical {
127	            r
128	        } else {
129	            Rect {
130	                col: r.row,
131	                row: r.col,
132	                cols: r.rows,
133	                rows: r.cols,
134	            }
135	        }
136	    };
137	    let a = flip(area); // `row`/`rows` along the box, `col`/`cols` across
138	    let sizes: Vec<(Size, bool, bool)> = kids
139	        .iter()
140	        .map(|c| {
141	            let (n, e) = (natural(tree, *c), expands(tree, *c));
142	            if vertical {
143	                (n, e.vertical, e.horizontal)
144	            } else {
145	                (
146	                    Size {
147	                        cols: n.rows,
148	                        rows: n.cols,
149	                    },
150	                    e.horizontal,
151	                    e.vertical,
152	                )
153	            }
154	        })
