/// Lay out the children `kids` of box `h` in `rect`.
fn boxed(
    tree: &Tree,
    h: Handle,
    kids: &[Handle],
    rect: Rect,
    vertical: bool,
    out: &mut Vec<Placed>,
) {
    let (margin, gap) = spacing(tree, h, vertical);
    let area = Rect {
        col: rect.col.saturating_add(margin.cols),
        row: rect.row.saturating_add(margin.rows),
        cols: rect.cols.saturating_sub(2 * margin.cols),
        rows: rect.rows.saturating_sub(2 * margin.rows),
    };
    let flip = |r: Rect| {
        if vertical {
            r
        } else {
            Rect {
                col: r.row,
                row: r.col,
                cols: r.rows,
                rows: r.cols,
            }
        }
    };
    let a = flip(area); // `row`/`rows` along the box, `col`/`cols` across
    let sizes: Vec<(Size, bool, bool)> = kids
        .iter()
        .map(|c| {
            let (n, e) = (natural(tree, *c), expands(tree, *c));
            if vertical {
                (n, e.vertical, e.horizontal)
            } else {
                (
                    Size {
                        cols: n.rows,
                        rows: n.cols,
                    },
                    e.horizontal,
                    e.vertical,
                )
            }
        })
        .collect();
    let used: u32 = sizes.iter().map(|s| u32::from(s.0.rows)).sum::<u32>()
        + u32::from(gap) * kids.len().saturating_sub(1) as u32;
    let extra = u32::from(a.rows).saturating_sub(used);
    let growers = sizes.iter().filter(|s| s.1).count() as u32;
    let how = tree.attr(h, "ALIGNMENT").unwrap_or_default();
    let (mut at, mut grown) = (a.row, 0);
    for (c, (n, along, across)) in kids.iter().zip(sizes) {
        let grow = if along {
            grown += 1;
            share(extra, growers, grown - 1)
        } else {
            0
        };
        let len = n.rows.saturating_add(grow);
        let cols = if across { a.cols } else { n.cols.min(a.cols) };
        let col = a.col.saturating_add(align(&how, a.cols - cols));
        place(
            tree,
            *c,
            flip(Rect {
                col,
                row: at,
                cols,
                rows: len,
            }),
            out,
        );
        at = at.saturating_add(len).saturating_add(gap);
    }
}

/// The part of `extra` cells the `i`th of `n` growing children gets.
fn share(extra: u32, n: u32, i: u32) -> u16 {
    (extra / n + u32::from(i < extra % n)) as u16
}

/// Where a child `room` cells smaller than its box goes across it.
fn align(how: &str, room: u16) -> u16 {
    match how.split(':').next().unwrap_or("") {
        "ACENTER" => room / 2,
        "ARIGHT" | "ABOTTOM" => room,
        _ => 0,
    }
}

