        /// and do what it does.
        fn iup_loop(&mut self, host: &mut dyn Host) -> R<Next> {
            if !self.ui.running() {
                self.ui.end_loop();
                self.ffi_push(0)?;
                return Ok(Next::Ret);
            }
            let Some(event) = self.iup_wait(host)? else {
                return Ok(Next::HostCall);
            };
            match self.ui.event(event) {
                Some(call) => self.iup_callback(call),
                None => Ok(Next::Jump(Gate::IupLoop.addr())),
            }
        }

