                HostAnswer::Reply(HostReply::Bytes(b)) => {
                    let line = String::from_utf8_lossy(&b).into_owned();
                    decode_event(&line).map(Some).ok_or_else(|| Fault::Unavailable(format!("ui: not an event: {line}")))
