        fn iup_callback(&mut self, call: Call) -> R<Next> {
            let saved = [self.cpu.r[ESI as usize], self.cpu.r[EAX as usize]];
            for v in call.args.iter().rev().map(|a| *a as u32).chain([call.handle, Gate::IupResume.addr()]) {
