cat > script.rs <<'EOF'
//! A script of events, one per line:
//!
//! ```text
//! # a comment
//! key K_F6          a key, by IUP's name or code
//! type 2 3 +        the characters, one key each
//! click 5           a button, toggle or menu item (by handle)
//! focus 3
//! close 1           a dialog's close box
//! file /tmp/a.txt   the answer to a file dialog
//! cancel            a file dialog cancelled
//! ```

use std::collections::VecDeque;

/// The events not yet given, and what the host showed so far.
#[derive(Clone, Debug, Default)]
pub struct UiScript {
    pub lines: VecDeque<String>,
}

/// The script `text` as lines of events: comments and blank lines left
/// out, `type` made one `key` per character.
pub fn lines(text: &str) -> VecDeque<String> {
    let mut out = VecDeque::new();
    for line in text.lines().map(str::trim_end).filter(|l| !l.trim().is_empty() && !l.starts_with('#')) {
        match line.strip_prefix("type ") {
            Some(chars) => out.extend(chars.chars().map(|c| format!("key {}", c as u32))),
            None => out.push_back(line.trim().to_string()),
        }
    }
    out
}
EOF
cat > answer.rs <<'EOF'
//! Answering the `ui` host calls.

use reva_hostcall::hostcall::{HostAnswer, HostCall, HostReply};

use crate::script::{UiScript, lines};

impl UiScript {
    /// A host that gives the events of script `text`.
    pub fn new(text: &str) -> UiScript {
        UiScript { lines: lines(text) }
    }

    /// The answer to `call`, and the transcript of it: the changes the
    /// library sent (`ui< `), the event given (`ui> `).
    pub fn answer(&mut self, call: &HostCall) -> (HostAnswer, String) {
        let mut log: String = call.bytes.first().map_or(String::new(), |b| {
            let sent = String::from_utf8_lossy(b);
            sent.lines().map(|l| format!("ui< {l}\n")).collect()
        });
        if call.op == "file" {
            log = format!("ui< file {}\n", call.bytes.iter().map(|b| String::from_utf8_lossy(b)).collect::<Vec<_>>().join(" | "));
        }
        let Some(line) = self.lines.pop_front() else {
            return (HostAnswer::Unavailable("the ui script has no more events".into()), log);
        };
        log.push_str(&format!("ui> {line}\n"));
        let answer = match (call.op, line.split_once(' ')) {
            ("file", Some(("file", path))) => HostAnswer::Reply(HostReply::Bytes(path.as_bytes().to_vec())),
            ("file", _) if line == "cancel" => HostAnswer::Reply(HostReply::Int(-1)),
            ("wait", _) => HostAnswer::Reply(HostReply::Bytes(line.into_bytes())),
            _ => HostAnswer::Unavailable(format!("the ui script has {line:?} where the program asks for {}", call.op)),
        };
        (answer, log)
    }
}
EOF
