/// The next word of the line, looked up through `find`'s vector.
pub fn interp_word(m: &mut Machine, _: Gate, host: &mut dyn Host) -> R<Next> {
    if m.cpu.r[ESI as usize] > S0 {
        return Err(Fault::StackUnderflow);
