    let (a, n) = m.parsews(host)?;
    if n == 0 {
        return Ok(Next::Jump(Gate::Interpret.addr()));
    }
    m.upsh(a)?;
    m.upsh(n)?;
    Ok(Next::Call(m.var(st::FINDINTERNAL), Gate::InterpFound))
