cat > draw.rs <<'EOF'
//! Each element as the TUI draws it, in the rectangle the layout gave it:
//! dialogs and frames as boxes titled in their top border, labels as
//! text, buttons `[ OK ]`, toggles `[x] Bold`, text fields between
//! brackets, multilines and lists in a box of their own, canvases blank.
//! The focused element's border or face takes the focus role, and a
//! focused text element shows the cursor at its caret, scrolled into view.

use reva_ui_base::change::Handle;
use reva_ui_base::kind::Kind;
use reva_ui_layout::geom::Rect;
use reva_ui_mirror::mirror::Mirror;

use crate::grid::{Grid, Role};

/// A position `"lin,col"` (or `"col"`) from 1, as (line, column) from 0.
fn parse_pos(s: &str) -> Option<(usize, usize)> {
    let n = |s: &str| s.trim().parse::<usize>().ok().map(|n| n.max(1) - 1);
    match s.split_once(',') {
        Some((l, c)) => Some((n(l)?, n(c)?)),
        None => Some((0, n(s)?)),
    }
}

/// Draw element `h` of `m` at `r`.
pub fn draw(g: &mut Grid, m: &Mirror, h: Handle, r: Rect) {
    let t = &m.tree;
    let Some(kind) = t.node(h).map(|n| n.kind) else {
        return;
    };
    let title = t.attr(h, "TITLE").unwrap_or_default().replace("&&", "\u{0}").replace('&', "").replace('\u{0}', "&");
    let active = t.attr(h, "ACTIVE").is_none_or(|v| v != "NO");
    let role = |normal| match (active, m.focus == Some(h)) {
        (false, _) => Role::Disabled,
        (true, true) => Role::Focus,
        _ => normal,
    };
    let face = |text: String| format!("{text:^w$}", w = r.cols as usize);
    match kind {
        Kind::Dialog | Kind::Frame | Kind::Tabs => g.frame(r, Role::Dialog, Some((Role::Border, &title, Role::Title))),
        Kind::Label => {
            for (i, line) in title.split('\n').enumerate().take(r.rows as usize) {
                g.text(r.col, r.row + i as u16, line, role(Role::Text), r.cols);
            }
        }
        Kind::Button => drop(g.text(r.col, r.row, &face(format!("[ {title} ]")), role(Role::Button), r.cols)),
        Kind::Toggle => {
            let on = t.attr(h, "VALUE").is_some_and(|v| v == "ON");
            g.text(r.col, r.row, &format!("[{}] {title}", if on { 'x' } else { ' ' }), role(Role::Button), r.cols);
        }
        Kind::Text => {
            g.text(r.col, r.row, "[", role(Role::Border), 1);
            g.text(r.col + r.cols.saturating_sub(1), r.row, "]", role(Role::Border), 1);
            field(g, m, h, Rect { col: r.col + 1, cols: r.cols.saturating_sub(2), rows: 1, ..r });
        }
        Kind::MultiLine | Kind::List => {
            g.frame(r, Role::Field, Some((role(Role::Border), "", Role::Title)));
            let inside = Rect { col: r.col + 1, row: r.row + 1, cols: r.cols.saturating_sub(2), rows: r.rows.saturating_sub(2) };
            if kind == Kind::List { list(g, m, h, inside) } else { field(g, m, h, inside) }
        }
        Kind::Canvas | Kind::Matrix => g.frame(r, Role::Field, None),
        _ => {}
    }
}

/// A text element's VALUE in `area`, scrolled to its caret, its selection
/// marked; the cursor there if it has the focus.
fn field(g: &mut Grid, m: &Mirror, h: Handle, area: Rect) {
    let t = &m.tree;
    let value = t.attr(h, "VALUE").unwrap_or_default();
    let caret = t.attr(h, "CARET").and_then(|c| parse_pos(&c)).unwrap_or((0, 0));
    let sel = t.attr(h, "SELECTION").and_then(|s| {
        let (a, b) = s.split_once(':')?;
        let (a, b) = (parse_pos(a)?, parse_pos(b)?);
        Some((a.min(b), a.max(b)))
    });
    let (rows, cols) = (area.rows.max(1) as usize, area.cols.max(1) as usize);
    let (top, left) = (caret.0.saturating_sub(rows - 1), caret.1.saturating_sub(cols - 1));
    for (i, line) in value.split('\n').enumerate().skip(top).take(area.rows as usize) {
        for (j, ch) in line.chars().enumerate().skip(left).take(area.cols as usize) {
            let selected = sel.is_some_and(|(a, b)| (i, j) >= a && (i, j) < b);
            let ch = if ch.is_control() { ' ' } else { ch };
            g.put(area.col + (j - left) as u16, area.row + (i - top) as u16, ch, if selected { Role::Selection } else { Role::Field });
        }
    }
    if m.focus == Some(h) && area.cols > 0 && area.rows > 0 {
        g.cursor = Some((area.col + (caret.1 - left) as u16, area.row + (caret.0 - top) as u16));
    }
}

/// A list's items (attributes `1`, `2`, ...) in `area`, the one VALUE
/// names selected.
fn list(g: &mut Grid, m: &Mirror, h: Handle, area: Rect) {
    let t = &m.tree;
    let selected = t.attr(h, "VALUE").and_then(|v| v.trim().parse::<usize>().ok());
    let items = (1..).map_while(|i| t.attr(h, &i.to_string()));
