cat > state.rs <<'EOF'
//! The renderer's state, shared by the element and the page's calls.

use std::cell::RefCell;
use std::rc::Rc;

use reva_ui_layout::geom::Size;
use reva_ui_mirror::mirror::Mirror;

/// The model as the VM's changes describe it, the screen size in cells,
/// where events go (the page's function), and how to draw again.
pub struct State {
    pub mirror: Mirror,
    pub size: Size,
    pub on_event: Option<js_sys::Function>,
    pub redraw: Option<Rc<dyn Fn()>>,
}

thread_local! {
    static STATE: RefCell<State> = RefCell::new(State {
        mirror: Mirror::default(),
        size: Size { cols: 80, rows: 24 },
        on_event: None,
        redraw: None,
    });
}

/// `f` of the state.
pub fn with<R>(f: impl FnOnce(&mut State) -> R) -> R {
    STATE.with(|s| f(&mut s.borrow_mut()))
}

/// Send event lines to the page, which answers the VM's wait with them.
pub fn send(lines: Vec<String>) {
    let Some(f) = with(|s| s.on_event.clone()) else {
        return;
    };
    for line in lines {
        let _ = f.call1(&wasm_bindgen::JsValue::NULL, &line.into());
    }
}

/// Draw the element again.
pub fn redraw() {
    if let Some(r) = with(|s| s.redraw.clone()) {
        r();
    }
}
EOF
cat > keys.rs <<'EOF'
//! Browser keys (`KeyboardEvent.key`) as IUP key codes.

use reva_ui_base::keys::{code, from_name};

/// The browser's names of keys IUP names otherwise.
const NAMES: &[(&str, &str)] = &[
    ("Enter", "CR"),
    ("Tab", "TAB"),
    ("Backspace", "BS"),
    ("Delete", "DEL"),
    ("Escape", "ESC"),
    ("Home", "HOME"),
    ("End", "END"),
    ("ArrowLeft", "LEFT"),
    ("ArrowRight", "RIGHT"),
    ("ArrowUp", "UP"),
    ("ArrowDown", "DOWN"),
    ("PageUp", "PGUP"),
    ("PageDown", "PGDN"),
    ("Insert", "INS"),
    ("Pause", "PAUSE"),
];

/// The IUP code of the key the browser calls `key` with these modifiers;
/// `None` for keys IUP has no code for (Shift alone, media keys, ...).
pub fn key_code(key: &str, shift: bool, ctrl: bool, alt: bool) -> Option<u32> {
    let iup = NAMES.iter().find(|n| n.0 == key).map_or(key, |n| n.1);
    let base = match from_name(&format!("K_{iup}")).filter(|_| iup.chars().count() > 1) {
        Some(b) => b,
        None => {
            let mut chars = key.chars();
            let c = chars.next().filter(|_| chars.next().is_none())?;
            c as u32
        }
    };
    Some(code(base, shift, ctrl, alt))
}
