93:<body>
94:<main>
95:  <header><button type="button" id="about-btn" title="About this program, its licenses and source">About</button>
96:    <button type="button" id="gfx" title="Show the turtle graphics window" hidden>Graphics</button>
97:    <b>Reva Forth</b> <span id="hint">— portable vx86 core in WebAssembly. Try <code>: sq dup * ; 7 sq .</code>
99:  <div id="out" aria-live="polite"></div>
100:  <form id="f"><span id="prompt">ok&gt;</span><input id="line" autocomplete="off" spellcheck="false" autofocus>
101:    <button type="button" id="stop" title="Stop the running word (Ctrl-C)" disabled>Stop</button></form>
102:  <div id="panes"></div>
103:  <footer id="footer"></footer>

  // The host (host.js) says where files are kept (the browser: in
  // localStorage; the desktop app: in a folder) and what to feed at start.
  // reva.status starts as RUNNING (booting); onStatus reports each change.
  // ?image=app.img starts from a saved image instead of booting reva.f.
  const host = await hostSetup();
  const query = new URLSearchParams(location.search);
  // ?package=DIR/ (or the reva-package meta) loads a package from a static
  // directory (package.js): its files, start files, title, icon, canvas.
  const pkgDir = query.get("package") ?? document.querySelector('meta[name="reva-package"]')?.content;
  const notes = [...(host.notes ?? [])];
  let pkg = null;
  if (pkgDir) {
    try {
      pkg = await loadPackage(pkgDir);
      notes.push(...pkg.notes);
    } catch (e) {
      notes.push(`package ${pkgDir} not loaded: ${e.message ?? e}`);
    }
  }
  // History: one list per package (browser: ?package=; desktop: --package).
  const historyKey = pkg?.historyKey
    ?? (host.package ? `reva:${packageId(host.package)}:history` : "reva:history");
  editor = lineEditor(line, { prompt: document.getElementById("prompt"), key: historyKey });
  const title = pkg?.title ?? host.title;
  if (title) {
    document.title = title;
    document.querySelector("header b").textContent = title;
  }
  if (pkg?.icon) document.querySelector('link[rel="icon"]').href = pkg.icon;
  // A package's "hint" replaces Reva's in the header (`code` in backticks).
  const hint = pkg?.hint ?? host.package?.hint;
  if (typeof hint === "string") showHint(document.getElementById("hint"), `— ${hint}`);
  // About: the package's entry (from the page's ?package= or the desktop
  // host), then reva-fork's.
  const about = aboutDialog({ pkg: pkg?.about ?? packageAbout(host.package), openUrl: host.openUrl });
  document.getElementById("about-btn").addEventListener("click", () => about.open());
  // Where graphics go: ?canvas=window|pane|split, else the package's or
  // the host's choice, else the page's default (the reva-canvas meta),
  // else a window.
  const meta = document.querySelector('meta[name="reva-canvas"]')?.content || undefined;
  const mode = query.get("canvas") ?? pkg?.canvas ?? host.canvas ?? meta ?? "window";
  const split = mode === "split" ? splitView(document.querySelector("main"), document.getElementById("panes")) : null;
  const image = query.get("image") ?? undefined;
  const gfx = document.getElementById("gfx");
  let canvas = null;
  const reva = start("reva.wasm", {
    image,
    files: pkg?.files,
    storage: host.storage,
    prefix: pkg && !host.keepsFiles ? pkg.prefix : undefined,
    onOutput: (s) => { write(s); host.output?.(s); },
    onUi: (m) => { if (m.channel === "canvas") canvas.handle(m); },
    // Host calls (SQLite, docs/design.md 3.11): a host that serves them
    // answers (the desktop app, natively); in a browser the VM's worker
    // answers SQLite itself with SQLite's wasm build (sqlite.js).
    localServices: host.hostCall ? [] : ["sqlite"],
    onHostCall: (call) => host.hostCall?.(call)
      ?? { error: `${call.service} is not available in the browser` },
    onStatus: (s) => {
      stop.disabled = s !== RUNNING;
      if (s === HALTED) {
        echo(`\n[exited with status ${reva.exitCode}]\n`);
        line.disabled = true;
        halted(reva.exitCode);
      }

