  // Where graphics go: ?canvas=window|pane|split, else the package's or
  // the host's choice, else the page's default (the reva-canvas meta),
  // else a window.
  const meta = document.querySelector('meta[name="reva-canvas"]')?.content || undefined;
  const mode = query.get("canvas") ?? pkg?.canvas ?? host.canvas ?? meta ?? "window";
  const split = mode === "split" ? splitView(document.querySelector("main"), document.getElementById("panes")) : null;
  const image = query.get("image") ?? undefined;
  const gfx = document.getElementById("gfx");
  let canvas = null;
  const reva = start("reva.wasm", {
    image,
    files: pkg?.files,
    storage: host.storage,
    prefix: pkg && !host.keepsFiles ? pkg.prefix : undefined,
    onOutput: (s) => { write(s); host.output?.(s); },
    onUi: (m) => { if (m.channel === "canvas") canvas.handle(m); },
    // Host calls (SQLite, docs/design.md 3.11): a host that serves them
    // answers (the desktop app, natively); in a browser the VM's worker
    // answers SQLite itself with SQLite's wasm build (sqlite.js).
    localServices: host.hostCall ? [] : ["sqlite"],
    onHostCall: (call) => host.hostCall?.(call)
      ?? { error: `${call.service} is not available in the browser` },
    onStatus: (s) => {
      stop.disabled = s !== RUNNING;
      if (s === HALTED) {
        echo(`\n[exited with status ${reva.exitCode}]\n`);
        line.disabled = true;
        halted(reva.exitCode);
      }

