                Event::Mouse(m) if m.kind == MouseEventKind::Down(MouseButton::Left) => {
                    self.pending.extend(click(&self.mirror, screen, m.column, m.row));
                }
                Event::Paste(text) => self.pending.extend(text.chars().filter(|c| !c.is_control() || *c == '\n').map(|c| format!("key {}", if c == '\n' { 13 } else { c as u32 }))),
                Event::Resize(..) => self.shown = None,
                _ => {}
            }
        }
    }

    /// Into TUI mode: raw input, the alternate screen, mouse reports; a
    /// panic puts the terminal back first (the release build aborts).
    fn enter(&mut self) -> std::io::Result<()> {
        if self.active {
            return Ok(());
        }
        let hook = std::panic::take_hook();
        std::panic::set_hook(Box::new(move |info| {
            restore();
            hook(info);
        }));
        terminal::enable_raw_mode()?;
        execute!(stdout(), EnterAlternateScreen, EnableMouseCapture, event::EnableBracketedPaste)?;
        self.active = true;
        self.shown = None;
        Ok(())
    }

    /// Back to the REPL's terminal (before it prompts, at exit, on errors).
    pub fn suspend(&mut self) {
        if std::mem::take(&mut self.active) {
            restore();
        }
    }
}

/// Leave TUI mode, whatever state the terminal is in.
fn restore() {
    let mut out = stdout();
    let _ = execute!(out, event::DisableBracketedPaste, DisableMouseCapture, LeaveAlternateScreen, crossterm::cursor::Show);
    let _ = terminal::disable_raw_mode();
    let _ = out.flush();
}

impl Drop for UiTerm {
    fn drop(&mut self) {
        self.suspend();
    }
}

