    assert_eq!(t.caret, 0, "the caret goes back to where it was");
    assert!(t.key(ctrl('K')));
    assert_eq!(value(&t), "\n", "Ctrl-K, a step of its own");
    assert!(t.key(ctrl('Z')));
    assert_eq!(value(&t), "hello world\n");
