    assert!(t.key(ctrl('A')) && t.caret == 0, "Ctrl-A: its start");
    assert!(t.key(ctrl('F')) && t.key(ctrl('F')) && t.key(ctrl('B')) && t.caret == 1);
    assert!(t.key(ctrl('N')) && t.caret == 9, "Ctrl-N: down");
