    assert_eq!(value(&t), "", "back to the start");
    assert!(t.key(ctrl('Z')), "nothing left to undo: still the undo key");
    t.key(LEFT);
    assert!(t.key('x' as u32) && t.key('y' as u32));
    t.key(LEFT);
    t.key('z' as u32);
    assert!(t.undo());
    assert_eq!(value(&t), "xy", "moving the caret ends a typing step");
