use crossterm::event::{
    self, DisableMouseCapture, EnableMouseCapture, Event, MouseButton, MouseEventKind,
};
use crossterm::execute;
use crossterm::terminal::{self, EnterAlternateScreen, LeaveAlternateScreen};
use reva_hostcall::hostcall::{HostAnswer, HostCall, HostReply};
use reva_ui_base::keys::pasted;
use reva_ui_layout::geom::Size;
use reva_ui_paint::paint::{click, paint};

use crate::keys::{is_quit, key_code};
use crate::screen::draw;
use crate::term::UiTerm;

/// The terminal's size in cells.
fn size() -> Size {
    let (cols, rows) = terminal::size().unwrap_or((80, 24));
    Size { cols, rows }
}

impl UiTerm {
    /// The answer to `call`: a `wait` applies the changes, draws, and
    /// returns the next event; a file dialog is cancelled for now.
    pub fn answer(&mut self, call: &HostCall) -> HostAnswer {
        match call.op {
            "wait" => {
                let text = call
                    .bytes
                    .first()
                    .map(|b| String::from_utf8_lossy(b).into_owned())
                    .unwrap_or_default();
                self.mirror.apply_lines(&text);
                match self.next_event() {
                    Ok(line) => HostAnswer::Reply(HostReply::Bytes(line.into_bytes())),
                    Err(e) => {
                        self.suspend();
                        HostAnswer::Unavailable(format!("the terminal UI failed: {e}"))
                    }
                }
            }
            "file" => HostAnswer::Reply(HostReply::Int(-1)),
            op => HostAnswer::Unavailable(format!("ui {op} is not available in the terminal")),
        }
    }

    /// Draw, then wait for a key or click that makes an event line.
    fn next_event(&mut self) -> std::io::Result<String> {
        self.enter()?;
        loop {
            if let Some(line) = self.pending.pop_front() {
                return Ok(line);
            }
            let screen = size();
            let grid = paint(&self.mirror, screen);
            draw(&mut stdout(), self.shown.as_ref(), &grid)?;
            self.shown = Some(grid);
            match event::read()? {
                Event::Key(k) if is_quit(&k) => {
                    let top = self.mirror.top().unwrap_or(0);
                    self.pending.push_back(format!("close {top}"));
                }
                Event::Key(k) => self
                    .pending
                    .extend(key_code(&k).map(|c| format!("key {c}"))),
                Event::Mouse(m) if m.kind == MouseEventKind::Down(MouseButton::Left) => {
                    self.pending
                        .extend(click(&self.mirror, screen, m.column, m.row));
                }
                // Terminals paste line breaks as \r; one Enter each.
                Event::Paste(text) => self.pending.extend(pasted(&text)),
                Event::Resize(..) => self.shown = None,
                _ => {}
            }
        }
    }

    /// Into TUI mode: raw input, the alternate screen, mouse reports; a
    /// panic puts the terminal back first (the release build aborts).
    fn enter(&mut self) -> std::io::Result<()> {
        if self.active {
            return Ok(());
        }
        static HOOK: std::sync::Once = std::sync::Once::new();
        HOOK.call_once(|| {
            let hook = std::panic::take_hook();
            std::panic::set_hook(Box::new(move |info| {
                restore();
                hook(info);
            }));
        });
        terminal::enable_raw_mode()?;
        execute!(
            stdout(),
            EnterAlternateScreen,
            EnableMouseCapture,
            event::EnableBracketedPaste
        )?;
        // Terminals that can (kitty, WezTerm, Ghostty, iTerm2 with CSI u)
        // tell Ctrl-Enter from Enter; elsewhere Ctrl-J or F6 evaluate.
        if terminal::supports_keyboard_enhancement().unwrap_or(false) {
            let flags = event::KeyboardEnhancementFlags::DISAMBIGUATE_ESCAPE_CODES;
            execute!(stdout(), event::PushKeyboardEnhancementFlags(flags))?;
            ENHANCED.store(true, std::sync::atomic::Ordering::Relaxed);
        }
        self.active = true;
        self.shown = None;
        Ok(())
    }

    /// Back to the REPL's terminal (before it prompts, at exit, on errors).
    pub fn suspend(&mut self) {
        if std::mem::take(&mut self.active) {
            restore();
        }
    }
}

/// Leave TUI mode, whatever state the terminal is in.
/// Whether the keyboard enhancement is on (to switch it off again).
static ENHANCED: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);

fn restore() {
    let mut out = stdout();
    if ENHANCED.swap(false, std::sync::atomic::Ordering::Relaxed) {
        let _ = execute!(out, event::PopKeyboardEnhancementFlags);
    }
    let _ = execute!(
        out,
        event::DisableBracketedPaste,
        DisableMouseCapture,
        LeaveAlternateScreen,
        crossterm::cursor::Show
    );
    let _ = terminal::disable_raw_mode();
    let _ = out.flush();
}

impl Drop for UiTerm {
    fn drop(&mut self) {
        self.suspend();
    }
}

//! Browser keys (`KeyboardEvent.key`) as IUP key codes.

use reva_ui_base::keys::{code, from_name};

/// The browser's names of keys IUP names otherwise.
const NAMES: &[(&str, &str)] = &[
    ("Enter", "CR"),
    ("Tab", "TAB"),
    ("Backspace", "BS"),
    ("Delete", "DEL"),
    ("Escape", "ESC"),
    ("Home", "HOME"),
    ("End", "END"),
    ("ArrowLeft", "LEFT"),
    ("ArrowRight", "RIGHT"),
    ("ArrowUp", "UP"),
    ("ArrowDown", "DOWN"),
    ("PageUp", "PGUP"),
    ("PageDown", "PGDN"),
    ("Insert", "INS"),
    ("Pause", "PAUSE"),
];

/// The IUP code of the key the browser calls `key` with these modifiers;
/// `None` for keys IUP has no code for (Shift alone, media keys, ...).
pub fn key_code(key: &str, shift: bool, ctrl: bool, alt: bool) -> Option<u32> {
    let iup = NAMES.iter().find(|n| n.0 == key).map_or(key, |n| n.1);
    let base = match from_name(&format!("K_{iup}")).filter(|_| iup.chars().count() > 1) {
        Some(b) => b,
        None => {
            let mut chars = key.chars();
            let c = chars.next().filter(|_| chars.next().is_none())?;
            c as u32
        }
    };
    Some(code(base, shift, ctrl, alt))
}

/// Whether the browser keeps `key` with Ctrl or Cmd (`ctrl`): copy, cut
/// and paste, so that a paste event follows.
pub fn clipboard_key(key: &str, ctrl: bool) -> bool {
    ctrl && matches!(key, "c" | "C" | "v" | "V" | "x" | "X")
}

/// Pasted text as event lines: reva-ui-base's, shared with the terminal.
pub use reva_ui_base::keys::pasted;

//! What keys do: the line's ends, edits, history and search.

use crate::editor::{Editor, Outcome, Search};
use reva_history::history::History;
use reva_keys::key::Key;

impl Editor {
    /// Apply `k`.
    pub fn key(&mut self, k: Key, h: &History) -> Outcome {
        if self.search.is_some()
            && let Some(o) = self.search_key(k, h)
        {
            return o;
        }
        // Ctrl-X Ctrl-E runs the line, as Enter does (and as it evaluates
        // a line in the notebook); any other key after Ctrl-X is itself.
        if std::mem::take(&mut self.prefix) && k == Key::Ctrl('e') {
            return Outcome::Line(self.text());
        }
        if k == Key::Ctrl('x') {
            self.prefix = true;
            return Outcome::Edit;
        }
        let n = self.buf.len();
        match k {
            Key::Enter => return Outcome::Line(self.text()),
            Key::Ctrl('c') => return Outcome::Cancel,
            Key::Ctrl('d') if n == 0 => return Outcome::Eof,
            Key::Ctrl('l') => return Outcome::Clear,
            _ => {}
        }
        if !self.move_key(k, n) && !self.edit_key(k, n) {
            self.history_key(k, h);
        }
        Outcome::Edit
    }

    /// An edit of the text; false if `k` is not one.
    pub fn edit_key(&mut self, k: Key, n: usize) -> bool {
        match k {
            Key::Char(c) => {
                self.buf.insert(self.pos, c);
                self.pos += 1;
            }
            Key::Ctrl('d') | Key::Delete if self.pos < n => {
                self.buf.remove(self.pos);
            }
            Key::Ctrl('h') | Key::Backspace if self.pos > 0 => {
                self.pos -= 1;
                self.buf.remove(self.pos);
            }
            Key::Ctrl('d') | Key::Delete | Key::Ctrl('h') | Key::Backspace => {}
            Key::Ctrl('k') => self.cut(self.pos, n),
            Key::Ctrl('u') => self.cut(0, self.pos),
            Key::Ctrl('w') | Key::AltBackspace => self.cut(self.word_left(), self.pos),
            Key::Alt('d') => self.cut(self.pos, self.word_right()),
            Key::Ctrl('y') => {
                let k = self.kill.clone();
                self.buf.splice(self.pos..self.pos, k.iter().copied());
                self.pos += k.len();
            }
            Key::Ctrl('t') if n >= 2 && self.pos > 0 => {
                let p = if self.pos == n { n - 1 } else { self.pos };
                self.buf.swap(p - 1, p);
                self.pos = p + 1;
            }
            _ => return false,
        }
        true
    }

    /// History recall (Up, Down) and the start of a search (Ctrl-R, Ctrl-S).
    pub fn history_key(&mut self, k: Key, h: &History) {
        match k {
            Key::Ctrl('p') | Key::Up => {
                let to = self.index.unwrap_or(h.len()).checked_sub(1);
                if let Some(i) = to {
                    self.recall(h, Some(i));
                }
            }
            Key::Ctrl('n') | Key::Down => {
                if let Some(i) = self.index {
                    self.recall(h, (i + 1 < h.len()).then_some(i + 1));
                }
            }
            Key::Ctrl('r') | Key::Ctrl('s') => {
                self.search = Some(Search {
                    back: k == Key::Ctrl('r'),
                    query: String::new(),
                    at: None,
                    failed: false,
                    original: (self.buf.clone(), self.pos),
                });
            }
            _ => {}
        }
    }

    /// A key while searching: `Some` if it was the search's, `None` if it
    /// ended the search and should now be applied to the line.
    pub fn search_key(&mut self, k: Key, h: &History) -> Option<Outcome> {
        let s = self.search.as_mut().unwrap();
        match k {
            Key::Ctrl('r') | Key::Ctrl('s') => {
                s.back = k == Key::Ctrl('r');
                if s.query.is_empty() {
                    s.query = self.last_query.clone();
                }
                let from = s.at;
                self.find(h, from, false);
            }
            Key::Char(c) => {
                s.query.push(c);
                let from = s.at;
                self.find(h, from, true);
            }
            Key::Backspace => {
                s.query.pop();
                s.at = None;
                self.find(h, None, true);
            }
            Key::Ctrl('g') | Key::Ctrl('c') | Key::Esc => {
                let s = self.search.take().unwrap();
                self.last_query = s.query;
                (self.buf, self.pos) = s.original;
            }
            _ => {
                let s = self.search.take().unwrap();
                if !s.query.is_empty() {
                    self.last_query = s.query;
                }
                self.index = s.at;
                return None;
            }
        }
        Some(Outcome::Edit)
    }

    /// Look for the query from history entry `from`; `stay`: the entry at
    /// `from` itself may match (the query grew).
    pub fn find(&mut self, h: &History, from: Option<usize>, stay: bool) {
        let s = self.search.as_mut().unwrap();
        let found = if s.query.is_empty() {
            None
        } else if s.back {
            let start = from.map_or(h.len(), |i| if stay { i + 1 } else { i });
            h.search_back(&s.query, start)
        } else {
            match from {
                Some(i) if stay && h.get(i).is_some_and(|t| t.contains(&s.query)) => Some(i),
                Some(i) => h.search_forward(&s.query, i),
                None => (0..h.len()).find(|&i| h.get(i).is_some_and(|t| t.contains(&s.query))),
            }
        };
        s.failed = found.is_none() && !s.query.is_empty();
        if let Some(i) = found {
            s.at = Some(i);
            let text = h.get(i).unwrap_or("");
            let q = s.query.clone();
            self.set(text);
            if let Some(b) = text.find(&q) {
                self.pos = text[..b].chars().count();
            }
        }
    }
}

//! The line being edited and what keys do to it.

/// What a key did to the line.
#[derive(Debug, PartialEq, Eq)]
pub enum Outcome {
    /// Still editing: redraw.
    Edit,
    /// Enter: the finished line (without newline).
    Line(String),
    /// Ctrl-C: drop the line, start a new one.
    Cancel,
    /// Ctrl-D on an empty line: end of input.
    Eof,
    /// Ctrl-L: clear the screen, then redraw.
    Clear,
}

#[derive(Debug)]
pub struct Search {
    pub back: bool,
    pub query: String,
    /// The history entry shown, if any matched.
    pub at: Option<usize>,
    pub failed: bool,
    pub original: (Vec<char>, usize),
}

/// One line being edited, with history recall and search.
#[derive(Debug, Default)]
pub struct Editor {
    pub(crate) buf: Vec<char>,
    pub(crate) pos: usize,
    pub(crate) kill: Vec<char>,
    /// History entry shown (`None`: the draft).
    pub(crate) index: Option<usize>,
    pub(crate) draft: Vec<char>,
    pub(crate) search: Option<Search>,
    pub(crate) last_query: String,
    /// First char shown, when the line is wider than the terminal.
    pub(crate) scroll: usize,
    /// Ctrl-X was the last key: Ctrl-E next runs the line (Emacs's
    /// "evaluate", as in the notebook).
    pub(crate) prefix: bool,
}

/// A letter, digit or `_`: part of a word.
pub fn is_word(c: char) -> bool {
    c.is_alphanumeric() || c == '_'
}

impl Editor {
    /// Start a new, empty line (the kill buffer and last search are kept).
    pub fn reset(&mut self) {
        let kill = std::mem::take(&mut self.kill);
        let last_query = std::mem::take(&mut self.last_query);
        *self = Editor {
            kill,
            last_query,
            ..Editor::default()
        };
    }

    /// The text being edited.
    pub fn text(&self) -> String {
        self.buf.iter().collect()
    }

    pub fn set(&mut self, text: &str) {
        self.buf = text.chars().collect();
        self.pos = self.buf.len();
    }

    pub fn cut(&mut self, a: usize, b: usize) {
        if a < b {
            self.kill = self.buf.drain(a..b).collect();
        }
        self.pos = a;
    }
}

