24	/// The IUP code of the key the browser calls `key` with these modifiers;
25	/// `None` for keys IUP has no code for (Shift alone, media keys, ...).
26	pub fn key_code(key: &str, shift: bool, ctrl: bool, alt: bool) -> Option<u32> {
27	    let iup = NAMES.iter().find(|n| n.0 == key).map_or(key, |n| n.1);
28	    let base = match from_name(&format!("K_{iup}")).filter(|_| iup.chars().count() > 1) {
29	        Some(b) => b,
30	        None => {
31	            let mut chars = key.chars();
32	            let c = chars.next().filter(|_| chars.next().is_none())?;
33	            c as u32
34	        }
35	    };
36	    Some(code(base, shift, ctrl, alt))
37	}
