7	impl Editor {
8	    /// Apply `k`.
9	    pub fn key(&mut self, k: Key, h: &History) -> Outcome {
10	        if self.search.is_some()
11	            && let Some(o) = self.search_key(k, h)
12	        {
13	            return o;
14	        }
15	        // Ctrl-X Ctrl-E runs the line, as Enter does (and as it evaluates
16	        // a line in the notebook); any other key after Ctrl-X is itself.
17	        if std::mem::take(&mut self.prefix) && k == Key::Ctrl('e') {
18	            return Outcome::Line(self.text());
19	        }
20	        if k == Key::Ctrl('x') {
21	            self.prefix = true;
22	            return Outcome::Edit;
23	        }
24	        let n = self.buf.len();
25	        match k {
26	            Key::Enter => return Outcome::Line(self.text()),
27	            Key::Ctrl('c') => return Outcome::Cancel,
28	            Key::Ctrl('d') if n == 0 => return Outcome::Eof,
29	            Key::Ctrl('l') => return Outcome::Clear,
30	            _ => {}
31	        }
32	        if !self.move_key(k, n) && !self.edit_key(k, n) {
33	            self.history_key(k, h);
34	        }
35	        Outcome::Edit
36	    }
