38	    /// An edit of the text; false if `k` is not one.
39	    pub fn edit_key(&mut self, k: Key, n: usize) -> bool {
40	        match k {
41	            Key::Char(c) => {
42	                self.buf.insert(self.pos, c);
43	                self.pos += 1;
44	            }
45	            Key::Ctrl('d') | Key::Delete if self.pos < n => {
46	                self.buf.remove(self.pos);
47	            }
48	            Key::Ctrl('h') | Key::Backspace if self.pos > 0 => {
49	                self.pos -= 1;
50	                self.buf.remove(self.pos);
51	            }
52	            Key::Ctrl('d') | Key::Delete | Key::Ctrl('h') | Key::Backspace => {}
53	            Key::Ctrl('k') => self.cut(self.pos, n),
54	            Key::Ctrl('u') => self.cut(0, self.pos),
55	            Key::Ctrl('w') | Key::AltBackspace => self.cut(self.word_left(), self.pos),
56	            Key::Alt('d') => self.cut(self.pos, self.word_right()),
57	            Key::Ctrl('y') => {
58	                let k = self.kill.clone();
