73	    pub fn history_key(&mut self, k: Key, h: &History) {
74	        match k {
75	            Key::Ctrl('p') | Key::Up => {
76	                let to = self.index.unwrap_or(h.len()).checked_sub(1);
77	                if let Some(i) = to {
78	                    self.recall(h, Some(i));
79	                }
80	            }
81	            Key::Ctrl('n') | Key::Down => {
82	                if let Some(i) = self.index {
83	                    self.recall(h, (i + 1 < h.len()).then_some(i + 1));
84	                }
85	            }
86	            Key::Ctrl('r') | Key::Ctrl('s') => {
87	                self.search = Some(Search {
88	                    back: k == Key::Ctrl('r'),
89	                    query: String::new(),
90	                    at: None,
91	                    failed: false,
92	                    original: (self.buf.clone(), self.pos),
