99	    /// A key while searching: `Some` if it was the search's, `None` if it
100	    /// ended the search and should now be applied to the line.
101	    pub fn search_key(&mut self, k: Key, h: &History) -> Option<Outcome> {
102	        let s = self.search.as_mut().unwrap();
103	        match k {
104	            Key::Ctrl('r') | Key::Ctrl('s') => {
105	                s.back = k == Key::Ctrl('r');
106	                if s.query.is_empty() {
107	                    s.query = self.last_query.clone();
108	                }
109	                let from = s.at;
110	                self.find(h, from, false);
111	            }
112	            Key::Char(c) => {
113	                s.query.push(c);
114	                let from = s.at;
115	                self.find(h, from, true);
116	            }
117	            Key::Backspace => {
118	                s.query.pop();
119	                s.at = None;
120	                self.find(h, None, true);
121	            }
122	            Key::Ctrl('g') | Key::Ctrl('c') | Key::Esc => {
123	                let s = self.search.take().unwrap();
124	                self.last_query = s.query;
125	                (self.buf, self.pos) = s.original;
126	            }
127	            _ => {
128	                let s = self.search.take().unwrap();
129	                if !s.query.is_empty() {
130	                    self.last_query = s.query;
131	                }
132	                self.index = s.at;
133	                return None;
134	            }
