139	    /// Look for the query from history entry `from`; `stay`: the entry at
140	    /// `from` itself may match (the query grew).
141	    pub fn find(&mut self, h: &History, from: Option<usize>, stay: bool) {
142	        let s = self.search.as_mut().unwrap();
143	        let found = if s.query.is_empty() {
144	            None
145	        } else if s.back {
146	            let start = from.map_or(h.len(), |i| if stay { i + 1 } else { i });
147	            h.search_back(&s.query, start)
148	        } else {
149	            match from {
150	                Some(i) if stay && h.get(i).is_some_and(|t| t.contains(&s.query)) => Some(i),
151	                Some(i) => h.search_forward(&s.query, i),
152	                None => (0..h.len()).find(|&i| h.get(i).is_some_and(|t| t.contains(&s.query))),
153	            }
154	        };
155	        s.failed = found.is_none() && !s.query.is_empty();
156	        if let Some(i) = found {
157	            s.at = Some(i);
158	            let text = h.get(i).unwrap_or("");
159	            let q = s.query.clone();
160	            self.set(text);
161	            if let Some(b) = text.find(&q) {
162	                self.pos = text[..b].chars().count();
163	            }
164	        }
165	    }
