    this.stopTimer = setTimeout(() => {
      this.w.terminate();
      this.onOutput("\n*** not responding: restarted\n");
      this.spawn();
    }, this.o.stopTimeoutMs ?? 2000);
  }
  terminate() { clearTimeout(this.stopTimer); this.w.terminate(); }
}

