// host.js for the desktop app (served in place of components/web/crates/reva-web/www/host.js).
//
// Files live in a folder on disk (~/Reva, or the package).  The page keeps
// files through a Web Storage object, read once at start and written on
// every change, so this file gives it one: an in-memory copy of the folder,
// loaded through the `session` command, whose writes go back to disk
// through `write_file` / `remove_file`.  Keys are "reva:fs:" + VM path; the
// VM path `/a/b` is `<folder>/a/b`.  See crates/reva-desktop/src/main.rs.

const PREFIX = "reva:fs:";

export async function hostSetup() {
  const invoke = globalThis.__TAURI__.core.invoke;
  const s = await invoke("session");
  const map = new Map(s.files.map(([path, data]) => [PREFIX + path, data]));
  const report = (e) => console.warn("reva-desktop:", e);
  const storage = {
    get length() { return map.size; },
    key: (i) => [...map.keys()][i] ?? null,
    getItem: (k) => map.get(k) ?? null,
    setItem(k, v) {
      map.set(k, v);
      if (k.startsWith(PREFIX)) invoke("write_file", { path: k.slice(PREFIX.length), data: v }).catch(report);
    },
    removeItem(k) {
      map.delete(k);
      if (k.startsWith(PREFIX)) invoke("remove_file", { path: k.slice(PREFIX.length) }).catch(report);
    },
  };
  return {
    storage,
    start: s.start,
    input: s.input,
    title: s.title,
    canvas: s.canvas ?? undefined,
    // the open package's manifest keys for the About dialog (about.js)
    package: s.package ?? undefined,
    // links (About) open in the system browser, not in this window
    openUrl: (url) => invoke("open_url", { url }).catch(report),
    // SQLite for lib/db/sqlite: the VM's host calls, answered natively
    // (crates/reva-desktop/src/sql.rs) as { int }, { bytes } or { error }
    hostCall: (call) => invoke("host_call", { call }).catch((e) => ({ error: String(e) })),
    // files are the folder's: the page must not pick its own storage prefix
    keepsFiles: true,
    notes: [`files are kept in ${s.root}`, ...s.notes],
    output: s.print_output ? (text) => invoke("print", { text }) : undefined,
    // Let pending writes reach the disk before the window closes.
    halted: (code) => setTimeout(() => invoke("halt", { code }), 300),
    openWindow,
  };
}

// More windows (see www/ui.js): a second native window per name, opened by
// the `open_window` command (panes, as in the split view, are iframes in
// the page, handled by ui.js as in a browser); messages go down as `reva-ui-down` events and
// come up as `reva-ui-up` (the app adds `closed` when a window is closed).
// Events are JSON, so drawing ops travel as plain arrays.
const upListeners = new Map();
let listening = null;

  editor = lineEditor(line, { prompt: document.getElementById("prompt"), key: historyKey });
  const title = pkg?.title ?? host.title;
  if (title) {
    document.title = title;
    document.querySelector("header b").textContent = title;
  }
  if (pkg?.icon) document.querySelector('link[rel="icon"]').href = pkg.icon;
  // A package's "hint" replaces Reva's in the header (`code` in backticks).
  const hint = pkg?.hint ?? host.package?.hint;
  if (typeof hint === "string") showHint(document.getElementById("hint"), `— ${hint}`);
  // About: the package's entry (from the page's ?package= or the desktop
  // host), then reva-fork's.
  const about = aboutDialog({ pkg: pkg?.about ?? packageAbout(host.package), openUrl: host.openUrl });
  document.getElementById("about-btn").addEventListener("click", () => about.open());
  // Where graphics go: ?canvas=window|pane|split, else the package's or
  // the host's choice, else the page's default (the reva-canvas meta),
  // else a window.
  const meta = document.querySelector('meta[name="reva-canvas"]')?.content || undefined;
  const mode = query.get("canvas") ?? pkg?.canvas ?? host.canvas ?? meta ?? "window";
  const split = mode === "split" ? splitView(document.querySelector("main"), document.getElementById("panes")) : null;
  const image = query.get("image") ?? undefined;
  const gfx = document.getElementById("gfx");
  let canvas = null;
  const tui = new TuiPane(document.getElementById("tui"));
  const reva = start("reva.wasm", {
    image,
    files: pkg?.files,
    storage: host.storage,
    prefix: pkg && !host.keepsFiles ? pkg.prefix : undefined,
    onOutput: (s) => { write(s); host.output?.(s); },
    onUi: (m) => {
      if (m.channel === "canvas") canvas.handle(m);
      else if (m.channel === "tui") tui.handle(m);
    },
    // Host calls (SQLite, docs/design.md 3.11): a host that serves them
    // answers (the desktop app, natively); in a browser the VM's worker
    // answers SQLite itself with SQLite's wasm build (sqlite.js).
    localServices: host.hostCall ? [] : ["sqlite"],
    // The TUI of IUP programs is the page's own (tui.js), here and in the
    // desktop app.
    onHostCall: (call) => call.service === "ui" ? tui.answer(call)
      : host.hostCall?.(call) ?? { error: `${call.service} is not available in the browser` },
    onStatus: (s) => {
      stop.disabled = s !== RUNNING;
      // Back at the REPL or halted: no event loop runs, so the TUI steps
      // aside (it shows again at the next one).
      if (s !== RUNNING) tui.show(false);
      if (s === HALTED) {
        echo(`\n[exited with status ${reva.exitCode}]\n`);
        line.disabled = true;
        halted(reva.exitCode);
      }
    },
  });
  // Turtle graphics go to their own window (ui.js), or a pane; once used,
  // the Graphics button brings a closed one back.  The split view shows
  // its pane from the start.
  canvas = new CanvasChannel(host, reva, {
    where: mode === "window" ? "window" : "pane",
    onState: (s) => {
      if (split) return;
      gfx.hidden = false;
      gfx.textContent = s === "closed" ? "Graphics (closed)" : "Graphics";
    },
  });
  if (split) canvas.open();
  gfx.addEventListener("click", () => {
    if (canvas.win && !canvas.win.closed()) canvas.win.focus();
    else canvas.open();
  });
  // The footer: copyright, license, source, and which build this is

