// upload.js — the Upload button: files chosen on this computer go into
// the VM's file system (as /NAME) and into the page's storage, so they are
// there after a reload too.  Then `include NAME` loads a Forth file, as on
// the CLI; other files (data, a CoSy .csy) are read the same way.

import { size } from "./store.js";

const FORTH = /\.(f|fth|fs|4th|forth)$/i;

/**
 * Put `files` ({ name, bytes() }) into `session` (start()'s, which saves
 * them to storage too); the lines to show, `usage` ({ used, quota } or
 * null) last.
 */
export async function uploadFiles(files, session, usage = null) {
  const lines = [];
  for (const f of files) {
    const data = new Uint8Array(await f.bytes());
    session.put(`/${f.name}`, data);
    const how = / /.test(f.name) ? " (rename it without spaces to include it)"
      : FORTH.test(f.name) ? `: include ${f.name} loads it` : "";
    lines.push(`uploaded ${f.name} (${size(data.length)})${how}`);
  }
  const u = await usage;
  if (u) lines.push(`storage: ${size(u.used)} used of ${size(u.quota)} for this site`);
  return lines;
}

/** Wire `button` to a file chooser that uploads into `session`. */
export function uploadButton(button, { session, storage, echo }) {
  const input = document.createElement("input");
  input.type = "file";
  input.multiple = true;
  input.hidden = true;
  button.after(input);
  button.hidden = false;
  button.addEventListener("click", () => input.click());
  input.addEventListener("change", async () => {
    const chosen = [...input.files].map((f) => ({ name: f.name, bytes: () => f.arrayBuffer() }));
    input.value = "";
    const lines = await uploadFiles(chosen, session, storage?.usage?.());
    echo(lines.map((l) => l + "\n").join(""));
  });
}

// host.js — what the page gets from where it runs.  This is the browser's:
// files persist in IndexedDB (store.js; localStorage where IndexedDB cannot
// open), `?include=FILE` (repeatable) includes FILE after start and again
// after each `restart`, and `?eval=TEXT` (repeatable) feeds a line once.
// The desktop app serves its own host.js in this file's place (files on
// disk, packages); index.html is the same in both.
//
// hostSetup() resolves to { storage, start, input, title?, output?(text),
// halted?(code), notes }.

import { openIdbStorage } from "./store.js";

/** localStorage, or null where the browser blocks site data. */
function webStorage() {
  try {
    const s = globalThis.localStorage ?? null;
    s?.length; // throws where site data is blocked
    return s;
  } catch {
    return null;
  }
}

export async function hostSetup() {
  const legacy = webStorage();
  const notes = [];
  let storage = legacy;
  try {
    const opened = await openIdbStorage({ legacy });
    storage = opened.storage;
    if (opened.moved) notes.push(`${opened.moved} saved file(s) moved from localStorage to IndexedDB`);
  } catch (e) {
    console.warn("reva: IndexedDB not available, files go to localStorage:", e);
  }
  if (!storage) notes.push("files are not kept: this browser blocks storage");
  const q = new URLSearchParams(globalThis.location?.search ?? "");
