< <script type="module">
<   // The VM runs in a Web Worker (see reva.js `start`), so this page only
<   // draws: output is appended at most once per animation frame, and the
<   // console keeps its last MAX_CHUNKS pieces so a chatty program cannot
<   // grow the page without bound.
<   import { start, RUNNING, HALTED } from "./reva.js";
<   import { hostSetup } from "./host.js";
<   import { CanvasChannel } from "./ui.js";
<   import { TuiPane } from "./tui.js";
<   import { loadPackage } from "./package.js";
<   import { splitView } from "./split.js";
<   import { aboutDialog, packageAbout, showHint } from "./about.js";
<   import { lineEditor } from "./lineedit.js";
<   import { packageId } from "./package.js";
<   import { Ansi } from "./ansi.js";
<   const MAX_CHUNKS = 4000;
<   const out = document.getElementById("out");
<   const line = document.getElementById("line");
<   const stop = document.getElementById("stop");
<   let pending = "", frame = 0;
<   const append = (s, cls) => {
<     const span = document.createElement("span");
<     if (cls) span.className = cls;
<     span.textContent = s;
<     out.append(span);
<     while (out.childElementCount > MAX_CHUNKS) out.firstElementChild.remove();
<     return span;
<   };
<   // Forth output may carry ANSI colour (ansi.js): one span per flush, with
<   // a child span per coloured run, so MAX_CHUNKS still counts flushes.
<   const ansi = new Ansi();
<   const appendOut = (s) => {
<     const runs = ansi.feed(s);
<     if (runs.length === 1 && !runs[0][1]) return append(runs[0][0]);
<     const span = append("");
<     for (const [t, c] of runs) {
<       if (!c) { span.append(t); continue; }
<       const r = document.createElement("span");
<       r.className = c;
<       r.textContent = t;
<       span.append(r);
<     }
<     return span;
<   };
<   // Follow the output only if the view was at the bottom before the write,
<   // so a reader who scrolled up is not pulled down; scroll after the
<   // coloured runs are in, so a long `pp` listing ends in view.
<   const atBottom = () => out.scrollHeight - out.scrollTop - out.clientHeight < 24;
<   const toBottom = () => { out.scrollTop = out.scrollHeight; };
<   const flush = () => {
<     frame = 0;
<     if (!pending) return;
<     const follow = atBottom();
<     appendOut(pending);
<     pending = "";
<     if (follow) toBottom();
<   };
<   const write = (s) => { pending += s; frame ||= requestAnimationFrame(flush); };
<   // Echoed input (a submitted line, notes) always brings the view down.
<   const echo = (s) => { flush(); append(s, "echo"); toBottom(); };
<   // The form is live from the start (a package can take a moment to
<   // fetch): lines typed before the VM is up wait in `early`.
<   const early = [];
<   let feedLine = (text) => early.push(text);
<   // History and Emacs keys (lineedit.js) are set up once the package is
<   // known, since each package keeps its own history; until then the line
<   // is a plain input.
<   let editor = null;
<   document.getElementById("f").addEventListener("submit", (e) => {
<     e.preventDefault();
<     const text = line.value;
<     line.value = "";
<     editor?.accept(text);
<     echo(text + "\n");
<     feedLine(text);
<   });
