/// Remember reva.f's own prompt: call right after booting reva.f
/// (not from an image), before any program runs.  Kept in images.
fn record_prompt(&mut self) {
    let p = self.mem.read_u32(st::PROMPT).expect("prompt");
    self.mem.write_u32(st::PROMPT_DEFAULT, p).expect("prompt");
}

/// The interactive prompt (`reva.f` prints `ok> ` before each line it
/// reads) off for batch use (piped input, tests, embedding), or on.
/// Only reva.f's own prompt is changed: one a program installed (an
/// image's) is kept.  An image without the record (older ones) is
/// quieted as before.
fn quiet_prompt(&mut self, quiet: bool) {
    let p = self.mem.read_u32(st::PROMPT).expect("prompt");
    let own = self.mem.read_u32(st::PROMPT_DEFAULT).expect("prompt");
    let noop = Gate::Noop.addr();
    let set = match (quiet, own) {
        (true, 0) => Some(noop),
        (true, _) if p == own => Some(noop),
        (false, own) if p == noop && own != 0 => Some(own),
        _ => None,
    };
    if let Some(v) = set {
        self.mem.write_u32(st::PROMPT, v).expect("prompt");
    }
}

