fn summary(files: usize, fixed: usize, left: usize, fixing: bool) -> String {
    match (fixing, left) {
        (_, 0) if fixed == 0 => format!("port-check: {files} file(s), nothing Windows-only found\n"),
        (true, _) => format!("port-check: {files} file(s): {fixed} fixed in the copies, {left} to do by hand\n"),
        (false, _) => format!("port-check: {files} file(s): {left} finding(s); --fix DIR writes copies with the safe fixes\n"),
    }
}

/// Write `path`'s migrated copy into `dir`, never over a source file.
fn write_copy(dir: &Path, path: &Path, fixed: &[u8]) -> Result<(), String> {
    let name = path.file_name().ok_or(format!("{}: not a file", path.display()))?;
    fs::create_dir_all(dir).map_err(|e| format!("{}: {e}", dir.display()))?;
    let out = dir.join(name);
    let same = fs::canonicalize(&out).ok() == fs::canonicalize(path).ok();
    if same {
        return Err(format!("{}: --fix would write over the source; choose another folder", out.display()));
    }
    fs::write(&out, fixed).map_err(|e| format!("{}: {e}", out.display()))
}

/// Report an error and give status 2.
fn fail(msg: &str) -> ExitCode {
    eprintln!("reva --port-check: {msg}");
    ExitCode::from(2)
}

