/// Where the library tree `lib/` appears: `libdir` (see [`APP_PATH`]).
pub const LIB_ROOT: &str = "/reva/lib";

// `LIB_FILES`: (path below `lib/`, contents) for every file in `lib/`,
// sorted by path; generated by build.rs.  Empty without `embed-lib`.
include!(concat!(env!("OUT_DIR"), "/lib_files.rs"));

/// An embedded library file by absolute path (`/reva/lib/util/locals`).
pub fn lib_file(path: &str) -> Option<&'static [u8]> {
    let rel = path.strip_prefix(LIB_ROOT)?.strip_prefix('/')?;
    LIB_FILES
        .binary_search_by(|(p, _)| (*p).cmp(rel))
        .ok()
        .map(|i| LIB_FILES[i].1)
}

/// The names in an embedded directory (`/`, `/reva`, `/reva/lib`, or a
/// directory below it), or `None` if the embedded tree has no such
/// directory.
pub fn lib_dir(path: &str) -> Option<Vec<String>> {
    let prefix = if path == "/" {
        "/".to_string()
    } else {
        format!("{path}/")
    };
    let mut names: Vec<String> = Vec::new();
    for (rel, _) in LIB_FILES {
        let full = format!("{LIB_ROOT}/{rel}");
        if let Some(rest) = full.strip_prefix(&prefix) {
            let name = rest.split('/').next().unwrap_or(rest);
            if !names.iter().any(|n| n == name) {
                names.push(name.to_string());
            }
        }
    }
    (!names.is_empty()).then_some(names)
}

