// A static server that caches like python3 -m http.server: Last-Modified,
// no Cache-Control, 304 for If-Modified-Since.  node serve-lm.mjs DIR PORT
import { createServer } from "node:http";
import { readFile, stat } from "node:fs/promises";
import { join, extname, normalize } from "node:path";

const [dir, port] = [process.argv[2], Number(process.argv[3] ?? 8001)];
const types = { ".html": "text/html", ".js": "text/javascript", ".wasm": "application/wasm", ".json": "application/json", ".png": "image/png", ".f": "text/plain" };
createServer(async (req, res) => {
  const path = decodeURIComponent(new URL(req.url, "http://x").pathname);
  const p = join(dir, normalize(path === "/" ? "/index.html" : path));
  try {
    const st = await stat(p);
    const lm = st.mtime.toUTCString();
    const ims = req.headers["if-modified-since"];
    if (ims && new Date(ims) >= new Date(lm)) {
      res.writeHead(304, { "last-modified": lm });
      return res.end();
    }
    res.writeHead(200, { "content-type": types[extname(p)] ?? "application/octet-stream", "last-modified": lm });
    res.end(await readFile(p));
  } catch {
    res.writeHead(404);
    res.end();
  }
}).listen(port, "127.0.0.1");

