// A line, as typed and Entered: history, echo, then the VM's input
// (queued there, so Stop and the runaway guard apply between lines).
const runLine = (text) => {
  editor?.accept(text);
  echo(text + "\n");
  feedLine(text);
};
document.getElementById("f").addEventListener("submit", (e) => {
  e.preventDefault();
  const text = line.value;
  line.value = "";
  runLine(text);
});
// Pasted lines run one by one; the last, unfinished one stays in the box.
line.addEventListener("paste", (e) => {
  const pasted = e.clipboardData?.getData("text") ?? "";
  if (!/[\r\n]/.test(pasted)) return;
  e.preventDefault();
  const { lines, rest, pos } = pasteLines(line.value, line.selectionStart, line.selectionEnd, pasted);
  line.value = "";
  lines.forEach(runLine);
  line.value = rest;
  line.setSelectionRange(pos, pos);
});

