// Pasted lines run one by one, each once the VM waits for input again, so
// the output reads like a session; the last, unfinished one stays in the
// box.  Stop drops the lines not yet run, as it drops typed-ahead input.
let pasting = 0;
line.addEventListener("paste", async (e) => {
  const pasted = e.clipboardData?.getData("text") ?? "";
  if (!/[\r\n]/.test(pasted)) return;
  e.preventDefault();
  const { lines, rest, pos } = pasteLines(line.value, line.selectionStart, line.selectionEnd, pasted);
  line.value = rest;
  line.setSelectionRange(pos, pos);
  const run = ++pasting;
  for (const text of lines) {
    if (run !== pasting || (await reva.idle()) === HALTED || run !== pasting) break;
    runLine(text);
  }
});
document.getElementById("stop").addEventListener("click", () => pasting++);

