/// The C string at `a` (up to 4 KiB), Latin-1.
fn zstr(mem: &dyn Memory, a: u32) -> String {
    let bytes = mem.bytes(a, 4096).or_else(|| mem.bytes(a, 256)).unwrap_or_default();
    bytes.iter().take_while(|b| **b != 0).map(|b| *b as char).collect()
}

