// reva-worker.js — the Reva VM in a Web Worker, so the page never waits
// for it.  Started by `start()` in reva.js; it can also be driven directly.
//
// Messages (all plain objects with a `type`):
//
//   page → worker   init   { wasm: URL or bytes, files: { path: bytes },
//                            image?: URL or bytes, local?: [service] }
//                                        local: host-call services this
//                                        worker answers itself ("sqlite":
//                                        sqlite.js) instead of the page
//                   input  { text }      a line (or any text) to read
//                   start  { text }      start input: read now and again
//                                        after each `restart`
//                   put    { path, data } add a file (an upload); the page
//                                        saves it to storage itself
//                   close  {}            end of input
//                   stop   {}            interrupt the running word
//                   resume { ms }        go on after "paused": ms more (0: no
//                                        limit; none: the guard's guardMs)
//                   hidden { hidden }    the page is hidden: pause; shown: go on
//                   ui     { channel, resend? }
//                                        a UI channel: "canvas" + resend
//                                        asks for the whole drawing again
//                   hostreply { reply }  the answer to a hostcall: { int },
//                                        { bytes } or { error }
//   worker → page   output { text }      text printed since the last one
//                   ui     { channel: "canvas", ops | reset }
//                                        drawing ops since the last slice
//                                        (Float32Array, transferred), or
//                                        reset after `restart`
//                   status { status, exitCode, boot?, build?, reason? }
//                                        "running", NEED_INPUT or HALTED;
//                                        after boot, the build facts
//                   files  { list }      [{ path, data: bytes | null }]
//                   hostcall { call }    the VM waits for this call's answer
//                                        ({ service, op, ints, bytes }; see
//                                        Reva.hostCall), sent back as
//                                        hostreply
//                   error  { message }
//
// The worker runs the VM in slices of about 8 ms and yields between them,
// so `input` and `stop` messages are seen within one slice.  While Forth
// waits for input the worker is idle: no polling, no CPU.

import { Reva, RUNNING, HALTED, HOST_CALL, PAUSED } from "./reva.js";

let reva = null;
let pumping = false;
// A host call posted to the page and not yet answered: the VM is stopped
// on it, so input that arrives meanwhile is queued without running (running
// would only post the same call again, and its extra answers would go to
// later calls).
let waiting = false;
// Services this worker answers itself (init's `local`): "sqlite" in the
// browser (sqlite.js); the desktop's page answers instead.
let local = new Set();
let sqlite = null;
async function answerLocally(call) {
  sqlite ??= new (await import("./sqlite.js")).SqliteHost();
  return sqlite.answer(call);
}
const post = (m, transfer) => globalThis.postMessage(m, transfer);
const postUi = (m) => post(m, m.ops ? [m.ops.buffer] : []);

// The runaway guard: a run that goes `guardMs` without waiting for input
// pauses (no slices, no CPU) until the page says resume or stop; `limit`
// is this run's (null: the guard's, 0: none).  A hidden page pauses too.
let guardMs = 5000;
let limit = null;
let hidden = false;
let paused = null; // why the VM is paused: "time" or "hidden"
let wake = null; // ends an `ms` wait early (Stop)

async function pump() {
  if (pumping || waiting || !reva) return;
  pumping = true;
  paused = null;
  post({ type: "status", status: RUNNING });
  let s;
  try {
    const opts = { onUi: postUi, limitMs: limit ?? guardMs, paused: () => hidden };
    s = await reva.run((text) => post({ type: "output", text }), opts);
  } catch (e) {
    post({ type: "error", message: String(e?.message ?? e) });
    s = HALTED;
  }
  pumping = false;
  if (s === PAUSED) {
    paused = hidden ? "hidden" : "time";
    return post({ type: "status", status: PAUSED, reason: paused, seconds: (limit ?? guardMs) / 1000 });
  }
  limit = null;
  sendFiles();
  // A host call: the page answers (hostreply), and the VM runs on.
  if (s === HOST_CALL) {
    const call = reva.hostCall();
    // `ms` (a `clock` `sleep`): wait here, the page drawing meanwhile; it
    // is not running, so the guard does not count it; Stop ends it early.
    if (call.service === "clock") {
      await new Promise((r) => {
        const t = setTimeout(r, Number(call.ints[0] ?? 0));
        wake = () => { clearTimeout(t); r(); };
      });
      wake = null;
      reva.resume({ int: 0 });
      return pump();
    }
    if (!local.has(call.service)) {
      waiting = true;
      return post({ type: "hostcall", call });
    }
    reva.resume(await answerLocally(call));
    return pump();
  }
  post({ type: "status", status: s, exitCode: s === HALTED ? reva.exitCode : 0 });
}

function sendFiles() {
  const list = reva.changes();
  if (list.length) post({ type: "files", list }, list.flatMap((c) => (c.data ? [c.data.buffer] : [])));
}

// Messages are handled one at a time, in order, so input that arrives
// while `init` is still loading the module waits for it.
let queue = Promise.resolve();
globalThis.onmessage = ({ data: m }) => {
  queue = queue.then(() => handle(m));
};

async function handle(m) {
  switch (m.type) {
    case "init":
      local = new Set(m.local ?? []);
      guardMs = m.guardMs ?? guardMs;
      try {
        reva = await Reva.load(m.wasm, { files: m.files ?? {}, image: m.image });
      } catch (e) {
        post({ type: "error", message: `could not start: ${e?.message ?? e}` });
        return;
      }
      reva.setClock();
      post({ type: "output", text: reva.takeOutput() });
      post({ type: "status", status: reva.status, exitCode: 0, boot: true, build: reva.build });
      break;
    case "input":
      reva.feed(m.text);
      if (!paused) pump(); // paused: read once the page says go on
      break;
    case "start":
      reva.feedStart(m.text);
      pump();
      break;
    case "put":
      reva?.put(m.path, m.data);
      break;
    case "close":
      reva.closeInput();
      pump();
      break;
    case "hostreply":
      waiting = false;
      reva.resume(m.reply);
      pump();
      break;
    case "stop":
      if (pumping) reva.interrupt();
      if (paused) {
        reva.interrupt();
        limit = null;
        pump();
      }
      break;
    case "resume":
      if (paused) {
        limit = m.ms ?? null;
        pump();
      }
      break;
    case "hidden":
      hidden = m.hidden;
      if (!hidden && paused === "hidden") pump();
      break;
    case "ui":
      reva?.ui(m);
      if (!pumping) reva?.flushUi(postUi);
      break;
