//! The CD functions Reva programs call (`lib/ui/cd`), on [`Cd`]: their
//! arguments are the `(call)`'s cells, first C argument first; strings and
//! bitmaps are read through [`Memory`]; what a function returns through
//! pointers comes back as writes for the caller to make.

use crate::draw::Op;
use crate::state::{Bitmap, Canvas, Cd};

/// The CD functions served.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum CdFn {
    ContextIup,
    CreateCanvas,
    KillCanvas,
    Activate,
    ActiveCanvas,
    Clear,
    Foreground,
    Background,
    LineStyle,
    LineWidth,
    InteriorStyle,
    MarkType,
    MarkSize,
    Font,
    Line,
    Box,
    Rect,
    Mark,
    Pixel,
    Begin,
    Vertex,
    End,
    Text,
    VectorText,
    CanvasVectorText,
    EncodeColor,
    GetCanvasSize,
    InitBitmap,
    PutBitmap,
    KillBitmap,
    /// Returns 0 and does nothing (flush, text direction, versions ...).
    Zero,
}

/// The VM's memory, as CD calls need it.
pub trait Memory {
    /// `n` bytes at `a`, or `None` outside memory.
    fn bytes(&self, a: u32, n: u32) -> Option<Vec<u8>>;
}

/// What a call returns, and the writes it asks for: (address, bytes).
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct Done {
    pub value: u32,
    pub writes: Vec<(u32, Vec<u8>)>,
}

/// CD_QUERY: ask for an attribute without setting it.
const QUERY: u32 = u32::MAX;
/// The interior style that draws no fill (CD_HOLLOW), and CD_FILL.
const HOLLOW: i32 = 4;
const FILL: i32 = 0;

impl Cd {
    /// Run CD function `f` with arguments `a`.
    pub fn call(&mut self, f: CdFn, a: &[u32], mem: &dyn Memory) -> Done {
        let arg = |i: usize| a.get(i).copied().unwrap_or(0);
        let value = match f {
            CdFn::ContextIup => 0x4344_0000,
            CdFn::CreateCanvas => {
                let n = self.number();
                self.canvases.insert(n, Canvas::new(arg(1)));
                n
            }
            CdFn::KillCanvas => {
                self.canvases.remove(&arg(0));
                self.active = if self.active == arg(0) {
                    0
                } else {
                    self.active
                };
                0
            }
            CdFn::Activate if arg(0) == 0 || self.canvases.contains_key(&arg(0)) => {
                self.active = arg(0);
                0
            }
            CdFn::Activate => u32::MAX,
            CdFn::ActiveCanvas => self.active,
            CdFn::EncodeColor => (arg(0) & 255) << 16 | (arg(1) & 255) << 8 | (arg(2) & 255),
            CdFn::GetCanvasSize => return self.canvas_size(a),
            CdFn::InitBitmap => self.init_bitmap(a, mem),
            CdFn::KillBitmap => {
                self.bitmaps.remove(&arg(0));
                0
            }
            CdFn::Zero => 0,
            _ => self.on_active(f, a, mem),
        };
        Done {
            value,
            writes: Vec::new(),
        }
    }

    /// An attribute or a drawing on the active canvas (0 with none).
    fn on_active(&mut self, f: CdFn, a: &[u32], mem: &dyn Memory) -> u32 {
        let n = |i: usize| a.get(i).copied().unwrap_or(0) as i32;
        let text = |i: usize| zstr(mem, a.get(i).copied().unwrap_or(0));
        let bitmap = self.bitmaps.get(&a.first().copied().unwrap_or(0)).cloned();
        let canvas = match f {
            CdFn::CanvasVectorText => self.canvases.get_mut(&a.first().copied().unwrap_or(0)),
            _ => self.canvases.get_mut(&self.active),
        };
        let Some(c) = canvas else { return 0 };
        let set = |v: &mut i32, x: i32| if x == -1 { *v } else { std::mem::replace(v, x) };
        let old = match f {
            CdFn::Foreground if a.first() != Some(&QUERY) => {
                std::mem::replace(&mut c.foreground, rgb(n(0))) as i32
            }
            CdFn::Foreground => c.foreground as i32,
            CdFn::Background if a.first() != Some(&QUERY) => {
                std::mem::replace(&mut c.background, rgb(n(0))) as i32
            }
            CdFn::Background => c.background as i32,
            CdFn::LineStyle => set(&mut c.line_style, n(0)),
            CdFn::LineWidth => set(&mut c.line_width, n(0)),
            CdFn::InteriorStyle => set(&mut c.interior, n(0)),
            CdFn::MarkType => set(&mut c.mark_type, n(0)),
            CdFn::MarkSize => set(&mut c.mark_size, n(0)),
            CdFn::Font => set(&mut c.text_size, n(2).abs()),
            _ => return draw(c, f, &n, text, bitmap),
        };
        old as u32
    }

    /// `cdGetCanvasSize(int *w, int *h, double *w_mm, double *h_mm)`.
    fn canvas_size(&self, a: &[u32]) -> Done {
        let element = self.canvases.get(&self.active).map_or(0, |c| c.element);
        let (w, h) = self.size(element);
        let mm = |px: i32| (px as f64 * 25.4 / 96.0).to_le_bytes().to_vec();
        let all = [
            (0, (w as u32).to_le_bytes().to_vec()),
            (1, (h as u32).to_le_bytes().to_vec()),
            (2, mm(w)),
            (3, mm(h)),
        ];
        let writes = all
            .into_iter()
            .filter_map(|(i, b)| a.get(i).filter(|p| **p != 0).map(|p| (*p, b)))
            .collect();
        Done { value: 0, writes }
    }

    /// `cdInitBitmap(w, h, type, ...)`: CD_RGB (r, g, b planes) or CD_MAP
    /// (an index per pixel and a 256-colour table); a new bitmap's number.
    fn init_bitmap(&mut self, a: &[u32], mem: &dyn Memory) -> u32 {
        let arg = |i: usize| a.get(i).copied().unwrap_or(0);
        let (w, h) = (arg(0) as i32, arg(1) as i32);
        let n = (w.max(0) * h.max(0)) as u32;
        let read = |p: u32, len: u32| mem.bytes(p, len).unwrap_or_else(|| vec![0; len as usize]);
        let pixels = match arg(2) {
            1 => {
                let index = read(arg(3), n);
                let colors = read(arg(4), 256 * 4);
                let color = |i: u8| {
                    u32::from_le_bytes(
                        colors[4 * i as usize..4 * i as usize + 4]
                            .try_into()
                            .unwrap(),
                    ) & 0xff_ffff
                };
                index.into_iter().map(color).collect()
            }
            _ => {
                let (r, g, b) = (read(arg(3), n), read(arg(4), n), read(arg(5), n));
                (0..n as usize)
                    .map(|i| (r[i] as u32) << 16 | (g[i] as u32) << 8 | b[i] as u32)
                    .collect()
            }
        };
        let id = self.number();
        self.bitmaps.insert(id, Bitmap { w, h, pixels });
        id
    }
}

/// A drawing on canvas `c` with its attributes (0 returned).
fn draw(
    c: &mut Canvas,
    f: CdFn,
    n: &dyn Fn(usize) -> i32,
    text: impl Fn(usize) -> String,
    bitmap: Option<Bitmap>,
) -> u32 {
    let fg = c.foreground;
    let op = match f {
        CdFn::Clear => {
            c.ops.clear();
            Some(Op::Clear(c.background))
        }
        CdFn::Line => Some(Op::Line {
            from: (n(0), n(1)),
            to: (n(2), n(3)),
            color: fg,
            style: c.line_style,
            width: c.line_width,
        }),
        CdFn::Box | CdFn::Rect => Some(Op::Box {
            lo: (n(0), n(2)),
            hi: (n(1), n(3)),
            color: fg,
            filled: f == CdFn::Box && c.interior != HOLLOW,
        }),
        CdFn::Mark => Some(Op::Mark {
            at: (n(0), n(1)),
            kind: c.mark_type,
            size: c.mark_size,
            color: fg,
        }),
        CdFn::Pixel => Some(Op::Box {
            lo: (n(0), n(1)),
            hi: (n(0), n(1)),
            color: rgb(n(2)),
            filled: true,
        }),
        CdFn::Text | CdFn::VectorText => Some(Op::Text {
            at: (n(0), n(1)),
            color: fg,
            size: c.text_size,
            text: text(2),
        }),
        CdFn::CanvasVectorText => Some(Op::Text {
            at: (n(1), n(2)),
            color: fg,
            size: c.text_size,
            text: text(3),
        }),
        CdFn::PutBitmap => bitmap.map(|b| Op::Image {
            at: (n(1), n(2)),
            size: (n(3), n(4)),
            w: b.w,
            h: b.h,
            pixels: b.pixels,
        }),
        CdFn::Begin => {
            c.poly = Some((n(0), Vec::new()));
            None
        }
        CdFn::Vertex => {
            if let Some((_, pts)) = c.poly.as_mut() {
                pts.push((n(0), n(1)));
            }
            None
        }
        CdFn::End => c.poly.take().map(|(mode, points)| Op::Poly {
            points,
            color: fg,
            filled: mode == FILL,
        }),
        _ => None,
    };
    if let Some(op) = op {
        c.ops.push(op);
        c.dirty = true;
    }
    0
}

/// The C string at `a` (up to 4 KiB), Latin-1.
fn zstr(mem: &dyn Memory, a: u32) -> String {
    let bytes = mem
        .bytes(a, 4096)
        .or_else(|| mem.bytes(a, 256))
        .unwrap_or_default();
    bytes
        .iter()
        .take_while(|b| **b != 0)
        .map(|b| *b as char)
        .collect()
}

/// A CD colour's red, green and blue (its top byte is alpha, which the
/// display list does not keep).
fn rgb(v: i32) -> u32 {
    v as u32 & 0xff_ffff
}

use reva_cd::calls::{CdFn, Done, Memory};
use reva_cd::draw::{Op, decode, encode};
use reva_cd::state::Cd;
use std::collections::HashMap;

/// Memory for the tests: byte strings at addresses.
#[derive(Default)]
struct Mem(HashMap<u32, Vec<u8>>);

impl Memory for Mem {
    fn bytes(&self, a: u32, n: u32) -> Option<Vec<u8>> {
        let (start, b) = self
            .0
            .iter()
            .find(|(s, b)| (**s..**s + b.len() as u32).contains(&a))?;
        let from = (a - start) as usize;
        Some(
            b[from..]
                .iter()
                .copied()
                .chain(std::iter::repeat(0))
                .take(n as usize)
                .collect(),
        )
    }
}

fn call(cd: &mut Cd, f: CdFn, a: &[u32], mem: &Mem) -> u32 {
    cd.call(f, a, mem).value
}

#[test]
fn operations_survive_their_text_form() {
    let ops = vec![
        Op::Clear(0x808080),
        Op::Line {
            from: (0, 0),
            to: (30, 30),
            color: 0x0000ff,
            style: 2,
            width: 1,
        },
        Op::Box {
            lo: (60, 0),
            hi: (90, 20),
            color: 0xff0000,
            filled: true,
        },
        Op::Mark {
            at: (40, 10),
            kind: 5,
            size: 10,
            color: 0,
        },
        Op::Text {
            at: (100, 10),
            color: 0xff0000,
            size: 12,
            text: "a; b\\c".into(),
        },
        Op::Image {
            at: (70, 70),
            size: (32, 32),
            w: 2,
            h: 1,
            pixels: vec![0x0000ff, 0xffff00],
        },
        Op::Poly {
            points: vec![(0, 0), (10, 0), (5, 8)],
            color: 0x00ff00,
            filled: true,
        },
    ];
    assert_eq!(decode(&encode(&ops)), ops);
    assert!(decode("").is_empty());
}

#[test]
fn a_redraw_as_cd_test_does_it() {
    let (mut cd, mem) = (Cd::default(), Mem::default());
    let ctx = call(&mut cd, CdFn::ContextIup, &[], &mem);
    let c = call(&mut cd, CdFn::CreateCanvas, &[ctx, 7], &mem);
    assert_eq!(call(&mut cd, CdFn::Activate, &[c], &mem), 0);
    assert_eq!(
        call(&mut cd, CdFn::Activate, &[12345], &mem),
        u32::MAX,
        "an unknown canvas is CD_ERROR"
    );
    assert_eq!(call(&mut cd, CdFn::ActiveCanvas, &[], &mem), c);
    call(&mut cd, CdFn::Background, &[0x808080], &mem);
    call(&mut cd, CdFn::Clear, &[], &mem);
    assert_eq!(
        call(&mut cd, CdFn::Foreground, &[0x0000ff], &mem),
        0x000000,
        "the old foreground"
    );
    assert_eq!(
        call(&mut cd, CdFn::Foreground, &[u32::MAX], &mem),
        0x0000ff,
        "CD_QUERY"
    );
    call(&mut cd, CdFn::LineStyle, &[2], &mem);
    call(&mut cd, CdFn::Line, &[0, 0, 30, 30], &mem);
    call(&mut cd, CdFn::Box, &[60, 90, 0, 20], &mem);
    let flushed = cd.flush();
    assert_eq!(flushed.len(), 1);
    assert_eq!(flushed[0].0, 7, "the IUP element's DRAW");
    assert_eq!(
        decode(&flushed[0].1),
        vec![
            Op::Clear(0x808080),
            Op::Line {
                from: (0, 0),
                to: (30, 30),
                color: 0x0000ff,
                style: 2,
                width: 1
            },
            Op::Box {
                lo: (60, 0),
                hi: (90, 20),
                color: 0x0000ff,
                filled: true
            },
        ]
    );
    assert!(cd.flush().is_empty(), "clean until drawn again");
    call(&mut cd, CdFn::Clear, &[], &mem);
    assert_eq!(
        decode(&cd.flush()[0].1),
        vec![Op::Clear(0x808080)],
        "clear starts a new frame"
    );
}

#[test]
fn bitmaps_and_the_canvas_size() {
    let mut mem = Mem::default();
    mem.0.insert(1000, vec![1, 0, 0, 1]);
    let colors: Vec<u8> = [0x0000ffu32, 0xffff00]
        .iter()
        .flat_map(|c| c.to_le_bytes())
        .chain(std::iter::repeat_n(0, 254 * 4))
        .collect();
    mem.0.insert(2000, colors);
    mem.0.insert(3000, b"hi\0".to_vec());
    let mut cd = Cd::default();
    let c = call(&mut cd, CdFn::CreateCanvas, &[0, 9], &mem);
    call(&mut cd, CdFn::Activate, &[c], &mem);
    let b = call(&mut cd, CdFn::InitBitmap, &[2, 2, 1, 1000, 2000], &mem);
    call(&mut cd, CdFn::PutBitmap, &[b, 5, 6, 16, 16], &mem);
