//! The renderer's state, shared by the element and the page's calls.

use std::cell::RefCell;
use std::rc::Rc;

use reva_ui_layout::geom::Size;
use reva_ui_mirror::mirror::Mirror;

/// The model as the VM's changes describe it, the screen size in cells,
/// where events go (the page's function), and how to draw again.
pub struct State {
    pub mirror: Mirror,
    pub size: Size,
    pub on_event: Option<js_sys::Function>,
    pub redraw: Option<Rc<dyn Fn()>>,
}

thread_local! {
    static STATE: RefCell<State> = RefCell::new(State {
        mirror: Mirror::default(),
        size: Size { cols: 80, rows: 24 },
        on_event: None,
        redraw: None,
    });
}

/// `f` of the state.
pub fn with<R>(f: impl FnOnce(&mut State) -> R) -> R {
    STATE.with(|s| f(&mut s.borrow_mut()))
}

/// Send event lines to the page, which answers the VM's wait with them.
pub fn send(lines: Vec<String>) {
    let Some(f) = with(|s| s.on_event.clone()) else {
        return;
    };
    for line in lines {
        let _ = f.call1(&wasm_bindgen::JsValue::NULL, &line.into());
    }
}

/// Draw the element again.
pub fn redraw() {
    if let Some(r) = with(|s| s.redraw.clone()) {
        r();
    }
}
//! What the page calls (www/tui.js).

use reva_ui_layout::geom::Size;
use reva_ui_mirror::mirror::Mirror;
use wasm_bindgen::prelude::*;

use crate::state::{redraw, with};
use crate::view::Tui;

/// Draw the TUI in `root`; event lines go to `on_event(line)`.
#[wasm_bindgen]
pub fn mount(root: web_sys::Element, on_event: js_sys::Function) {
    with(|s| s.on_event = Some(on_event));
    yew::Renderer::<Tui>::with_root(root).render();
}

/// Apply the change lines of a `ui` `wait` call; whether a dialog is
/// shown (the page shows the TUI only then).
#[wasm_bindgen]
pub fn changes(lines: &str) -> bool {
    with(|s| s.mirror.apply_lines(lines));
    redraw();
    shown()
}

/// The screen is now `cols` by `rows` cells.
#[wasm_bindgen]
pub fn resize(cols: u16, rows: u16) {
    with(|s| {
        s.size = Size {
            cols: cols.max(1),
            rows: rows.max(1),
        }
    });
    redraw();
}

/// Whether a dialog is shown.
#[wasm_bindgen]
pub fn shown() -> bool {
    with(|s| !s.mirror.shown.is_empty())
}

/// Forget the UI (the VM restarted).
#[wasm_bindgen]
pub fn reset() {
    with(|s| s.mirror = Mirror::default());
    redraw();
}

/// Type `text` into the focused element (a paste the page caught).
#[wasm_bindgen]
pub fn paste(text: &str) {
    crate::state::send(crate::keys::pasted(text));
}
