# shows the same page): a Yew element drawing reva-ui-grid's cells.
# One Cargo workspace per component (docs/code-metrics.md); the build
# output goes to the repository's target/ (.cargo/config.toml).
[workspace]
resolver = "2"
members = ["crates/reva-ui-web"]

[workspace.package]
version = "0.1.0"
edition = "2024"
publish = false
[dependencies]
reva-ui-base = { path = "../../../ui/crates/reva-ui-base" }
