//! Painting a display list on a 2D context.

use reva_cd::draw::{Op, Rgb, decode};
use wasm_bindgen::{JsCast, JsValue};
use web_sys::{CanvasRenderingContext2d, HtmlCanvasElement};

/// Paint `draw` (a `DRAW` value) on `canvas`, sized to its box in CSS
/// pixels first; that size, for the canvas's `size` event.
pub fn paint(canvas: &HtmlCanvasElement, draw: &str) -> (i32, i32) {
    let (w, h) = (canvas.client_width().max(1), canvas.client_height().max(1));
    if canvas.width() != w as u32 || canvas.height() != h as u32 {
        canvas.set_width(w as u32);
        canvas.set_height(h as u32);
    }
    let ctx = canvas.get_context("2d").ok().flatten().and_then(|c| c.dyn_into::<CanvasRenderingContext2d>().ok());
    if let Some(ctx) = ctx {
        for op in decode(draw) {
            one(&ctx, &op, h);
        }
    }
    (w, h)
}

/// `#rrggbb`.
fn css(c: Rgb) -> String {
    format!("#{:06x}", c & 0xff_ffff)
}

/// One operation; `h` flips CD's y (up) to the screen's (down).
fn one(ctx: &CanvasRenderingContext2d, op: &Op, h: i32) {
    let y = |v: i32| f64::from(h - 1 - v);
    match op {
        Op::Clear(c) => {
            ctx.set_fill_style_str(&css(*c));
            ctx.fill_rect(0.0, 0.0, 1e6, 1e6);
        }
        Op::Line { from, to, color, style, width } => {
            let dash: &[f64] = match style {
                1 => &[6.0, 3.0],
                2 => &[1.0, 2.0],
                3 => &[6.0, 3.0, 1.0, 3.0],
                4 => &[6.0, 3.0, 1.0, 3.0, 1.0, 3.0],
                _ => &[],
            };
            let pattern = js_sys_array(dash);
            let _ = ctx.set_line_dash(&pattern);
            ctx.set_stroke_style_str(&css(*color));
            ctx.set_line_width(f64::from((*width).max(1)));
            ctx.begin_path();
            ctx.move_to(f64::from(from.0) + 0.5, y(from.1) + 0.5);
            ctx.line_to(f64::from(to.0) + 0.5, y(to.1) + 0.5);
            ctx.stroke();
            let _ = ctx.set_line_dash(&js_sys_array(&[]));
        }
        Op::Box { lo, hi, color, filled } => {
            let (x0, x1) = (lo.0.min(hi.0), lo.0.max(hi.0));
            let (y0, y1) = (lo.1.min(hi.1), lo.1.max(hi.1));
            let (left, top, w, hh) = (f64::from(x0), y(y1), f64::from(x1 - x0 + 1), f64::from(y1 - y0 + 1));
            if *filled {
                ctx.set_fill_style_str(&css(*color));
                ctx.fill_rect(left, top, w, hh);
            } else {
                ctx.set_stroke_style_str(&css(*color));
                ctx.stroke_rect(left + 0.5, top + 0.5, w - 1.0, hh - 1.0);
            }
        }
        Op::Mark { at, kind, size, color } => mark(ctx, f64::from(at.0), y(at.1), *kind, f64::from(*size), &css(*color)),
        Op::Text { at, color, size, text } => {
            ctx.set_fill_style_str(&css(*color));
            ctx.set_font(&format!("{}px monospace", (*size).max(6)));
            let _ = ctx.fill_text(text, f64::from(at.0), y(at.1));
        }
        Op::Image { at, size, w, h: ih, pixels } => {
            let (cw, ch) = (f64::from(size.0) / f64::from((*w).max(1)), f64::from(size.1) / f64::from((*ih).max(1)));
            for (i, p) in pixels.iter().enumerate() {
                let (col, row) = ((i as i32 % w.max(&1)) as f64, (i as i32 / w.max(&1)) as f64);
                ctx.set_fill_style_str(&css(*p));
                ctx.fill_rect(f64::from(at.0) + col * cw, y(at.1) + 1.0 - (row + 1.0) * ch, cw, ch);
            }
        }
        Op::Poly { points, color, filled } => {
            ctx.begin_path();
            for (i, p) in points.iter().enumerate() {
                let (px, py) = (f64::from(p.0) + 0.5, y(p.1) + 0.5);
                if i == 0 { ctx.move_to(px, py) } else { ctx.line_to(px, py) }
            }
            ctx.close_path();
            if *filled {
                ctx.set_fill_style_str(&css(*color));
                ctx.fill();
            } else {
                ctx.set_stroke_style_str(&css(*color));
                ctx.stroke();
            }
        }
    }
}

/// A CD mark of `kind` and `size` (pixels) centred at `x`, `y`: plus, star,
/// circle, x, box, diamond, then the hollow circle, box and diamond.
fn mark(ctx: &CanvasRenderingContext2d, x: f64, y: f64, kind: i32, size: f64, color: &str) {
    let r = (size / 2.0).max(1.0);
    ctx.set_fill_style_str(color);
    ctx.set_stroke_style_str(color);
    ctx.set_line_width(1.0);
    ctx.begin_path();
    match kind {
        0 | 1 | 3 => {
            if kind != 3 {
                ctx.move_to(x - r, y);
                ctx.line_to(x + r, y);
                ctx.move_to(x, y - r);
                ctx.line_to(x, y + r);
            }
            if kind != 0 {
                ctx.move_to(x - r, y - r);
                ctx.line_to(x + r, y + r);
                ctx.move_to(x - r, y + r);
                ctx.line_to(x + r, y - r);
            }
            ctx.stroke();
        }
        2 | 6 => {
