//! The element: the grid as rows of spans, a class per colour role (the
//! page's stylesheet colours them with its theme), the cursor a span of
//! its own; keys and clicks go back to the VM as event lines.

use std::rc::Rc;

use reva_ui_grid::grid::{Grid, Role};
use reva_ui_layout::geom::Rect;
use reva_ui_paint::paint::{click, paint};
use wasm_bindgen::JsCast;
use yew::prelude::*;

use crate::keys::{clipboard_key, key_code, pasted};
use crate::state::{send, with};

/// The stylesheet class of a role.
fn class(role: Role) -> &'static str {
    match role {
        Role::Screen => "tui-screen",
        Role::Dialog => "tui-dialog",
        Role::Border => "tui-border",
        Role::Title => "tui-title",
        Role::Text => "tui-text",
        Role::Button => "tui-button",
        Role::Focus => "tui-focus",
        Role::Active => "tui-active",
        Role::Field => "tui-field",
        Role::Selection => "tui-selection",
        Role::Disabled => "tui-disabled",
    }
}

/// Row `r` of `g` as spans: runs of one role, the cursor apart.
fn row(g: &Grid, r: u16) -> Html {
    let mut spans = Vec::new();
    let (mut text, mut role, mut cursor) = (String::new(), None, false);
    for c in 0..g.cols {
        let cell = g.cell(c, r).copied().expect("on the grid");
        let here = g.cursor == Some((c, r));
        if role != Some(cell.role) || here || cursor {
            if let Some(ro) = role.filter(|_| !text.is_empty()) {
                spans.push(html! { <span class={classes!(class(ro), cursor.then_some("tui-cursor"))}>{ std::mem::take(&mut text) }</span> });
            }
            (role, cursor) = (Some(cell.role), here);
        }
        text.push(cell.ch);
    }
    if let Some(ro) = role {
        spans.push(html! { <span class={classes!(class(ro), cursor.then_some("tui-cursor"))}>{ text }</span> });
    }
    html! { <div class="tui-row">{ for spans }</div> }
}

/// A key: its IUP code to the VM, the browser's own use of it prevented.
fn on_key(e: KeyboardEvent) {
    if clipboard_key(&e.key(), e.ctrl_key(), e.meta_key()) {
        return;
    }
    if let Some(code) = key_code(
        &e.key(),
        e.shift_key(),
        e.ctrl_key() || e.meta_key(),
        e.alt_key(),
    ) {
        e.prevent_default();
        send(vec![format!("key {code}")]);
    }
}

/// A paste: the clipboard's text typed into the focused element.
fn on_paste(e: Event) {
    let Some(text) = e
        .dyn_ref::<web_sys::ClipboardEvent>()
        .and_then(|c| c.clipboard_data())
        .and_then(|d| d.get_data("text/plain").ok())
    else {
        return;
    };
    e.prevent_default();
    send(pasted(&text));
}

/// A click: the cell under it, from the element's size in cells.
fn on_click(e: MouseEvent) {
    let Some(el) = e
        .current_target()
        .and_then(|t| t.dyn_into::<web_sys::Element>().ok())
    else {
        return;
    };
    let r = el.get_bounding_client_rect();
    let lines = with(|s| {
        let size = s.size;
        let col = ((f64::from(e.client_x()) - r.left()) * f64::from(size.cols) / r.width().max(1.0))
            as u16;
        let row = ((f64::from(e.client_y()) - r.top()) * f64::from(size.rows) / r.height().max(1.0))
            as u16;
        click(&s.mirror, size, col, row)
    });
    send(lines);
}

/// An HTML canvas over an IUP canvas's cells (inside its frame), placed in
/// percent of the grid so it follows the element's size.
fn overlay(g: &Grid, h: u32, r: Rect) -> Html {
    let pct = |a: u16, of: u16| f64::from(a) * 100.0 / f64::from(of.max(1));
    let (cols, rows) = (
        r.cols.saturating_sub(2).max(1),
        r.rows.saturating_sub(2).max(1),
    );
    let style = format!(
        "left:{}%;top:{}%;width:{}%;height:{}%",
        pct(r.col + 1, g.cols),
        pct(r.row + 1, g.rows),
        pct(cols, g.cols),
        pct(rows, g.rows)
    );
    html! { <canvas class="tui-canvas" data-h={h.to_string()} style={style} /> }
}

/// Paint every IUP canvas's DRAW list; a canvas whose size changed is
/// reported to the VM (`size H W H`: RESIZE_CB, then its redraw).
fn paint_canvases() {
    let Some(doc) = web_sys::window().and_then(|w| w.document()) else {
        return;
    };
    let Ok(list) = doc.query_selector_all(".tui-canvas") else {
        return;
    };
    let mut events = Vec::new();
    for i in 0..list.length() {
        let Some(el) = list
            .item(i)
            .and_then(|n| n.dyn_into::<web_sys::HtmlCanvasElement>().ok())
        else {
            continue;
        };
        let Some(h) = el
            .get_attribute("data-h")
            .and_then(|v| v.parse::<u32>().ok())
        else {
            continue;
        };
        let draw = with(|s| s.mirror.tree.attr(h, "DRAW")).unwrap_or_default();
        let size = reva_ui_canvas2d::paint::paint(&el, &draw);
        if with(|s| s.canvas_sizes.insert(h, size)) != Some(size) {
            events.push(format!("size {h} {} {}", size.0, size.1));
        }
    }
    send(events);
}

/// The TUI element.
#[function_component]
pub fn Tui() -> Html {
    let update = use_force_update();
    use_effect_with((), move |_| {
        with(|s| s.redraw = Some(Rc::new(move || update.force_update())));
    });
    use_effect(|| paint_canvases());
    let g = with(|s| paint(&s.mirror, s.size));
    html! {
        <div class="tui" tabindex="0" onkeydown={Callback::from(on_key)} onmousedown={Callback::from(on_click)} onpaste={Callback::from(on_paste)}>
            { for (0..g.rows).map(|r| row(&g, r)) }
            { for g.canvases.iter().map(|(h, r)| overlay(&g, *h, *r)) }
        </div>
    }
}

//! The renderer's state, shared by the element and the page's calls.

use std::cell::RefCell;
use std::rc::Rc;

use reva_ui_layout::geom::Size;
use reva_ui_mirror::mirror::Mirror;

/// The model as the VM's changes describe it, the screen size in cells,
/// where events go (the page's function), and how to draw again.
pub struct State {
    pub mirror: Mirror,
    pub size: Size,
    pub on_event: Option<js_sys::Function>,
    pub redraw: Option<Rc<dyn Fn()>>,
    /// The size (pixels) each IUP canvas was last reported at.
    pub canvas_sizes: std::collections::BTreeMap<u32, (i32, i32)>,
}

thread_local! {
    static STATE: RefCell<State> = RefCell::new(State {
        mirror: Mirror::default(),
        size: Size { cols: 80, rows: 24 },
        on_event: None,
        redraw: None,
        canvas_sizes: std::collections::BTreeMap::new(),
    });
}

/// `f` of the state.
pub fn with<R>(f: impl FnOnce(&mut State) -> R) -> R {
    STATE.with(|s| f(&mut s.borrow_mut()))
}

/// Send event lines to the page, which answers the VM's wait with them.
pub fn send(lines: Vec<String>) {
    let Some(f) = with(|s| s.on_event.clone()) else {
        return;
    };
    for line in lines {
        let _ = f.call1(&wasm_bindgen::JsValue::NULL, &line.into());
    }
}

/// Draw the element again.
pub fn redraw() {
    if let Some(r) = with(|s| s.redraw.clone()) {
        r();
    }
}

//! Painting a display list on a 2D context.

use reva_cd::draw::{Op, Rgb, decode};
use wasm_bindgen::{JsCast, JsValue};
use web_sys::{CanvasRenderingContext2d, HtmlCanvasElement};

/// Paint `draw` (a `DRAW` value) on `canvas`, sized to its box in CSS
/// pixels first; that size, for the canvas's `size` event.
pub fn paint(canvas: &HtmlCanvasElement, draw: &str) -> (i32, i32) {
    let (w, h) = (canvas.client_width().max(1), canvas.client_height().max(1));
    if canvas.width() != w as u32 || canvas.height() != h as u32 {
        canvas.set_width(w as u32);
        canvas.set_height(h as u32);
    }
    let ctx = canvas
        .get_context("2d")
        .ok()
        .flatten()
        .and_then(|c| c.dyn_into::<CanvasRenderingContext2d>().ok());
    if let Some(ctx) = ctx {
        for op in decode(draw) {
            one(&ctx, &op, h);
        }
    }
    (w, h)
}

/// `#rrggbb`.
fn css(c: Rgb) -> String {
    format!("#{:06x}", c & 0xff_ffff)
}

/// One operation; `h` flips CD's y (up) to the screen's (down).
fn one(ctx: &CanvasRenderingContext2d, op: &Op, h: i32) {
    let y = |v: i32| f64::from(h - 1 - v);
    match op {
        Op::Clear(c) => {
            ctx.set_fill_style_str(&css(*c));
            ctx.fill_rect(0.0, 0.0, 1e6, 1e6);
        }
        Op::Line {
            from,
            to,
            color,
            style,
            width,
        } => {
            let dash: &[f64] = match style {
                1 => &[6.0, 3.0],
                2 => &[1.0, 2.0],
                3 => &[6.0, 3.0, 1.0, 3.0],
                4 => &[6.0, 3.0, 1.0, 3.0, 1.0, 3.0],
                _ => &[],
            };
            let pattern = js_sys_array(dash);
            let _ = ctx.set_line_dash(&pattern);
            ctx.set_stroke_style_str(&css(*color));
            ctx.set_line_width(f64::from((*width).max(1)));
            ctx.begin_path();
            ctx.move_to(f64::from(from.0) + 0.5, y(from.1) + 0.5);
            ctx.line_to(f64::from(to.0) + 0.5, y(to.1) + 0.5);
            ctx.stroke();
            let _ = ctx.set_line_dash(&js_sys_array(&[]));
        }
        Op::Box {
            lo,
            hi,
            color,
            filled,
        } => {
            let (x0, x1) = (lo.0.min(hi.0), lo.0.max(hi.0));
            let (y0, y1) = (lo.1.min(hi.1), lo.1.max(hi.1));
            let (left, top, w, hh) = (
                f64::from(x0),
                y(y1),
                f64::from(x1 - x0 + 1),
                f64::from(y1 - y0 + 1),
            );
            if *filled {
                ctx.set_fill_style_str(&css(*color));
                ctx.fill_rect(left, top, w, hh);
            } else {
                ctx.set_stroke_style_str(&css(*color));
                ctx.stroke_rect(left + 0.5, top + 0.5, w - 1.0, hh - 1.0);
            }
        }
        Op::Mark {
            at,
            kind,
            size,
            color,
        } => mark(
            ctx,
            f64::from(at.0),
            y(at.1),
            *kind,
            f64::from(*size),
            &css(*color),
        ),
        Op::Text {
            at,
            color,
            size,
            text,
        } => {
            ctx.set_fill_style_str(&css(*color));
            ctx.set_font(&format!("{}px monospace", (*size).max(6)));
            let _ = ctx.fill_text(text, f64::from(at.0), y(at.1));
        }
        Op::Image {
            at,
            size,
            w,
            h: ih,
            pixels,
        } => {
            let (cw, ch) = (
                f64::from(size.0) / f64::from((*w).max(1)),
                f64::from(size.1) / f64::from((*ih).max(1)),
            );
            for (i, p) in pixels.iter().enumerate() {
                let (col, row) = ((i as i32 % w.max(&1)) as f64, (i as i32 / w.max(&1)) as f64);
                ctx.set_fill_style_str(&css(*p));
                ctx.fill_rect(
                    f64::from(at.0) + col * cw,
                    y(at.1) + 1.0 - (row + 1.0) * ch,
                    cw,
                    ch,
                );
            }
        }
        Op::Poly {
            points,
            color,
            filled,
        } => {
            ctx.begin_path();
            for (i, p) in points.iter().enumerate() {
                let (px, py) = (f64::from(p.0) + 0.5, y(p.1) + 0.5);
                if i == 0 {
                    ctx.move_to(px, py)
                } else {
                    ctx.line_to(px, py)
                }
            }
            ctx.close_path();
            if *filled {
                ctx.set_fill_style_str(&css(*color));
                ctx.fill();
            } else {
                ctx.set_stroke_style_str(&css(*color));
                ctx.stroke();
            }
        }
    }
}

/// A CD mark of `kind` and `size` (pixels) centred at `x`, `y`: plus, star,
/// circle, x, box, diamond, then the hollow circle, box and diamond.
fn mark(ctx: &CanvasRenderingContext2d, x: f64, y: f64, kind: i32, size: f64, color: &str) {
    let r = (size / 2.0).max(1.0);
    ctx.set_fill_style_str(color);
    ctx.set_stroke_style_str(color);
    ctx.set_line_width(1.0);
    ctx.begin_path();
    match kind {
        0 | 1 | 3 => {
            if kind != 3 {
                ctx.move_to(x - r, y);
                ctx.line_to(x + r, y);
                ctx.move_to(x, y - r);
                ctx.line_to(x, y + r);
            }
            if kind != 0 {
                ctx.move_to(x - r, y - r);
                ctx.line_to(x + r, y + r);
                ctx.move_to(x - r, y + r);
                ctx.line_to(x + r, y - r);
            }
            ctx.stroke();
        }
        2 | 6 => {
            let _ = ctx.arc(x, y, r, 0.0, std::f64::consts::TAU);
            if kind == 2 { ctx.fill() } else { ctx.stroke() }
        }
        4 | 7 => {
            ctx.rect(x - r, y - r, 2.0 * r, 2.0 * r);
            if kind == 4 { ctx.fill() } else { ctx.stroke() }
        }
        _ => {
            ctx.move_to(x, y - r);
            ctx.line_to(x + r, y);
            ctx.line_to(x, y + r);
            ctx.line_to(x - r, y);
            ctx.close_path();
            if kind == 5 { ctx.fill() } else { ctx.stroke() }
        }
    }
}

/// A JS array of numbers (a dash pattern).
fn js_sys_array(v: &[f64]) -> JsValue {
    let a = web_sys::js_sys::Array::new();
    for x in v {
        a.push(&JsValue::from_f64(*x));
    }
    a.into()
}

//! The grid of cells.

use reva_ui_layout::geom::Rect;

/// What a cell is part of; a backend gives each role its theme's colours.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash)]
pub enum Role {
    /// Outside every dialog.
    #[default]
    Screen,
    /// A dialog's or a frame's inside.
    Dialog,
    /// Borders of dialogs, frames and edit panes.
    Border,
    /// A dialog's or a frame's title.
    Title,
    /// Labels.
    Text,
    /// Buttons and toggles.
    Button,
    /// The element with the focus: a button's face.
    Focus,
    /// The border of the edit pane or list with the focus.
    Active,
    /// Where text is edited, lists, canvases.
    Field,
    /// Selected text, a list's selected item.
    Selection,
    /// Elements with ACTIVE=NO.
    Disabled,
}

/// One character cell.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Cell {
    pub ch: char,
    pub role: Role,
}

/// A screen of cells, row by row, and where the text cursor is (the
/// focused text element's caret), if anywhere.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Grid {
    pub cols: u16,
    pub rows: u16,
    pub cells: Vec<Cell>,
    pub cursor: Option<(u16, u16)>,
    /// The IUP canvases painted, with their rectangles: a renderer that
    /// can draw lays a drawing surface over each (their DRAW lists).
    pub canvases: Vec<(u32, Rect)>,
}

