7	/// Paint `draw` (a `DRAW` value) on `canvas`, sized to its box in CSS
8	/// pixels first; that size, for the canvas's `size` event.
9	pub fn paint(canvas: &HtmlCanvasElement, draw: &str) -> (i32, i32) {
10	    let (w, h) = (canvas.client_width().max(1), canvas.client_height().max(1));
11	    if canvas.width() != w as u32 || canvas.height() != h as u32 {
12	        canvas.set_width(w as u32);
13	        canvas.set_height(h as u32);
14	    }
15	    let ctx = canvas
16	        .get_context("2d")
17	        .ok()
18	        .flatten()
19	        .and_then(|c| c.dyn_into::<CanvasRenderingContext2d>().ok());
20	    if let Some(ctx) = ctx {
21	        for op in decode(draw) {
22	            one(&ctx, &op, h);
23	        }
24	    }
25	    (w, h)
26	}
