33	/// One operation; `h` flips CD's y (up) to the screen's (down).
34	fn one(ctx: &CanvasRenderingContext2d, op: &Op, h: i32) {
35	    let y = |v: i32| f64::from(h - 1 - v);
36	    match op {
37	        Op::Clear(c) => {
38	            ctx.set_fill_style_str(&css(*c));
39	            ctx.fill_rect(0.0, 0.0, 1e6, 1e6);
40	        }
41	        Op::Line {
42	            from,
43	            to,
44	            color,
45	            style,
46	            width,
47	        } => {
48	            let dash: &[f64] = match style {
49	                1 => &[6.0, 3.0],
50	                2 => &[1.0, 2.0],
51	                3 => &[6.0, 3.0, 1.0, 3.0],
52	                4 => &[6.0, 3.0, 1.0, 3.0, 1.0, 3.0],
53	                _ => &[],
54	            };
55	            let pattern = js_sys_array(dash);
56	            let _ = ctx.set_line_dash(&pattern);
57	            ctx.set_stroke_style_str(&css(*color));
58	            ctx.set_line_width(f64::from((*width).max(1)));
59	            ctx.begin_path();
60	            ctx.move_to(f64::from(from.0) + 0.5, y(from.1) + 0.5);
61	            ctx.line_to(f64::from(to.0) + 0.5, y(to.1) + 0.5);
62	            ctx.stroke();
63	            let _ = ctx.set_line_dash(&js_sys_array(&[]));
64	        }
65	        Op::Box {
66	            lo,
67	            hi,
68	            color,
69	            filled,
70	        } => {
71	            let (x0, x1) = (lo.0.min(hi.0), lo.0.max(hi.0));
72	            let (y0, y1) = (lo.1.min(hi.1), lo.1.max(hi.1));
73	            let (left, top, w, hh) = (
74	                f64::from(x0),
75	                y(y1),
76	                f64::from(x1 - x0 + 1),
77	                f64::from(y1 - y0 + 1),
78	            );
79	            if *filled {
80	                ctx.set_fill_style_str(&css(*color));
81	                ctx.fill_rect(left, top, w, hh);
82	            } else {
83	                ctx.set_stroke_style_str(&css(*color));
84	                ctx.stroke_rect(left + 0.5, top + 0.5, w - 1.0, hh - 1.0);
85	            }
86	        }
