102	            color,
103	            size,
104	            text,
105	        } => {
106	            ctx.set_fill_style_str(&css(*color));
107	            ctx.set_font(&format!("{}px monospace", (*size).max(6)));
108	            let _ = ctx.fill_text(text, f64::from(at.0), y(at.1));
109	        }
110	        Op::Image {
111	            at,
112	            size,
113	            w,
114	            h: ih,
115	            pixels,
116	        } => {
117	            let (cw, ch) = (
118	                f64::from(size.0) / f64::from((*w).max(1)),
119	                f64::from(size.1) / f64::from((*ih).max(1)),
120	            );
121	            for (i, p) in pixels.iter().enumerate() {
122	                let (col, row) = ((i as i32 % w.max(&1)) as f64, (i as i32 / w.max(&1)) as f64);
123	                ctx.set_fill_style_str(&css(*p));
124	                ctx.fill_rect(
