158	/// A CD mark of `kind` and `size` (pixels) centred at `x`, `y`: plus, star,
159	/// circle, x, box, diamond, then the hollow circle, box and diamond.
160	fn mark(ctx: &CanvasRenderingContext2d, x: f64, y: f64, kind: i32, size: f64, color: &str) {
161	    let r = (size / 2.0).max(1.0);
162	    ctx.set_fill_style_str(color);
163	    ctx.set_stroke_style_str(color);
164	    ctx.set_line_width(1.0);
165	    ctx.begin_path();
166	    match kind {
167	        0 | 1 | 3 => {
168	            if kind != 3 {
169	                ctx.move_to(x - r, y);
170	                ctx.line_to(x + r, y);
171	                ctx.move_to(x, y - r);
172	                ctx.line_to(x, y + r);
173	            }
174	            if kind != 0 {
175	                ctx.move_to(x - r, y - r);
176	                ctx.line_to(x + r, y + r);
177	                ctx.move_to(x - r, y + r);
178	                ctx.line_to(x + r, y - r);
179	            }
180	            ctx.stroke();
181	        }
182	        2 | 6 => {
183	            let _ = ctx.arc(x, y, r, 0.0, std::f64::consts::TAU);
184	            if kind == 2 { ctx.fill() } else { ctx.stroke() }
185	        }
186	        4 | 7 => {
187	            ctx.rect(x - r, y - r, 2.0 * r, 2.0 * r);
188	            if kind == 4 { ctx.fill() } else { ctx.stroke() }
189	        }
190	        _ => {
191	            ctx.move_to(x, y - r);
192	            ctx.line_to(x + r, y);
193	            ctx.line_to(x, y + r);
194	            ctx.line_to(x - r, y);
195	            ctx.close_path();
196	            if kind == 5 { ctx.fill() } else { ctx.stroke() }
197	        }
198	    }
199	}
200	
201	/// A JS array of numbers (a dash pattern).
202	fn js_sys_array(v: &[f64]) -> JsValue {
203	    let a = web_sys::js_sys::Array::new();
204	    for x in v {
205	        a.push(&JsValue::from_f64(*x));
206	    }
207	    a.into()
