/// One operation; `h` flips CD's y (up) to the screen's (down).
fn one(ctx: &CanvasRenderingContext2d, op: &Op, h: i32) {
    let y = |v: i32| f64::from(h - 1 - v);
    match op {
        Op::Clear(c) => {
            ctx.set_fill_style_str(&css(*c));
            ctx.fill_rect(0.0, 0.0, 1e6, 1e6);
        }
        Op::Line { from, to, color, style, width } => {
            let ends = (f64::from(from.0), y(from.1), f64::from(to.0), y(to.1));
            line(ctx, ends, &css(*color), *style, *width);
        }
        Op::Box { lo, hi, color, filled } => {
            let (x0, x1) = (lo.0.min(hi.0), lo.0.max(hi.0));
            let (y0, y1) = (lo.1.min(hi.1), lo.1.max(hi.1));
            let r = (f64::from(x0), y(y1), f64::from(x1 - x0 + 1), f64::from(y1 - y0 + 1));
            rect(ctx, r, &css(*color), *filled);
        }
        Op::Mark { at, kind, size, color } => {
            mark(ctx, f64::from(at.0), y(at.1), *kind, f64::from(*size), &css(*color))
        }
        Op::Text { at, color, size, text } => {
            ctx.set_fill_style_str(&css(*color));
            ctx.set_font(&format!("{}px monospace", (*size).max(6)));
            let _ = ctx.fill_text(text, f64::from(at.0), y(at.1));
        }
        Op::Image { at, size, w, h: ih, pixels } => {
            let cell = (f64::from(size.0) / f64::from((*w).max(1)), f64::from(size.1) / f64::from((*ih).max(1)));
            image(ctx, (f64::from(at.0), y(at.1) + 1.0), cell, (*w).max(1), pixels);
        }
        Op::Poly { points, color, filled } => {
            let pts: Vec<(f64, f64)> = points.iter().map(|p| (f64::from(p.0) + 0.5, y(p.1) + 0.5)).collect();
            poly(ctx, &pts, &css(*color), *filled);
        }
    }
}

/// A line from `(x0, y0)` to `(x1, y1)` in CD's line style and width.
fn line(ctx: &CanvasRenderingContext2d, (x0, y0, x1, y1): (f64, f64, f64, f64), color: &str, style: i32, width: i32) {
    let dash: &[f64] = match style {
        1 => &[6.0, 3.0],
        2 => &[1.0, 2.0],
        3 => &[6.0, 3.0, 1.0, 3.0],
        4 => &[6.0, 3.0, 1.0, 3.0, 1.0, 3.0],
        _ => &[],
    };
    let _ = ctx.set_line_dash(&js_sys_array(dash));
    ctx.set_stroke_style_str(color);
    ctx.set_line_width(f64::from(width.max(1)));
    ctx.begin_path();
    ctx.move_to(x0 + 0.5, y0 + 0.5);
    ctx.line_to(x1 + 0.5, y1 + 0.5);
    ctx.stroke();
    let _ = ctx.set_line_dash(&js_sys_array(&[]));
}

/// A box, filled or its outline: left, top, width, height.
fn rect(ctx: &CanvasRenderingContext2d, (left, top, w, h): (f64, f64, f64, f64), color: &str, filled: bool) {
    if filled {
        ctx.set_fill_style_str(color);
        ctx.fill_rect(left, top, w, h);
    } else {
        ctx.set_stroke_style_str(color);
        ctx.stroke_rect(left + 0.5, top + 0.5, w - 1.0, h - 1.0);
    }
}

/// An image `w` pixels wide, bottom row first, its lower left at `(x, y)`,
/// each pixel a `cell` (width, height) box.
fn image(ctx: &CanvasRenderingContext2d, (x, y): (f64, f64), (cw, ch): (f64, f64), w: i32, pixels: &[Rgb]) {
    for (i, p) in pixels.iter().enumerate() {
        let (col, row) = (f64::from(i as i32 % w), f64::from(i as i32 / w));
        ctx.set_fill_style_str(&css(*p));
        ctx.fill_rect(x + col * cw, y - (row + 1.0) * ch, cw, ch);
    }
}

/// A closed polygon, filled or its outline.
fn poly(ctx: &CanvasRenderingContext2d, points: &[(f64, f64)], color: &str, filled: bool) {
    ctx.begin_path();
    for (i, &(x, y)) in points.iter().enumerate() {
        if i == 0 { ctx.move_to(x, y) } else { ctx.line_to(x, y) }
    }
    ctx.close_path();
    if filled {
        ctx.set_fill_style_str(color);
        ctx.fill();
    } else {
        ctx.set_stroke_style_str(color);
        ctx.stroke();
    }
}
