//! What a canvas shows: a list of operations in CD's coordinates (pixels,
//! the origin at the bottom left, y up), each with the colour and style it
//! was drawn with, and their text form, the value of the IUP canvas's
//! `DRAW` attribute: items separated by `;`, fields by spaces, colours as
//! six hex digits, a text last (with `\;` and `\\` for `;` and `\`).

/// A colour, `0xRRGGBB` (CD's `long` colours without alpha).
pub type Rgb = u32;

/// One drawing operation.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Op {
    /// The whole canvas in a colour (`cdClear`, the background).
    Clear(Rgb),
    /// `cdLine`: a line in a style (CD's line styles) and width.
    Line {
        from: (i32, i32),
        to: (i32, i32),
        color: Rgb,
        style: i32,
        width: i32,
    },
    /// `cdBox` (filled) or `cdRect` (outlined): corners `lo` and `hi`.
    Box {
        lo: (i32, i32),
        hi: (i32, i32),
        color: Rgb,
        filled: bool,
    },
    /// `cdMark`: a marker of CD's mark type and size centred at `at`.
    Mark {
        at: (i32, i32),
        kind: i32,
        size: i32,
        color: Rgb,
    },
    /// `cdText` / `cdVectorText`: a text with its left baseline at `at`.
    Text {
        at: (i32, i32),
        color: Rgb,
        size: i32,
        text: String,
    },
    /// `cdPutBitmap`: `w`×`h` pixels (row 0 at the bottom, as in CD)
    /// drawn at `at`, scaled to `size`.
    Image {
        at: (i32, i32),
        size: (i32, i32),
        w: i32,
        h: i32,
        pixels: Vec<Rgb>,
    },
    /// `cdBegin`…`cdEnd`: a polygon, filled or a closed line.
    Poly {
        points: Vec<(i32, i32)>,
        color: Rgb,
        filled: bool,
    },
}

/// `ops` in text form.
pub fn encode(ops: &[Op]) -> String {
    ops.iter().map(item).collect::<Vec<_>>().join(";")
}

/// One operation in text form.
fn item(op: &Op) -> String {
    let xy = |p: &(i32, i32)| format!("{} {}", p.0, p.1);
    match op {
        Op::Clear(c) => format!("c {c:06x}"),
        Op::Line {
            from,
            to,
            color,
            style,
            width,
        } => format!("l {} {} {color:06x} {style} {width}", xy(from), xy(to)),
        Op::Box {
            lo,
            hi,
            color,
            filled,
        } => format!(
            "{} {} {} {color:06x}",
            if *filled { "b" } else { "r" },
            xy(lo),
            xy(hi)
        ),
        Op::Mark {
            at,
            kind,
            size,
            color,
        } => format!("m {} {kind} {size} {color:06x}", xy(at)),
        Op::Text {
            at,
            color,
            size,
            text,
        } => format!("t {} {color:06x} {size} {}", xy(at), escape(text)),
        Op::Image {
            at,
            size,
            w,
            h,
            pixels,
        } => {
            let px: String = pixels.iter().map(|p| format!("{p:06x}")).collect();
            format!("i {} {} {w} {h} {px}", xy(at), xy(size))
        }
        Op::Poly {
            points,
            color,
            filled,
        } => {
            let pts: Vec<String> = points.iter().map(xy).collect();
            format!(
                "{} {color:06x} {}",
                if *filled { "P" } else { "p" },
                pts.join(" ")
            )
        }
    }
}

/// A text with `\` and `;` escaped.
fn escape(s: &str) -> String {
    s.replace('\\', "\\\\").replace(';', "\\;")
}

/// The operations of a `DRAW` value; items it cannot read are skipped.
pub fn decode(s: &str) -> Vec<Op> {
    let mut items = Vec::new();
    let mut cur = String::new();
    let mut chars = s.chars();
    while let Some(c) = chars.next() {
        match c {
            '\\' => cur.extend(chars.next()),
            ';' => items.push(std::mem::take(&mut cur)),
            c => cur.push(c),
        }
    }
    items.push(cur);
    items.iter().filter_map(|i| parse(i)).collect()
}

/// One item in text form, read back.
fn parse(item: &str) -> Option<Op> {
    let (verb, rest) = item.split_once(' ')?;
    let f: Vec<&str> = rest.split(' ').collect();
    let n = |i: usize| f.get(i)?.parse::<i32>().ok();
    let c = |i: usize| u32::from_str_radix(f.get(i)?, 16).ok();
    let p = |i: usize| Some((n(i)?, n(i + 1)?));
    Some(match verb {
        "c" => Op::Clear(c(0)?),
        "l" => Op::Line {
            from: p(0)?,
            to: p(2)?,
            color: c(4)?,
            style: n(5)?,
            width: n(6)?,
        },
        "b" | "r" => Op::Box {
            lo: p(0)?,
            hi: p(2)?,
            color: c(4)?,
            filled: verb == "b",
        },
        "m" => Op::Mark {
            at: p(0)?,
            kind: n(2)?,
            size: n(3)?,
            color: c(4)?,
        },
        "t" => Op::Text {
            at: p(0)?,
            color: c(2)?,
            size: n(3)?,
            text: f.get(4..)?.join(" "),
        },
        "i" => {
            let (w, h) = (n(4)?, n(5)?);
            let hex = f.get(6).copied().unwrap_or("");
            let pixels = (0..hex.len() / 6)
                .filter_map(|k| u32::from_str_radix(&hex[6 * k..6 * k + 6], 16).ok())
                .collect();
            Op::Image {
                at: p(0)?,
                size: p(2)?,
                w,
                h,
                pixels,
            }
        }
        "p" | "P" => {
            let points = (1..f.len()).step_by(2).filter_map(p).collect();
            Op::Poly {
                points,
                color: c(0)?,
                filled: verb == "P",
            }
        }
        _ => return None,
    })
}
