/// A drawing on canvas `c` with its attributes (0 returned).
fn draw(
    c: &mut Canvas,
    f: CdFn,
    n: &dyn Fn(usize) -> i32,
    text: impl Fn(usize) -> String,
    bitmap: Option<Bitmap>,
) -> u32 {
    let fg = c.foreground;
    let op = match f {
        CdFn::Clear => {
            c.ops.clear();
            Some(Op::Clear(c.background))
        }
        CdFn::Line => Some(Op::Line {
            from: (n(0), n(1)),
            to: (n(2), n(3)),
            color: fg,
            style: c.line_style,
            width: c.line_width,
        }),
        CdFn::Box | CdFn::Rect => Some(Op::Box {
            lo: (n(0), n(2)),
            hi: (n(1), n(3)),
            color: fg,
            filled: f == CdFn::Box && c.interior != HOLLOW,
        }),
        CdFn::Mark => Some(Op::Mark {
            at: (n(0), n(1)),
            kind: c.mark_type,
            size: c.mark_size,
            color: fg,
        }),
        CdFn::Pixel => Some(Op::Box {
            lo: (n(0), n(1)),
            hi: (n(0), n(1)),
            color: rgb(n(2)),
            filled: true,
        }),
        CdFn::Text | CdFn::VectorText => Some(Op::Text {
            at: (n(0), n(1)),
            color: fg,
            size: c.text_size,
            text: text(2),
        }),
        CdFn::CanvasVectorText => Some(Op::Text {
            at: (n(1), n(2)),
            color: fg,
            size: c.text_size,
            text: text(3),
        }),
        CdFn::PutBitmap => bitmap.map(|b| Op::Image {
            at: (n(1), n(2)),
            size: (n(3), n(4)),
            w: b.w,
            h: b.h,
            pixels: b.pixels,
        }),
        CdFn::Begin => {
            c.poly = Some((n(0), Vec::new()));
            None
        }
        CdFn::Vertex => {
            if let Some((_, pts)) = c.poly.as_mut() {
                pts.push((n(0), n(1)));
            }
            None
        }
        CdFn::End => c.poly.take().map(|(mode, points)| Op::Poly {
            points,
            color: fg,
            filled: mode == FILL,
        }),
        _ => None,
    };
    if let Some(op) = op {
        c.ops.push(op);
        c.dirty = true;
    }
    0
}

/// The C string at `a` (up to 4 KiB), Latin-1.
fn zstr(mem: &dyn Memory, a: u32) -> String {
    let bytes = mem
        .bytes(a, 4096)
        .or_else(|| mem.bytes(a, 256))
        .unwrap_or_default();
    bytes
        .iter()
        .take_while(|b| **b != 0)
        .map(|b| *b as char)
        .collect()
}

/// A CD colour's red, green and blue (its top byte is alpha, which the
