        fn source_where(&self) -> Option<String> {
            let mut pos = self.var(st::TIN);
            let inside = |f: &reva_core::IncludeFrame, p: u32| (f.start..=f.end).contains(&p);
            let mut k = self.includes.iter().rposition(|f| inside(f, pos))?;
