            let cells: Vec<String> = below.chain(top).map(|v| (v as i32).to_string()).collect();
            Some(match cells.is_empty() {
                true => format!("stack ({depth})"),
                false => format!("stack ({depth}): {}", cells.join(" ")),
            })
